	copyEntered := make(chan struct{})
	var gateOnce sync.Once
	copier := session.WorkspaceCopier(func(ctx context.Context, _, destination string) error {
		gateOnce.Do(func() {
			close(copyEntered)
			select {
			case <-allowCopy:
			case <-ctx.Done():
			}
		})
