	if err != nil {
		t.Fatal(err)
	}
	recipientToken := tokenFromWorkspace()
	runner := NewOperationRunner(repo.Dir(), service)
	service.SetOperationRunner(runner)
	t.Cleanup(runner.Shutdown)
	inspection, err := service.GetSession(callerToken, recipientID)
	if err != nil || inspection.ActivationID == "" || !inspection.KankuroMCPEnabled {
		t.Fatalf("recipient inspection = %#v, %v", inspection, err)
	}
	requestID := uuid.NewString()
	result, err := service.SendMessage(
		context.Background(),
		callerToken,
		requestID,
		recipientID,
		inspection.ActivationID,
		"check the workspace",
	)
	if err != nil || result.State != OperationSucceeded || result.Result == nil || result.Result.MessageID == "" ||
		result.Result.Delivery != string(session.MessageSubmitted) {
		t.Fatalf("send result = %#v, %v", result, err)
	}
	retry, err := service.SendMessage(
		context.Background(),
		callerToken,
		requestID,
		recipientID,
		inspection.ActivationID,
		"check the workspace",
	)
	if err != nil || retry.ID != result.ID || retry.Result.MessageID != result.Result.MessageID {
		t.Fatalf("send retry = %#v, %v", retry, err)
	}
	if _, err = service.SendMessage(
		context.Background(),
		callerToken,
		requestID,
		recipientID,
		inspection.ActivationID,
		"different text",
	); err == nil {
		t.Fatal("changed send retry was accepted")
	}
	stored, err := service.GetMessage(callerToken, result.Result.MessageID)
	if err != nil || stored.Text != "check the workspace" {
		t.Fatalf("stored message = %#v, %v", stored, err)
	}
	if _, err = service.ReportReply(recipientToken, uuid.NewString(), result.Result.MessageID, "completed", "done"); err != nil {
		t.Fatalf("recipient without Dashboard Control could not report: %v", err)
	}
	page, err := service.GetReplies(context.Background(), callerToken, result.Result.MessageID, "", 50, 0)
	if err != nil || len(page.Items) != 1 || page.Items[0].Kind != "completed" {
		t.Fatalf("reply page = %#v, %v", page, err)
	}
	if err = manager.Kill(recipientID); err != nil {
		t.Fatal(err)
	}
	if err = removeSessionTest(service, recipientID); err != nil {
		t.Fatal(err)
	}
	if _, err = service.GetMessage(callerToken, result.Result.MessageID); err == nil {
		t.Fatal("recipient deletion kept message content")
	}
}

internal/app/command_race_internal_test..source:
package app

// TestCommandClosuresDoNotRaceCoordinator is a runtime backstop for invariant
// 1 (no tea.Cmd closure touches coordinator-goroutine state: c.views,
// c.preview, c.currentView, c.err, c.settings), in addition to the structural
// rule (refresher and sessionActions hold no *Coordinator) and the greps in
// project.md §6. It only means something under `go test -race`; without the
// race detector it merely checks that the flows still complete.
//
// How it works: for each message that returns commands, Update runs on the
// test goroutine (as it does in Bubble Tea), every returned command is then
// executed on its own goroutine (as Bubble Tea does), and meanwhile the test
// goroutine keeps *writing* the state those closures must not touch - through
// Update, which assigns into c.views, c.err, c.currentView and c.settings,
// not just reads. A closure that reads any of them is then an unsynchronised
// access the detector reports. The hammering has to write: two concurrent
// reads of a map are not a race.
//
// Limit: receiving a closure's result from the channel orders everything
// after it behind the closure, so a violation is only reported if a hammer
// write lands between the closure's read and that receive. runCommands
// therefore hammers for a whole slice before draining. That catches reads
// made early in a closure, including fast ones; a closure that reads state
// late, after other work or a delay, can still slip through. This is a
// backstop, not a proof.
//
// Can-fail check (redo it if you change the harness): the fast case is the
// one that matters, because it is what regressed before. In callbacks.go,
// wrap the command launchIDE returns in a closure that reads settings:
//
//	inner := c.actions.launchIDE(sessionID, c.settings.IDECommand)
//	return func() tea.Msg {
//		if c.settings.IDECommand == "planted" { return nil }
//		return inner()
//	}
//
// and this test must fail under -race (the "open IDE" case). Use the value
// in a condition: a bare `_ = c.settings.IDECommand` is a dead load the
// compiler can drop, which leaves the race detector nothing to see.

import (
	"context"
	"errors"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

// raceNoopMsg is a message no handler knows, so Update routes it to the
// current view and then assigns the result back into c.views - the map write
// a leaked closure read would race with.
type raceNoopMsg struct{}

type raceFixture struct {
	coord     *Coordinator
	sessionID string
}

func newRaceFixture(t *testing.T, killSession bool) raceFixture {
	t.Helper()
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	sm := newTestManager(t, repo.Dir(), repo)

	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); saveErr != nil {
		t.Fatalf("save workspace sources: %v", saveErr)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("list workspaces: %v (%d)", err, len(workspaces))
	}

	var first config.IDCard
	for _, name := range []string{"race-a", "race-b"} {
		created, createErr := repo.CreateIDCard(
			config.IDCard{Name: name, Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "default"},
		)
		if createErr != nil {
			t.Fatalf("create card %s: %v", name, createErr)
		}
		if first.ID == "" {
			first = created
		}
	}
	card := first

	service := api.New(repo, sm)
	sessionID, err := service.LaunchInDashboard(context.Background(), "default", card.ID)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	if killSession {
		if killErr := sm.Kill(sessionID); killErr != nil {
			t.Fatalf("kill: %v", killErr)
		}
	}

	c := NewCoordinator(repo, sm, service)
	c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	c.Update(messages.DashboardOpenRequestedMsg{Dashboard: config.Dashboard{ID: "default", Name: "Default", State: config.DashboardActive}})
	c.Update(c.refreshDataSeeded()())
	return raceFixture{coord: c, sessionID: sessionID}
}

// hammer writes coordinator-goroutine state through the public message path.
func hammer(c *Coordinator) {
	c.Update(raceNoopMsg{})
	c.Update(messages.ErrorMsg{Err: errors.New("hammer")})
	c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	c.Update(messages.SettingsSavedMsg{Settings: config.DefaultAppSettings(), DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	c.Update(messages.ScopedNavigateMsg{View: messages.ViewSettings, DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	_ = c.View()
	c.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: c.activeDashboard, Generation: c.viewGeneration})
	_ = c.View()
}

// spawnCommands executes cmd (unwrapping tea.BatchMsg) with every leaf on its
// own goroutine, sending each leaf's message to results.
func spawnCommands(cmd tea.Cmd, results chan<- tea.Msg) {
	if cmd == nil {
		return
	}
	go func() {
		msg := cmd()
		if batch, ok := msg.(tea.BatchMsg); ok {
			for _, sub := range batch {
				spawnCommands(sub, results)
			}
			return
		}
		if msg != nil {
			results <- msg
		}
	}()
}

// drainResults moves whatever is currently queued on results into got
// without blocking, and reports whether any of it satisfied want.
func drainResults(results <-chan tea.Msg, got []tea.Msg, want func(tea.Msg) bool) ([]tea.Msg, bool) {
	matched := false
	for {
		select {
		case m := <-results:
			got = append(got, m)
			matched = matched || (want != nil && want(m))
		default:
			return got, matched
		}
	}
}

// runCommands executes cmd concurrently (see spawnCommands) while hammering
// the coordinator on this goroutine, until want has seen a result (or, with a
// nil want, for minHammer). It returns every leaf message that arrived.
func runCommands(t *testing.T, c *Coordinator, cmd tea.Cmd, want func(tea.Msg) bool) []tea.Msg {
	t.Helper()
	const (
		minHammer   = 100 * time.Millisecond
		hammerSlice = 300 * time.Millisecond
		maxWait     = 3 * time.Second
	)
	results := make(chan tea.Msg, 64)
	spawnCommands(cmd, results)

	var got []tea.Msg
	seen := want == nil
	start := time.Now()
	for time.Since(start) < maxWait && (time.Since(start) < minHammer || !seen) {
		// Hammer for a whole slice before looking at results: receiving a
		// result orders everything after it behind the closure, so a write
		// must land between the closure's read and that receive. Draining
		// after every hammer() would miss any closure that returns fast.
		for slice := time.Now(); time.Since(slice) < hammerSlice; {
			hammer(c)
		}
		var matched bool
		got, matched = drainResults(results, got, want)
		seen = seen || matched
	}
	if !seen {
		t.Fatalf("expected command to produce the awaited message within %v; got %d messages: %v", maxWait, len(got), got)
	}
	return got
}

func TestCommandClosuresDoNotRaceCoordinator(t *testing.T) {
	key := func(s string) tea.KeyPressMsg { return tea.KeyPressMsg{Code: 0, Text: s} }
	isMsg := func(match func(tea.Msg) bool) func(tea.Msg) bool { return match }

	tests := []struct {
		name       string
		killedSess bool
		// run drives Update on the test goroutine and returns the command(s)
		// whose closures will then be executed concurrently.
		run  func(t *testing.T, f raceFixture) tea.Cmd
		want func(tea.Msg) bool
	}{
		{
			name: "idle tick",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(tickMsg(time.Now()))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SessionsRefreshedMsg); return ok }),
		},
		{
			name: "data refresh requested",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(messages.DataRefreshRequestedMsg{})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(configFingerprintMsg); return ok }),
		},
		{
			name: "dashboard list save",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				return f.coord.dashboardListCallbacks().Save("", "race dashboard", "")
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.DashboardMutationFinishedMsg); return ok }),
		},
		{
			name: "asynchronous session name",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				return f.coord.sessionLauncherCallbacks().OnSetNameAsync(f.sessionID, "race session")
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedSessionNamedMsg); return ok }),
		},
		{
			name: "scoped attachment readiness",
			run:  func(_ *testing.T, f raceFixture) tea.Cmd { return f.coord.requestAttach(f.sessionID) },
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedAttachReadyMsg); return ok }),
		},
		{
			name: "launch card (Enter on the cards pane)",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SessionLaunchCompletedMsg); return ok }),
		},
		{
			name: "preview request",
			run: func(t *testing.T, f raceFixture) tea.Cmd {
				_, cmd := f.coord.Update(messages.SessionPreviewRequestedMsg{SessionID: f.sessionID})
				if cmd == nil {
					t.Fatal("expected a live-output wait command: the preview should have subscribed")
				}
				return cmd
			},
		},
		{
			name: "kill the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("x"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedActionFinishedMsg); return ok }),
		},
		{
			name: "open IDE for the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("o"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedActionFinishedMsg); return ok }),
		},
		{
			name: "open terminal for the selected session",
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(
					messages.SettingsSavedMsg{
						Settings:    config.AppSettings{TerminalCommand: "/bin/true"},
						DashboardID: f.coord.activeDashboard,
						Generation:  f.coord.viewGeneration,
					},
				)
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(key("t"))
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.ScopedActionFinishedMsg); return ok }),
		},
		{
			name:       "relaunch a terminated session (Enter on the sessions pane)",
			killedSess: true,
			run: func(_ *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(tea.KeyPressMsg{Code: tea.KeyTab})
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.SessionAttachRequestedMsg); return ok }),
		},
		{
			name:       "switch agent on a terminated session",
			killedSess: true,
			run: func(t *testing.T, f raceFixture) tea.Cmd {
				f.coord.Update(
					messages.AgentSwitchRequestedMsg{
						SessionID:   f.sessionID,
						SessionName: "race",
						DashboardID: f.coord.activeDashboard,
						Generation:  f.coord.viewGeneration,
					},
				)
				if f.coord.CurrentView() != ViewAgentSwitch {
					t.Fatalf("expected the agent-switch view, got %v", f.coord.CurrentView())
				}
				// Refresh after navigating, or the switch view's list is
				// empty and OnSwitch never fires. Twice: see
				// TestPersistFailureWarningReachesViewOnBothPaths.
				f.coord.Update(f.coord.RefreshData()())
				f.coord.Update(f.coord.RefreshData()())
				_, cmd := f.coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
				return cmd
			},
			want: isMsg(func(m tea.Msg) bool { _, ok := m.(messages.AgentSwitchedMsg); return ok }),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			f := newRaceFixture(t, tt.killedSess)
			cmd := tt.run(t, f)
			if cmd == nil {
				t.Fatal("expected Update to return a command")
			}

			// Round 1: the commands Update returned, run concurrently.
			results := runCommands(t, f.coord, cmd, tt.want)

			// Round 2: feed the results back through Update the way Bubble
			// Tea would, and run whatever those return concurrently too.
			for _, msg := range results {
				_, next := f.coord.Update(msg)
				if next != nil {
					runCommands(t, f.coord, next, nil)
				}
			}
		})
	}
}

internal/app/conversation_choice_interna.source:
package app

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type coordinatorCodexDriver struct{ *driver.GenericCLIDriver }

func (d *coordinatorCodexDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	cfg.Driver = "cat"
	return d.GenericCLIDriver.Spawn(cfg)
}

//nolint:cyclop,gocognit,gocyclo,govet // Exercises refresh recovery for both relaunch and switch errors against real manager state.
func TestConversationChoiceRefreshesDriverAndRejectsStaleContext(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", err)
	}
	registry := driver.NewBuiltinRegistry()
	registry.Register("codex", func() driver.AgentDriver {
		return &coordinatorCodexDriver{GenericCLIDriver: driver.NewGenericCLIDriver()}
	})
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	card, err := repo.CreateIDCard(
		config.IDCard{
			DashboardID: "default",
			ID:          "conversation-card",
			Name:        "Conversation card",
			Driver:      "cat",
			WorkspaceID: workspaces[0].ID,
			MCPIDs:      []string{config.BuiltinMCPKankuro},
		},
	)
	if err != nil {
		t.Fatal(err)
	}
	service := api.New(repo, manager)
	sessionID, err := service.LaunchInDashboard(context.Background(), "default", card.ID)
	if err != nil {
		t.Fatal(err)
	}
	catSnapshot, _ := manager.GetSession(sessionID)
	if _, err := manager.RegisterConversation(
		readMCPToken(t, driver.MCPConfigPath(catSnapshot.WorkingDir)),
		"cat-native-id",
		"Cat conversation",
	); err != nil {
		t.Fatal(err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	card.Driver = "codex"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	if err := service.SwitchInDashboard(
		context.Background(), "default", sessionID, card.ID,
		session.ConversationChoice{New: true},
	); err != nil {
		t.Fatal(err)
	}
	codexSnapshot, _ := manager.GetSession(sessionID)
	if _, err := manager.RegisterConversation(
		readMCPToken(t, driver.MCPConfigPath(codexSnapshot.WorkingDir)),
		"codex-native-id",
		"Codex conversation",
	); err != nil {
		t.Fatal(err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}

	coord := NewCoordinator(repo, manager, service)
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	coord.Update(
		messages.DashboardOpenRequestedMsg{Dashboard: config.Dashboard{ID: "default", Name: "Default", State: config.DashboardActive}},
	)
	coord.Update(coord.refreshData()())
	request := coord.DashboardCallbacks().OnRelaunch(sessionID)
	if request == nil {
		t.Fatal("relaunch request returned no command")
	}
	coord.Update(request())
	choiceView := coord.Views()[ViewConversationChoice].(*views.ConversationChoiceView)
	choiceView.SetSize(80, 20)
	if selected, ok := choiceView.SelectedBinding(); !ok || selected.ID != "codex-native-id" {
		t.Fatalf("initial compatible selection = %#v, found=%v", selected, ok)
	}

	// An error-triggered refresh must re-read the destination driver and reselect
	// the saved conversation that is compatible with that refreshed driver.
	card.Driver = "cat"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	_, relaunchRefresh := coord.Update(messages.ErrorMsg{Err: errors.New("stale relaunch choice")})
	if relaunchRefresh == nil {
		t.Fatal("relaunch failure did not request refreshed context")
	}
	coord.Update(relaunchRefresh())
	selected, ok := choiceView.SelectedBinding()
	if !ok || selected.ID != "cat-native-id" || selected.Driver != "cat" {
		t.Fatalf("relaunch refresh selection = %#v, found=%v", selected, ok)
	}
	if !strings.Contains(choiceView.View(), "incompatible driver") {
		t.Fatal("picker did not mark the other driver's saved binding incompatible")
	}

	card.Driver = "codex"
	if _, err := repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
	_, switchRefresh := coord.Update(
		messages.AgentSwitchedMsg{
			DashboardID: "default",
			Generation:  coord.viewGeneration,
			SessionID:   sessionID,
			Err:         errors.New("stale switch choice"),
		},
	)
	if switchRefresh == nil {
		t.Fatal("switch failure did not request refreshed context")
	}
	coord.Update(switchRefresh())
	selected, ok = choiceView.SelectedBinding()
	if !ok || selected.ID != "codex-native-id" || selected.Driver != "codex" {
		t.Fatalf("switch refresh selection = %#v, found=%v", selected, ok)
	}

	preflight, err := service.PreflightCardDeletion("default", card.ID)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := service.ConfirmCardDeletion(
		context.Background(),
		"default",
		card.ID,
		preflight.Token,
		preflight.RequiresForeignConfirmation,
	); err != nil {
		t.Fatal(err)
	}
	coord.Update(coord.refreshData()())
	if !strings.Contains(choiceView.View(), "destination card was removed") {
		t.Fatalf("removed destination did not leave an actionable picker error: %s", choiceView.View())
	}
	if _, cmd := choiceView.Update(tea.KeyPressMsg{Code: tea.KeyEnter}); cmd != nil {
		t.Fatal("stale picker submitted an activation after its destination card disappeared")
	}
	if err := manager.Remove(sessionID); err != nil {
		t.Fatal(err)
	}
	coord.Update(coord.refreshSessions()())
	if !strings.Contains(choiceView.View(), "selected session was removed") {
		t.Fatalf("removed session did not leave an actionable picker error: %s", choiceView.View())
	}
}

func readMCPToken(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var config struct {
		MCPServers map[string]struct {
			Headers map[string]string `json:"headers"`
		} `json:"mcpServers"`
	}
	if unmarshalErr := json.Unmarshal(data, &config); unmarshalErr != nil {
		t.Fatal(unmarshalErr)
	}
	return strings.TrimPrefix(config.MCPServers["kankuro"].Headers["Authorization"], "Bearer ")
}

