package app_test

import (
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/app"
)

func TestDashboardListRequiresExplicitQuit(t *testing.T) {
	coord := newBannerCoordinator(t)
	_, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEsc})
	for _, msg := range collectMsgs(t, cmd) {
		coord.Update(msg)
	}
	if coord.CurrentView() != app.ViewDashboardList {
		t.Fatal("Escape did not return to the dashboard list")
	}
	for _, size := range [][2]int{{120, 40}, {40, 10}, {120, 40}} {
		coord.Update(tea.WindowSizeMsg{Width: size[0], Height: size[1]})
		for _, key := range []tea.KeyPressMsg{
			{Code: tea.KeyEsc}, {Code: tea.KeyEsc}, {Code: 'c', Mod: tea.ModCtrl},
		} {
			_, cmd = coord.Update(key)
			for _, msg := range collectMsgs(t, cmd) {
				if _, quit := msg.(tea.QuitMsg); quit {
					t.Fatalf("key %v quit the dashboard list", key)
				}
				coord.Update(msg)
			}
			if coord.CurrentView() != app.ViewDashboardList {
				t.Fatalf("key %v left the dashboard list", key)
			}
		}
	}
	_, cmd = coord.Update(tea.KeyPressMsg{Text: "q", Code: 'q'})
	if cmd == nil {
		t.Fatal("q returned no quit command")
	}
	if _, quit := cmd().(tea.QuitMsg); !quit {
		t.Fatal("q did not quit the dashboard list")
	}
}

internal/app/delete_card_guard_test.go.source:
package app_test

import (
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

// Card deletion always requires a preflight and confirmation, including when a
// session references the card. The existing session must survive deletion.
//
//nolint:gocognit,govet // Cover both deletion cases and each operation error.
func TestOnDeleteCardPreflightsAndPreservesReferencedSession(t *testing.T) {
	for _, referenced := range []bool{false, true} {
		t.Run(map[bool]string{false: "unreferenced", true: "referenced"}[referenced], func(t *testing.T) {
			repo, err := newCurrentRepository(t.TempDir())
			if err != nil {
				t.Fatal(err)
			}
			sm := newTestManager(t, repo.Dir(), repo)
			if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("workspaces: %v %v", workspaces, err)
			}
			card, err := createCurrentCard(repo, config.IDCard{Name: "Card", Driver: "cat", WorkspaceID: workspaces[0].ID})
			if err != nil {
				t.Fatal(err)
			}
			var sessionID string
			if referenced {
				sessionID, err = launchCurrentSession(repo, sm, card)
				if err != nil {
					t.Fatal(err)
				}
			}
			coord := newOpenedCoordinator(repo, sm)
			callbacks := coord.DashboardCallbacks()
			cmd, err := callbacks.OnDeleteCard(card.ID)
			if err != nil || cmd == nil {
				t.Fatalf("prepare deletion: %v", err)
			}
			prepared, ok := cmd().(messages.CardDeletionPreparedMsg)
			if !ok || prepared.Err != nil || prepared.Token == "" {
				t.Fatalf("preflight: %#v", prepared)
			}
			cards, err := repo.ListIDCards()
			if err != nil || len(cards) != 1 {
				t.Fatalf("preflight changed cards: %v %v", cards, err)
			}
			result, ok := callbacks.OnConfirmCardDeletion(card.ID, prepared.Token, prepared.RequiresForeignConfirmation)().(messages.ScopedActionFinishedMsg)
			if !ok || result.Err != nil {
				t.Fatalf("confirm: %#v", result)
			}
			cards, err = repo.ListIDCards()
			if err != nil || len(cards) != 0 {
				t.Fatalf("card remains: %v %v", cards, err)
			}
			if referenced {
				if _, ok := sm.GetSession(sessionID); !ok {
					t.Fatal("referenced session was removed")
				}
			}
		})
	}
}

internal/app/error_banner_test.go.source:
package app_test

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/app"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

func newBannerCoordinator(t *testing.T) *app.Coordinator {
	t.Helper()
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	coord := newScopedCoordinator(repo, sm)
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	openDefaultDashboard(coord)
	return coord
}

func assertBannerShown(t *testing.T, coord *app.Coordinator, want error, context string) {
	t.Helper()
	if coord.Err() == nil {
		t.Fatalf("%s: expected the error banner to be set, got nil", context)
	}
	if !strings.Contains(coord.View(), want.Error()) {
		t.Fatalf("%s: expected View() to contain %q", context, want.Error())
	}
}

// Navigation must preserve an error regardless of batch delivery order.
func TestErrorSurvivesNavigationInEitherOrder(t *testing.T) {
	bannerErr := errors.New("persist failed: disk on fire")

	t.Run("error then navigate", func(t *testing.T) {
		coord := newBannerCoordinator(t)
		coord.Update(messages.ErrorMsg{Err: bannerErr})
		coord.Update(messages.ScopedNavigateMsg{View: messages.ViewSettings, DashboardID: "default", Generation: 1})
		if coord.CurrentView() != app.ViewSettings {
			t.Fatalf("expected navigation to have happened, got view %v", coord.CurrentView())
		}
		assertBannerShown(t, coord, bannerErr, "error then navigate")
	})

	t.Run("navigate then error", func(t *testing.T) {
		coord := newBannerCoordinator(t)
		coord.Update(messages.ScopedNavigateMsg{View: messages.ViewSettings, DashboardID: "default", Generation: 1})
		coord.Update(messages.ErrorMsg{Err: bannerErr})
		if coord.CurrentView() != app.ViewSettings {
			t.Fatalf("expected navigation to have happened, got view %v", coord.CurrentView())
		}
		assertBannerShown(t, coord, bannerErr, "navigate then error")
	})
}

// TestKeyPressClearsBanner: the banner goes away when the user acts.
func TestKeyPressClearsBanner(t *testing.T) {
	coord := newBannerCoordinator(t)
	coord.Update(messages.ErrorMsg{Err: errors.New("stale")})
	if coord.Err() == nil {
		t.Fatal("precondition: banner should be set")
	}

	coord.Update(tea.KeyPressMsg{Code: 0, Text: "j"})

	if coord.Err() != nil {
		t.Fatalf("expected a keypress to clear the banner, got: %v", coord.Err())
	}
}

// TestKeyPressThenErrorShowsNewError: an error that is the result of a
// keypress arrives as a later message, so clearing on the keypress must not
// hide it.
func TestKeyPressThenErrorShowsNewError(t *testing.T) {
	coord := newBannerCoordinator(t)
	coord.Update(messages.ErrorMsg{Err: errors.New("old")})

	fresh := errors.New("fresh failure")
	coord.Update(tea.KeyPressMsg{Code: 0, Text: "j"})
	coord.Update(messages.ErrorMsg{Err: fresh})

	assertBannerShown(t, coord, fresh, "keypress then error")
}

