	}
	coord.Update(coord.RefreshData()())
	cards := dashboard.Cards()
	if len(cards) != 1 || cards[0].ID != card.ID || cards[0].Name != "Propagated" {
		t.Fatalf("dashboard cards: %+v", cards)
	}
	card.Name = "Updated"
	if _, err = repo.UpdateIDCard(card); err != nil {
		t.Fatal(err)
	}
