package app

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

//nolint:gocognit // Exercise all refresh producers through the same failure and recovery scenario.
func TestScopedRefreshPreservesDataOnInventoryFailure(t *testing.T) {
	for _, kind := range []string{"full", "sessions", "config"} {
		t.Run(kind, func(t *testing.T) {
			root := t.TempDir()
			if err := configstartup.PrepareStartup(root); err != nil {
				t.Fatal(err)
			}
			repo, err := config.NewFileRepository(root)
			if err != nil {
				t.Fatal(err)
			}
			if err = os.WriteFile(
				filepath.Join(repo.Dir(), config.DashboardsFilename),
				[]byte("schema_version: 1\ndashboards:\n  - {id: a, name: A, state: active}\n"),
				0600,
			); err != nil {
				t.Fatal(err)
			}
			if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("workspaces: %v %v", workspaces, err)
			}
			card, err := repo.CreateIDCard(config.IDCard{Name: "card", Driver: "cat", WorkspaceID: workspaces[0].ID, DashboardID: "a"})
			if err != nil {
				t.Fatal(err)
			}
			manager := newTestManager(t, repo.Dir(), repo)
			service := api.New(repo, manager)
			id, err := service.LaunchInDashboard(context.Background(), "a", card.ID)
			if err != nil {
				t.Fatal(err)
			}
			c := NewCoordinator(repo, manager, service)
			c.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
			c.Update(
				messages.DashboardOpenRequestedMsg{
					Dashboard:  config.Dashboard{ID: "a", Name: "A", State: config.DashboardActive},
					Generation: c.viewGeneration,
				},
			)
			c.Update(c.refreshData()())
			dashboard := c.views[ViewDashboard].(*views.Dashboard)
			if len(dashboard.Cards()) != 1 || len(dashboard.Sessions()) != 1 {
				t.Fatalf("initial cards/sessions: %v %v", dashboard.Cards(), dashboard.Sessions())
			}
			path := filepath.Join(repo.Dir(), config.IDCardsFilename)
			raw, err := os.ReadFile(path)
			if err != nil {
				t.Fatal(err)
			}
			if err = os.WriteFile(path, []byte("invalid: ["), 0600); err != nil {
				t.Fatal(err)
			}
			var cmd tea.Cmd
			switch kind {
			case "full":
				cmd = c.refreshData()
			case "sessions":
				cmd = c.refreshSessions()
			default:
				cmd = c.maybeRefreshConfig()
			}
			c.Update(cmd())
			if c.err == nil || len(dashboard.Cards()) != 1 || dashboard.Cards()[0].ID != card.ID || len(dashboard.Sessions()) != 1 ||
				dashboard.Sessions()[0].ID != id {
				t.Fatalf("failure cleared data: error=%v cards=%v sessions=%v", c.err, dashboard.Cards(), dashboard.Sessions())
			}
			if _, err = service.LaunchInDashboard(context.Background(), "a", card.ID); err == nil {
				t.Fatal("corrupt inventory allowed launch")
			}
			if err = os.WriteFile(path, raw, 0600); err != nil {
				t.Fatal(err)
			}
			c.Update(c.refreshData()())
			if len(dashboard.Cards()) != 1 || len(dashboard.Sessions()) != 1 {
				t.Fatal("data did not recover")
			}
		})
	}
}

func TestScopedRefreshReturnsExplicitEmptyInventory(t *testing.T) {
	root := t.TempDir()
	if err := configstartup.PrepareStartup(root); err != nil {
		t.Fatal(err)
	}
	repo, err := config.NewFileRepository(root)
	if err != nil {
		t.Fatal(err)
	}
	manager := newTestManager(t, repo.Dir(), repo)
	service := api.New(repo, manager)
	r := refresher{repo: repo, sessions: manager}
	full := unwrapRefresh(r.scopedFull(service, "default", 1, "")()).(messages.DataLoadedMsg)
	if full.Err != nil || full.Cards == nil || full.Sessions == nil || len(full.Cards) != 0 || len(full.Sessions) != 0 {
		t.Fatalf("empty full refresh: %+v", full)
	}
	tick := r.scopedSessions(service, "default", 1, "")().(messages.SessionsRefreshedMsg)
	if tick.Err != nil || tick.Cards == nil || tick.Sessions == nil || len(tick.Cards) != 0 || len(tick.Sessions) != 0 {
		t.Fatalf("empty session refresh: %+v", tick)
	}
	changed := r.scopedConfigIfChanged(service, "default", 1, nil)().(configFingerprintMsg)
	if changed.data == nil || changed.data.Err != nil || changed.data.Cards == nil || len(changed.data.Cards) != 0 {
		t.Fatalf("empty config refresh: %+v", changed)
	}
}

internal/app/session_actions_registry_te.source:
package app_test

import (
	"errors"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
)

type capabilityFailingRepository struct {
	config.Repository

	cardErr         error
	cardsRead       int
	capabilityReads int
}

func (r *capabilityFailingRepository) ListIDCards() ([]config.IDCard, error) {
	r.cardsRead++
	if r.cardErr != nil {
		return nil, r.cardErr
	}
	return r.Repository.ListIDCards()
}

func (r *capabilityFailingRepository) capabilityFailure() error {
	r.capabilityReads++
	return errors.New("capability registry unavailable")
}

func (r *capabilityFailingRepository) ListSkills() ([]config.Skill, error) {
	return nil, r.capabilityFailure()
}

func (r *capabilityFailingRepository) ListPersonas() ([]config.Persona, error) {
	return nil, r.capabilityFailure()
}

func (r *capabilityFailingRepository) ListMCPs() ([]config.MCPServer, error) {
	return nil, r.capabilityFailure()
}

func TestRelaunchLoadsCardWithoutCapabilityRegistries(t *testing.T) {
	repo, repoErr := newCurrentRepository(t.TempDir())
	if repoErr != nil {
		t.Fatal(repoErr)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, workspaceErr := repo.ListWorkspaces()
	if workspaceErr != nil {
		t.Fatal(workspaceErr)
	}
	card, cardErr := createCurrentCard(repo, config.IDCard{Name: "relaunch registry", Driver: "cat", WorkspaceID: workspaces[0].ID})
	if cardErr != nil {
		t.Fatal(cardErr)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	sid, launchErr := launchCurrentSession(repo, sm, card)
	if launchErr != nil {
		t.Fatal(launchErr)
	}
	if err := sm.Kill(sid); err != nil {
		t.Fatal(err)
	}

	failingRepo := &capabilityFailingRepository{Repository: repo}
	coord := newOpenedCoordinator(failingRepo, sm)
	var result tea.Msg
	for _, msg := range collectMsgs(t, coord.DashboardCallbacks().OnRelaunch(sid)) {
		result = msg
	}
	if _, ok := result.(messages.SessionAttachRequestedMsg); !ok {
		t.Fatalf("relaunch result = %T (%+v), want SessionAttachRequestedMsg", result, result)
	}
	if failingRepo.cardsRead == 0 || failingRepo.capabilityReads != 0 {
		t.Fatalf(
			"relaunch reads: cards=%d capabilities=%d, want at least one card read and no capability reads",
			failingRepo.cardsRead,
			failingRepo.capabilityReads,
		)
	}
	if err := sm.Kill(sid); err != nil {
		t.Fatal(err)
	}
}

func TestCardAndCapabilityLookupFailuresRemainVisible(t *testing.T) {
	repo, repoErr := newCurrentRepository(t.TempDir())
	if repoErr != nil {
		t.Fatal(repoErr)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, workspaceErr := repo.ListWorkspaces()
	if workspaceErr != nil {
		t.Fatal(workspaceErr)
	}
	card, cardErr := createCurrentCard(repo, config.IDCard{Name: "lookup", Driver: "cat", WorkspaceID: workspaces[0].ID})
	if cardErr != nil {
		t.Fatal(cardErr)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	failingRepo := &capabilityFailingRepository{Repository: repo}
	coord := newOpenedCoordinator(failingRepo, sm)
	sid, launchErr := launchCurrentSession(repo, sm, card)
	if launchErr != nil {
		t.Fatal(launchErr)
	}
	if err := sm.Kill(sid); err != nil {
		t.Fatal(err)
	}

	failingRepo.cardErr = errors.New("cards unavailable")
	msg := collectMsgs(t, coord.DashboardCallbacks().OnRelaunch(sid))
	if len(msg) != 1 {
		t.Fatalf("card read failure messages = %v", msg)
	}
	errMsg, ok := msg[0].(messages.ScopedActionFinishedMsg)
	if !ok || !strings.Contains(errMsg.Err.Error(), "cards unavailable") {
		t.Fatalf("card read failure = %T (%+v)", msg[0], msg[0])
	}
	failingRepo.cardErr = nil
	failingRepo.Repository = repositoryWithoutCard{Repository: repo, excludedID: card.ID}
	msg = collectMsgs(t, coord.DashboardCallbacks().OnRelaunch(sid))
	errMsg, ok = msg[0].(messages.ScopedActionFinishedMsg)
	if !ok || errMsg.Err == nil {
		t.Fatalf("missing card result = %T (%+v)", msg[0], msg[0])
	}

	failingRepo.Repository = repo
	failingRepo.capabilityReads = 0
	launchMsgs := collectMsgs(t, coord.DashboardCallbacks().OnLaunchCard(card))
	if !containsCapabilityError(launchMsgs) || failingRepo.capabilityReads == 0 {
		t.Fatalf("launch did not propagate capability failure: %v", launchMsgs)
	}
	switchMsgs := collectMsgs(t, coord.AgentSwitchCallbacks().OnSwitch(sid, card.ID, ""))
	if !containsSwitchCapabilityError(switchMsgs) || failingRepo.capabilityReads == 0 {
		t.Fatalf("switch did not propagate capability failure: %v", switchMsgs)
	}
	if err := sm.Remove(sid); err != nil {
		t.Fatal(err)
	}
}

type repositoryWithoutCard struct {
	config.Repository

	excludedID string
}

func (r repositoryWithoutCard) ListIDCards() ([]config.IDCard, error) {
	cards, err := r.Repository.ListIDCards()
	if err != nil {
		return nil, err
	}
	out := cards[:0]
	for _, card := range cards {
		if card.ID != r.excludedID {
			out = append(out, card)
		}
	}
	return out, nil
}

func containsCapabilityError(msgs []tea.Msg) bool {
	for _, msg := range msgs {
		if launch, ok := msg.(messages.SessionLaunchCompletedMsg); ok &&
			launch.Err != nil && strings.Contains(launch.Err.Error(), "list skills: capability registry unavailable") {
			return true
		}
	}
	return false
}

func containsSwitchCapabilityError(msgs []tea.Msg) bool {
	for _, msg := range msgs {
		if switched, ok := msg.(messages.AgentSwitchedMsg); ok && switched.Err != nil &&
			strings.Contains(switched.Err.Error(), "list skills: capability registry unavailable") {
			return true
		}
	}
	return false
}

internal/app/session_warning_test.go.source:
package app_test

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/app"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

// collectMsgs executes cmd, recursing into tea.BatchMsg, and returns every
// leaf message it produces. It does not chain into commands returned by
// Update itself: the flows under test only need the messages a callback's
// own Cmd produces, not whatever those in turn trigger (e.g. an actual PTY
// attach, which shows up here as an opaque internal execMsg we don't need to
// unpack further).
func collectMsgs(t *testing.T, cmd tea.Cmd) []tea.Msg {
	t.Helper()
	if cmd == nil {
		return nil
	}
	msg := cmd()
	if msg == nil {
		return nil
	}
	if batch, ok := msg.(tea.BatchMsg); ok {
		var out []tea.Msg
		for _, c := range batch {
			out = append(out, collectMsgs(t, c)...)
		}
		return out
	}
	return []tea.Msg{msg}
}

// drive executes the command batch and delivers each leaf message once. It does not
// execute commands returned by Update, which may block on a PTY or subscription.
func drive(t *testing.T, coord *app.Coordinator, cmd tea.Cmd) {
	t.Helper()
	for _, msg := range collectMsgs(t, cmd) {
		coord.Update(msg)
	}
}

// permute calls fn once for every permutation of msgs (Heap's algorithm).
// Exercise every delivery order because tea.Batch does not guarantee one.
func permute(msgs []tea.Msg, fn func([]tea.Msg)) {
	n := len(msgs)
	cur := make([]tea.Msg, n)
	copy(cur, msgs)
	var generate func(k int)
	generate = func(k int) {
		if k == 1 {
			fn(cur)
			return
		}
		for i := range k {
			generate(k - 1)
			if k%2 == 0 {
				cur[i], cur[k-1] = cur[k-1], cur[i]
			} else {
				cur[0], cur[k-1] = cur[k-1], cur[0]
			}
		}
	}
	generate(n)
}

// Persistence warnings must reach the error banner on both relaunch and switch.
func TestPersistFailureWarningReachesViewOnBothPaths(t *testing.T) {
	t.Run("relaunch", func(t *testing.T) {
		repo, sm, sessionsDir := newPersistFailureFixture(t)
		wd := t.TempDir()
		_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
		workspaces, _ := repo.ListWorkspaces()

		card, errCreate := createCurrentCard(repo, config.IDCard{
			Name:        "relaunch-warning",
			Driver:      "cat",
			WorkspaceID: workspaces[0].ID,
		})
		if errCreate != nil {
			t.Fatalf("create card: %v", errCreate)
		}

		sessionID, errLaunch := launchCurrentSession(repo, sm, card)
		if errLaunch != nil {
			t.Fatalf("launch: %v", errLaunch)
		}
		if errKill := sm.Kill(sessionID); errKill != nil {
			t.Fatalf("kill: %v", errKill)
		}
		time.Sleep(50 * time.Millisecond)

		restore := makeSessionsDirReadOnly(t, sessionsDir)
		defer restore()

		coord := newOpenedCoordinator(repo, sm)
		coord.Init()

		cmd := coord.DashboardCallbacks().OnRelaunch(sessionID)
		msgs := collectMsgs(t, cmd)
		defer func() {
			restore()
			_ = sm.Kill(sessionID)
		}()

		assertWarningSurvivesEveryOrder(t, repo, sm, msgs, "relaunch")
	})

	t.Run("switch", func(t *testing.T) {
		repo, sm, sessionsDir := newPersistFailureFixture(t)
		wd := t.TempDir()
		_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
		workspaces, _ := repo.ListWorkspaces()

		card, errCreate := createCurrentCard(repo, config.IDCard{
			Name:        "switch-warning-a",
			Driver:      "cat",
			WorkspaceID: workspaces[0].ID,
		})
		if errCreate != nil {
			t.Fatalf("create card: %v", errCreate)
		}
		card2, errCreate2 := createCurrentCard(repo, config.IDCard{
			Name:        "switch-warning-b",
			Driver:      "cat",
			WorkspaceID: workspaces[0].ID,
		})
		if errCreate2 != nil {
			t.Fatalf("create card2: %v", errCreate2)
		}

		sessionID, errLaunch := launchCurrentSession(repo, sm, card)
		if errLaunch != nil {
			t.Fatalf("launch: %v", errLaunch)
		}
		if errKill := sm.Kill(sessionID); errKill != nil {
			t.Fatalf("kill: %v", errKill)
		}
		time.Sleep(50 * time.Millisecond)

		restore := makeSessionsDirReadOnly(t, sessionsDir)
		defer restore()

		coord := newOpenedCoordinator(repo, sm)
		coord.Init()

		cmd := coord.AgentSwitchCallbacks().OnSwitch(sessionID, card2.ID, card2.Driver)
		msgs := collectMsgs(t, cmd)
		defer func() {
			restore()
			_ = sm.Kill(sessionID)
		}()

		assertWarningSurvivesEveryOrder(t, repo, sm, msgs, "switch")
	})
}

// Switching through the event loop must preserve the dashboard model. Callback-only
// tests cannot exercise the coordinator's model write-back.
func TestAgentSwitchDoesNotClobberDashboardView(t *testing.T) {
	repo, sm, _ := newPersistFailureFixture(t)
	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	card, errCreate := createCurrentCard(repo, config.IDCard{
		Name:        "clobber-a",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	})
	if errCreate != nil {
		t.Fatalf("create card: %v", errCreate)
	}
	card2, errCreate2 := createCurrentCard(repo, config.IDCard{
		Name:        "clobber-b",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	})
	if errCreate2 != nil {
		t.Fatalf("create card2: %v", errCreate2)
	}

	sessionID, errLaunch := launchCurrentSession(repo, sm, card)
	if errLaunch != nil {
		t.Fatalf("launch: %v", errLaunch)
	}
	if errKill := sm.Kill(sessionID); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}
	time.Sleep(50 * time.Millisecond)
	defer func() { _ = sm.Kill(sessionID) }()

	coord := newOpenedCoordinator(repo, sm)
	coord.Init()

	// Give every view a real size: AgentSwitchView's list needs a non-zero
	// size for SelectedItem() to return anything.
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})

	// Navigate to the switch view first, THEN refresh. Refreshing before
	// navigating (or not at all) leaves AgentSwitchView's card list empty,
	// SelectedItem() returns nil, OnSwitch never runs, and the test would
	// pass for the wrong reason.
	coord.Update(messages.AgentSwitchRequestedMsg{SessionID: sessionID, SessionName: card.Name, DashboardID: "default", Generation: 1})
	if coord.CurrentView() != app.ViewAgentSwitch {
		t.Fatalf("expected to be on ViewAgentSwitch, got %v", coord.CurrentView())
	}
	coord.Update(coord.RefreshData()())

	// Cards are listed alphabetically by name (repo.ListIDCards), so
	// "clobber-a" (the session's current card) sits at index 0. Move down
	// once to select "clobber-b" - selecting the already-active card would
	// make SwitchAgent's CardID assertion below trivially true.
	coord.Update(tea.KeyPressMsg{Code: tea.KeyDown})

	// Run the actual switch command and its resulting messages through the event loop.
	_, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	drive(t, coord, cmd)

	// The switch must have actually run before this test's result means
	// anything - otherwise a no-op Enter would pass for the wrong reason too.
	sess, ok := sm.GetSession(sessionID)
	if !ok {
		t.Fatalf("session not found after switch")
	}
	if sess.CardID != card2.ID {
		t.Fatalf("expected SwitchAgent to have run (CardID=%s), got CardID=%s", card2.ID, sess.CardID)
	}
	if sess.Status != session.StatusRunning && sess.Status != session.StatusWaiting {
		t.Fatalf("expected the switched session to be running, got status=%s", sess.Status)
	}

	coord.Update(messages.ScopedNavigateMsg{View: messages.ViewDashboard, DashboardID: "default", Generation: 1})
	if coord.CurrentView() != app.ViewDashboard {
		t.Fatalf("expected to be back on ViewDashboard, got %v", coord.CurrentView())
	}
	if strings.Contains(coord.View(), "Switch Agent") {
		t.Fatalf("dashboard slot was overwritten with the AgentSwitchView: %q", coord.View())
	}
	if _, isDashboard := coord.Views()[app.ViewDashboard].(*views.Dashboard); !isDashboard {
		t.Fatalf("c.views[ViewDashboard] is no longer a *views.Dashboard")
	}
}

func newPersistFailureFixture(t *testing.T) (config.Repository, *session.Manager, string) {
	t.Helper()
	repo, errRepo := newCurrentRepository(t.TempDir())
	if errRepo != nil {
		t.Fatalf("new repo: %v", errRepo)
	}
	sm := newTestManager(t, repo.Dir(), repo)
	sessionsDir := filepath.Join(repo.Dir(), "sessions")
	return repo, sm, sessionsDir
}

// makeSessionsDirReadOnly strips write permission from the sessions directory
// so the next session save fails deterministically. It has to be the
// directory, not the record: records are written with temp-file + rename,
// which replaces the target whatever its own mode is. Returns a restore func
// to put permissions back (idempotent, safe to call from a defer even after
// an earlier explicit call).
func makeSessionsDirReadOnly(t *testing.T, sessionsDir string) func() {
	t.Helper()
	if os.Geteuid() == 0 {
		t.Skip("running as root: file permissions are not enforced")
	}
	if err := os.Chmod(sessionsDir, 0o500); err != nil {
		t.Fatalf("chmod: %v", err)
	}
	return func() {
		_ = os.Chmod(sessionsDir, 0o700)
	}
}

// assertWarningSurvivesEveryOrder replays msgs, in every possible order,
// against a fresh Coordinator each time, and requires the persist-failure
// warning to be visible after every single ordering. tea.Batch gives no
// delivery-order guarantee, so anything less than "every order" leaves the
// warning vulnerable to command scheduling.
func assertWarningSurvivesEveryOrder(t *testing.T, repo config.Repository, sm *session.Manager, msgs []tea.Msg, label string) {
	t.Helper()
	if len(msgs) == 0 {
		t.Fatalf("%s: expected at least one message from the callback's command", label)
	}

	tested := 0
	permute(msgs, func(order []tea.Msg) {
		tested++
		coord := newOpenedCoordinator(repo, sm)
		coord.Init()
		for _, m := range order {
			coord.Update(m)
		}

		if coord.Err() == nil {
			t.Errorf("%s: order %v: expected coord.Err() to carry the persist-failure warning, got nil", label, order)
			return
		}
		if !errors.Is(coord.Err(), session.ErrPersistFailed) {
			t.Errorf("%s: order %v: expected coord.Err() to wrap session.ErrPersistFailed, got: %v", label, order, coord.Err())
			return
		}
		if !strings.Contains(coord.View(), "could not be saved") {
			t.Errorf("%s: order %v: expected the rendered view to contain the warning, got: %q", label, order, coord.View())
		}
	})
	if tested == 0 {
		t.Fatalf("%s: permute never invoked fn", label)
	}
}

internal/app/settings_error_test.go.source:
package app_test

import (
	"errors"
	"reflect"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/BlackGiack/kankuro/internal/app"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/messages"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

type settingsFailingRepository struct {
	config.Repository

	err       error
	attempted config.AppSettings
}

func (r *settingsFailingRepository) SaveAppSettings(settings config.AppSettings) error {
	r.attempted = settings
	return r.err
}

func TestSettingsSaveFailureRemainsVisible(t *testing.T) {
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	before, err := repo.GetAppSettings()
	if err != nil {
		t.Fatal(err)
	}
	failure := errors.New("settings disk unavailable")
	failing := &settingsFailingRepository{Repository: repo, err: failure}
	coord := newOpenedCoordinator(failing, newTestManager(t, repo.Dir(), repo))
	coord.Update(tea.WindowSizeMsg{Width: 120, Height: 40})
	drive(t, coord, coord.NavigateTo(app.ViewSettings))
	coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	view := coord.Views()[app.ViewSettings].(*views.SettingsView)
	view.Input().SetValue("changed-editor")
	_, cmd := coord.Update(tea.KeyPressMsg{Code: tea.KeyEnter})
	if cmd == nil {
		t.Fatal("save produced no command")
	}
	var results int
	for _, msg := range collectMsgs(t, cmd) {
		if saved, ok := msg.(messages.SettingsSavedMsg); ok {
			results++
			if !errors.Is(saved.Err, failure) {
				t.Fatalf("save error: %v", saved.Err)
			}
		}
		coord.Update(msg)
	}
	if results != 1 || failing.attempted.IDECommand != "changed-editor" {
		t.Fatalf("save was not executed: results=%d settings=%+v", results, failing.attempted)
	}
	assertBannerShown(t, coord, failure, "asynchronous settings failure")
	if coord.CurrentView() != app.ViewSettings || view.Mode() != views.SettingsModeDisplay || view.Input().Value() != "changed-editor" {
		t.Fatal("failed save lost settings view or edited value")
	}
	after, err := repo.GetAppSettings()
	if err != nil || !reflect.DeepEqual(before, after) {
		t.Fatalf("failed save changed persisted settings: %+v %v", after, err)
	}
	coord.Update(messages.ClearErrorMsg{})
	if coord.Err() != nil {
		t.Fatal("banner did not clear")
	}
}

internal/app/size_guard_test.go.source:
package app_test

import (
	"fmt"
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/app"
	"github.com/BlackGiack/kankuro/internal/ui/uitest"
	"github.com/BlackGiack/kankuro/internal/ui/views"
)

// Below the minimum size, render an exact terminal-sized notice and ignore action keys.
// Resizing to a supported size restores the active view.

func newSizedCoordinator(t *testing.T, w, h int) *app.Coordinator {
	t.Helper()
	coord := newBannerCoordinator(t)
	coord.Update(tea.WindowSizeMsg{Width: w, Height: h})
	return coord
}

func TestCoordinatorTooSmallScreenIsExact(t *testing.T) {
	coord := newBannerCoordinator(t)
	for w := 1; w <= views.MinTerminalWidth+5; w++ {
		for h := 1; h <= views.MinTerminalHeight+3; h++ {
			coord.Update(tea.WindowSizeMsg{Width: w, Height: h})
			if w >= views.MinTerminalWidth && h >= views.MinTerminalHeight {
				if strings.Contains(coord.View(), "Terminal too small") {
					t.Fatalf("%dx%d is large enough but shows the notice", w, h)
				}
				continue
			}
			out := coord.View()
			label := fmt.Sprintf("%dx%d", w, h)
			uitest.AssertExactRect(t, out, w, h, label)
			if h >= 2 && w >= 21 && !strings.Contains(ansi.Strip(out), "have") {
				t.Errorf("%s: the notice does not say the terminal's size:\n%s", label, ansi.Strip(out))
			}
		}
	}
}

func TestCoordinatorTooSmallScreenText(t *testing.T) {
	coord := newSizedCoordinator(t, 60, 20)
	if got := ansi.Strip(coord.View()); !strings.Contains(got, "Terminal too small: need 80×24, have 60×20") {
		t.Errorf("notice text wrong:\n%s", got)
	}
}

func TestCoordinatorDropsKeysWhenTooSmall(t *testing.T) {
	for _, size := range [][2]int{{79, 24}, {80, 23}, {40, 10}} {
		coord := newSizedCoordinator(t, size[0], size[1])
		before := coord.CurrentView()
		for _, key := range []tea.KeyPressMsg{
			{Code: 0, Text: "n"}, {Code: tea.KeyEnter}, {Code: tea.KeyTab}, {Code: tea.KeyBackspace}, {Code: 0, Text: "c"},
		} {
			if _, cmd := coord.Update(key); cmd != nil {
				t.Errorf("%v: key %v returned a command while too small", size, key)
			}
			if coord.CurrentView() != before {
				t.Fatalf("%v: key %v changed the view to %v", size, key, coord.CurrentView())
			}
		}
	}
}

func TestDashboardListDropsKeysWhenTooSmall(t *testing.T) {
	repo, err := newCurrentRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	coord := newScopedCoordinator(repo, newTestManager(t, repo.Dir(), repo))
	coord.Update(tea.WindowSizeMsg{Width: 40, Height: 10})
	before := coord.CurrentView()
	uitest.AssertExactRect(t, coord.View(), 40, 10, "dashboard list")
	for _, key := range []tea.KeyPressMsg{{Code: 0, Text: "n"}, {Code: tea.KeyEnter}, {Code: tea.KeyTab}} {
		if _, cmd := coord.Update(key); cmd != nil || coord.CurrentView() != before {
			t.Fatalf("key %v was accepted while the dashboard list was too small", key)
		}
	}
}

func TestCoordinatorTooSmallStillQuits(t *testing.T) {
	for _, key := range []tea.KeyPressMsg{{Code: 0, Text: "q"}, {Code: 'c', Mod: tea.ModCtrl}} {
		coord := newSizedCoordinator(t, 40, 10)
		_, cmd := coord.Update(key)
		if cmd == nil {
			t.Fatalf("key %v returned no command", key)
		}
		if _, ok := cmd().(tea.QuitMsg); !ok {
			t.Errorf("key %v did not quit", key)
		}
	}
}

// TestCoordinatorRecoversWhenTerminalGrows: at the minimum size the notice is
// gone and the dashboard accepts keys again ("n" asks for a new card).
func TestCoordinatorRecoversWhenTerminalGrows(t *testing.T) {
	coord := newSizedCoordinator(t, 60, 20)
	if _, cmd := coord.Update(tea.KeyPressMsg{Code: 0, Text: "n"}); cmd != nil {
		t.Fatal("a key was accepted while too small")
	}
	coord.Update(tea.WindowSizeMsg{Width: views.MinTerminalWidth, Height: views.MinTerminalHeight})
	if strings.Contains(coord.View(), "Terminal too small") {
		t.Fatal("still showing the notice at the minimum size")
	}
	if _, cmd := coord.Update(tea.KeyPressMsg{Code: 0, Text: "n"}); cmd == nil {
		t.Error("the dashboard dropped a key at the minimum size")
	}
}

// TestCoordinatorDashboardFillsTheTerminal: through the coordinator, at and
// above the minimum size, the dashboard's render is exactly the terminal's rows
// - the coordinator's reserve (views.CoordinatorRows) and the dashboard's use of
// it must agree. Seen to fail with one row added to the dashboard's pane height.
func TestCoordinatorDashboardFillsTheTerminal(t *testing.T) {
	for _, size := range [][2]int{{80, 24}, {81, 25}, {120, 40}, {200, 60}} {
		coord := newSizedCoordinator(t, size[0], size[1])
		uitest.AssertWithin(t, coord.View(), size[0], size[1], fmt.Sprintf("%dx%d", size[0], size[1]))
		if got := strings.Count(coord.View(), "\n") + 1; got != size[1] {
			t.Errorf("%dx%d: dashboard is %d rows, want %d", size[0], size[1], got, size[1])
		}
	}
}

