	}

	// Configure source
	if errAtomic := repo.WriteAtomic(filepath.Join(repo.Dir(), config.SkillsSourcesFilename), config.SkillsSourcesFile{
		SchemaVersion: config.SchemaVersion,
		Paths:         []string{sourceRoot},
	}); errAtomic != nil {
