package config_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
)

//nolint:gocognit
func TestUpsertDomainTypes(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	// Test Skills
	s1, err := repo.UpsertSkill(config.Skill{Name: "skill1"})
	if err != nil || s1.ID == "" {
		t.Fatalf("upsert skill: %v", err)
	}
	s1.Description = "updated"
	s1Upd, err := repo.UpsertSkill(s1)
	if err != nil || s1Upd.ID != s1.ID || s1Upd.Description != "updated" {
		t.Fatalf("update skill: %v", err)
	}
	skills, _ := repo.ListSkills()
	// Should have the custom skill and both built-ins.
	if len(skills) != 3 {
		t.Fatalf("expected 3 skills (skill1 + builtins), got %d", len(skills))
	}
	// Verify our custom skill is present
	found := false
	for _, s := range skills {
		if s.Name == "skill1" {
			found = true
			if s.Description != "updated" {
				t.Fatalf("expected updated description, got %s", s.Description)
			}
		}
	}
	if !found {
		t.Fatalf("skill1 not found in skills list")
	}

	// Test Personas
	p1, err := repo.UpsertPersona(config.Persona{Name: "persona1"})
	if err != nil || p1.ID == "" {
		t.Fatalf("upsert persona: %v", err)
	}
	p1.Source = "updated"
	p1Upd, err := repo.UpsertPersona(p1)
	if err != nil || p1Upd.ID != p1.ID || p1Upd.Source != "updated" {
		t.Fatalf("update persona: %v", err)
	}
	personas, _ := repo.ListPersonas()
	if len(personas) != 1 {
		t.Fatalf("expected 1 persona, got %d", len(personas))
	}

	// Test MCPs
	m1, err := repo.UpsertMCP(config.MCPServer{Name: "mcp1", Command: "cmd1"})
	if err != nil || m1.ID == "" {
		t.Fatalf("upsert mcp: %v", err)
	}
	m1.Command = "updated"
	m1Upd, err := repo.UpsertMCP(m1)
	if err != nil || m1Upd.ID != m1.ID || m1Upd.Command != "updated" {
		t.Fatalf("update mcp: %v", err)
	}
	mcps, _ := repo.ListMCPs()
	if len(mcps) != 2 {
		t.Fatalf("expected user mcp and built-in kankuro mcp, got %d", len(mcps))
	}
}

func TestUpdateIDCardRefactored(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()
	wsID := workspaces[0].ID

	card := config.IDCard{
		DashboardID: "default",
		Name:        "Original",
		Driver:      "cat",
		WorkspaceID: wsID,
	}

	created, err := repo.CreateIDCard(card)
	if err != nil {
		t.Fatalf("create card: %v", err)
	}
	originalCreatedAt := created.CreatedAt
	originalUpdatedAt := created.UpdatedAt

	// Wait a bit to ensure UpdatedAt changes
	time.Sleep(10 * time.Millisecond)

	created.Name = "Updated"
	updated, err := repo.UpdateIDCard(created)
	if err != nil {
		t.Fatalf("update card: %v", err)
	}

	if updated.ID != created.ID {
		t.Fatalf("ID mismatch: %s != %s", updated.ID, created.ID)
	}
	if !updated.CreatedAt.Equal(originalCreatedAt) {
		t.Fatalf("CreatedAt changed: %v != %v", updated.CreatedAt, originalCreatedAt)
	}
	if !updated.UpdatedAt.After(originalUpdatedAt) {
		t.Fatalf("UpdatedAt did not increase: %v <= %v", updated.UpdatedAt, originalUpdatedAt)
	}

	// Test update unknown ID
	unknownCard := updated
	unknownCard.ID = "unknown"
	_, err = repo.UpdateIDCard(unknownCard)
	if err == nil {
		t.Fatal("expected error updating unknown card")
	}
}

func TestValidateCardRefactored(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()
	wsID := workspaces[0].ID

	t.Run("MissingFields", func(t *testing.T) {
		cases := []struct {
			card config.IDCard
			err  string
		}{
			{config.IDCard{}, "id card name is required"},
			{config.IDCard{Name: "N"}, "driver is required"},
			{config.IDCard{Name: "N", Driver: "D"}, "workspace is required"},
		}
		for _, tc := range cases {
			if vErr := repo.ValidateCard(tc.card); vErr == nil || vErr.Error() != tc.err {
				t.Errorf("expected error %q, got %v", tc.err, vErr)
			}
		}
	})

	t.Run("UnknownWorkspace", func(t *testing.T) {
		card := config.IDCard{Name: "N", Driver: "D", WorkspaceID: "missing"}
		if vErr := repo.ValidateCard(card); vErr == nil {
			t.Fatal("expected error for unknown workspace")
		}
	})

	t.Run("UnknownRefs", func(t *testing.T) {
		card := config.IDCard{Name: "N", Driver: "D", WorkspaceID: wsID}

		card.SkillIDs = []string{"missing-skill"}
		if vErr := repo.ValidateCard(card); vErr == nil {
			t.Fatal("expected error for unknown skill")
		}
		card.SkillIDs = nil

		card.PersonaIDs = []string{"missing-persona"}
		if vErr := repo.ValidateCard(card); vErr == nil {
			t.Fatal("expected error for unknown persona")
		}
		card.PersonaIDs = nil

		card.MCPIDs = []string{"missing-mcp"}
		if vErr := repo.ValidateCard(card); vErr == nil {
			t.Fatal("expected error for unknown mcp")
		}
		card.MCPIDs = nil
	})

	t.Run("ValidCard", func(t *testing.T) {
		skill, _ := repo.UpsertSkill(config.Skill{Name: "s"})
		persona, _ := repo.UpsertPersona(config.Persona{Name: "p"})
		mcp, _ := repo.UpsertMCP(config.MCPServer{Name: "m", Command: "c"})

		card := config.IDCard{
			Name:        "N",
			Driver:      "D",
			WorkspaceID: wsID,
			SkillIDs:    []string{skill.ID},
			PersonaIDs:  []string{persona.ID},
			MCPIDs:      []string{mcp.ID},
		}
		if vErr := repo.ValidateCard(card); vErr != nil {
			t.Fatalf("unexpected validation error: %v", vErr)
		}
	})
}

func TestValidateCardRegistryIntegrity(t *testing.T) {
	for _, filename := range []string{config.SkillsFilename, config.PersonasFilename, config.MCPsFilename} {
		t.Run(filename, func(t *testing.T) {
			repo, card := newRegistryIntegrityFixture(t)
			var err error
			if err = repo.ValidateCard(card); err != nil {
				t.Fatalf("valid baseline: %v", err)
			}
			if err = os.WriteFile(filepath.Join(repo.Dir(), filename), []byte("invalid: yaml: :"), 0o600); err != nil {
				t.Fatal(err)
			}
			err = repo.ValidateCard(card)
			if err == nil || !strings.Contains(err.Error(), filename) {
				t.Fatalf("corrupt %s: got %v, want error naming registry", filename, err)
			}
		})
	}
}

func newRegistryIntegrityFixture(t *testing.T) (*config.FileRepository, config.IDCard) {
	t.Helper()
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: t.TempDir()}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v, %v", workspaces, err)
	}
	return repo, config.IDCard{Name: "N", Driver: "D", WorkspaceID: workspaces[0].ID}
}

internal/config/repository_concurrency_t.source:
package config_test

import (
	"fmt"
	"sync"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
)

// TestSaveSkillSourcesConcurrentWritesDoNotCorrupt documents the safety
// FileRepository's internal locking (#11) provides: concurrent calls to a
// single mutator never corrupt the underlying file or panic/deadlock the
// repository, and every individual write is durably applied. It does not
// assert all N entries survive - List-then-append-then-Save from N separate
// goroutines is a classic read-modify-write race at the *caller* level
// (each goroutine's read can miss another's concurrent write) that
// repository-internal locking alone cannot close; that is a caller-side
// concern, not this primitive's.
func TestSaveSkillSourcesConcurrentWritesDoNotCorrupt(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	const n = 10
	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := range n {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			existing, listErr := repo.ListSkillSources()
			if listErr != nil {
				errs <- fmt.Errorf("list: %w", listErr)
				return
			}
			if saveErr := repo.SaveSkillSources(append(existing, fmt.Sprintf("source-%d", i))); saveErr != nil {
				errs <- fmt.Errorf("save: %w", saveErr)
			}
		}(i)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatalf("unexpected error from concurrent save: %v", err)
	}

	final, err := repo.ListSkillSources()
	if err != nil {
		t.Fatalf("final list: %v", err)
	}
	if len(final) < 1 || len(final) > n {
		t.Fatalf("expected between 1 and %d sources, got %d: %v", n, len(final), final)
	}
	seen := map[string]bool{}
	for _, s := range final {
		if seen[s] {
			t.Fatalf("duplicate entry in final list, file may be corrupted: %v", final)
		}
		seen[s] = true
	}
}

// TestUpdateSkillSourcesConcurrentAppendsAllSurvive is the strict counterpart
// to TestSaveSkillSourcesConcurrentWritesDoNotCorrupt: UpdateSkillSources
// reads, mutates, and saves the list under one lock acquisition, so unlike
// the List-then-Save pattern above, concurrent appends cannot be lost. Every
// one of the n goroutines' entries must survive.
func TestUpdateSkillSourcesConcurrentAppendsAllSurvive(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	// Use real, readable directories so the post-save registry resync
	// succeeds too - this test is about the source *list* never losing an
	// entry, not about sync errors (that's TestUpdateSkillSourcesRefreshesUIOnSyncFailure).
	const n = 10
	dirs := make([]string, n)
	for i := range n {
		dirs[i] = t.TempDir()
	}

	var wg sync.WaitGroup
	errs := make(chan error, n)
	for i := range n {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			updateErr := repo.UpdateSkillSources(func(sources []string) ([]string, error) {
				return append(sources, dirs[i]), nil
			})
			if updateErr != nil {
				errs <- updateErr
			}
		}(i)
	}
	wg.Wait()
	close(errs)
	for err := range errs {
		t.Fatalf("unexpected error from concurrent update: %v", err)
	}

	final, err := repo.ListSkillSources()
	if err != nil {
		t.Fatalf("final list: %v", err)
	}
	if len(final) != n {
		t.Fatalf("expected exactly %d sources (no lost updates), got %d: %v", n, len(final), final)
	}
	seen := map[string]bool{}
	for _, s := range final {
		if seen[s] {
			t.Fatalf("duplicate entry in final list: %v", final)
		}
		seen[s] = true
	}
	for _, dir := range dirs {
		if !seen[dir] {
			t.Fatalf("expected %q to survive, final list: %v", dir, final)
		}
	}
}

// TestRepositoryConcurrentMixedOperationsNoDeadlock exercises several
// domains' mutators and readers concurrently to catch the reentrancy hazard
// called out in #11: a mutator that calls a public List* method while
// already holding FileRepository.mu would deadlock the whole TUI. If this
// test does not hang, no such reentrant call exists on these paths.
func TestRepositoryConcurrentMixedOperationsNoDeadlock(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}

	wsDir := t.TempDir()
	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wsDir}}); saveErr != nil {
		t.Fatalf("seed workspace source: %v", saveErr)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) == 0 {
		t.Fatalf("seed workspace: %v (workspaces=%v)", err, workspaces)
	}
	wsID := workspaces[0].ID

	var wg sync.WaitGroup
	done := make(chan struct{})
	errs := make(chan error, 64)

	worker := func(fn func() error) {
		defer wg.Done()
		if workerErr := fn(); workerErr != nil {
			errs <- workerErr
		}
	}

	for i := range 5 {
		wg.Add(4)
		go worker(func() error {
			_, createErr := repo.CreateIDCard(config.IDCard{
				DashboardID: "default",
				Name:        fmt.Sprintf("card-%d", i),
				Driver:      "cat",
				WorkspaceID: wsID,
			})
			return createErr
		})
		go worker(func() error {
			_, listErr := repo.ListIDCards()
			return listErr
		})
		go worker(func() error {
			_, upsertErr := repo.UpsertSkill(config.Skill{Name: fmt.Sprintf("skill-%d", i)})
			return upsertErr
		})
		go worker(func() error {
			_, settingsErr := repo.GetAppSettings()
			return settingsErr
		})
	}

	go func() {
		wg.Wait()
		close(done)
	}()

	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("concurrent repository operations deadlocked")
	}
	close(errs)
	for err := range errs {
		t.Fatalf("unexpected error from concurrent operation: %v", err)
	}
}

