internal/driver/kill_test.go.source:
package driver_test

import (
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/driver"
)

var pidLineRE = regexp.MustCompile(`(\d+)\r?\n`)

// spawnScript runs script under sh in a PTY, drains its output into the
// returned channel, and registers a cleanup that SIGKILLs the process group
// whatever the test did - a failing kill test must not leave processes (a
// `sleep 1000`, say) running on the developer's machine.
func spawnScript(t *testing.T, script string, env map[string]string) (*driver.GenericCLIDriver, *driver.SessionHandle, <-chan string) {
	t.Helper()
	d := driver.NewGenericCLIDriver()
	h, err := d.Spawn(driver.AgentConfig{
		Driver:     "sh",
		Args:       []string{"-c", script},
		WorkingDir: t.TempDir(),
		Env:        env,
	})
	if err != nil {
		t.Fatalf("spawn: %v", err)
	}
	pid := h.Cmd.Process.Pid
	t.Cleanup(func() { _ = syscall.Kill(-pid, syscall.SIGKILL) })

	out := make(chan string, 64)
	go func() {
		for chunk := range h.Output {
			select {
			case out <- string(chunk):
			default:
			}
		}
	}()
	return d, h, out
}

// waitForMatch accumulates output until pred accepts it.
func waitForMatch(t *testing.T, out <-chan string, what string, pred func(string) bool) string {
	t.Helper()
	var acc strings.Builder
	timeout := time.After(5 * time.Second)
	for {
		select {
		case chunk := <-out:
			acc.WriteString(chunk)
			if pred(acc.String()) {
				return acc.String()
			}
		case <-timeout:
			t.Fatalf("timed out waiting for %s; output so far: %q", what, acc.String())
		}
	}
}

func waitForText(t *testing.T, out <-chan string, text string) {
	t.Helper()
	waitForMatch(t, out, text, func(s string) bool { return strings.Contains(s, text) })
}

// processGone reports whether pid no longer runs. A zombie counts as gone: in
// a container whose init does not reap orphans, an exited grandchild stays a
// zombie forever and kill(pid, 0) keeps succeeding.
func processGone(pid int) bool {
	if err := syscall.Kill(pid, 0); errors.Is(err, syscall.ESRCH) {
		return true
	}
	stat, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
	if err != nil {
		return false
	}
	// "<pid> (<comm>) <state> ..."; comm may contain spaces, so cut at the last ')'.
	s := string(stat)
	if i := strings.LastIndexByte(s, ')'); i >= 0 && i+2 < len(s) {
		return s[i+2] == 'Z'
	}
	return false
}

// TestKillTerminatesTheProcessGroup: a descendant that ignores SIGHUP used to
// survive Kill (only the direct child was signalled, and the SIGHUP from the
// closing PTY does not reach a process ignoring it).
func TestKillTerminatesTheProcessGroup(t *testing.T) {
	// The trap is set before the background job is forked so the job inherits
	// the ignore: no window in which it could still die of the PTY's SIGHUP.
	d, _, out := spawnScript(t, `trap "" HUP; sleep 1000 & echo $!; wait`, nil)

	got := waitForMatch(t, out, "the grandchild's pid", func(s string) bool { return pidLineRE.MatchString(s) })
	gpid, err := strconv.Atoi(pidLineRE.FindStringSubmatch(got)[1])
	if err != nil {
		t.Fatalf("parse pid: %v", err)
	}
	t.Cleanup(func() { _ = syscall.Kill(gpid, syscall.SIGKILL) })
	if processGone(gpid) {
		t.Fatalf("grandchild %d is not running before Kill", gpid)
	}

	if errKill := d.Kill(); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}

	deadline := time.Now().Add(5 * time.Second)
	for !processGone(gpid) {
		if time.Now().After(deadline) {
			t.Fatalf("grandchild %d survived Kill", gpid)
		}
		time.Sleep(20 * time.Millisecond)
	}
}

// TestKillIsGraceful: SIGTERM comes first, so the agent can run its own
// shutdown. A bare SIGKILL gives the trap no chance.
func TestKillIsGraceful(t *testing.T) {
	marker := filepath.Join(t.TempDir(), "bye")
	d, _, out := spawnScript(t,
		`trap 'echo bye > "$F"; exit 0' TERM; echo ready; while :; do sleep 0.1; done`,
		map[string]string{"F": marker})
	waitForText(t, out, "ready")

	if err := d.Kill(); err != nil {
		t.Fatalf("kill: %v", err)
	}
	if _, err := os.Stat(marker); err != nil {
		t.Fatalf("the TERM handler did not run: %v", err)
	}
}

// TestKillEscalatesWhenTERMIsIgnored: an agent that ignores SIGTERM must still
// die, after the grace period and not much later.
func TestKillEscalatesWhenTERMIsIgnored(t *testing.T) {
	d, h, out := spawnScript(t, `trap "" TERM; echo ready; while :; do sleep 0.1; done`, nil)
	d.SetKillGraceForTest(200 * time.Millisecond)
	waitForText(t, out, "ready")
	pid := h.Cmd.Process.Pid

	start := time.Now()
	if err := d.Kill(); err != nil {
		t.Fatalf("kill: %v", err)
	}
	if elapsed := time.Since(start); elapsed > time.Second {
		t.Fatalf("Kill took %v, want about the 200ms grace period", elapsed)
	}
	if !processGone(pid) {
		t.Fatalf("process %d survived Kill", pid)
	}
	if d.GetStatus() != driver.StatusTerminated {
		t.Fatalf("status = %s, want terminated", d.GetStatus())
	}
}

// TestKillReachesDescendantsThatIgnoreTERM: the leader exits on SIGTERM (the
// normal case), but a child it started ignores SIGTERM and SIGHUP. The SIGKILL
// escalation must depend on the group still having members, not on the leader
// still running, or such a child is orphaned and lives on.
func TestKillReachesDescendantsThatIgnoreTERM(t *testing.T) {
	// The child inherits the ignored TERM and HUP; the shell then restores the
	// default TERM action for itself and only then announces the pid, so Kill
	// cannot run before the shell is ready to die of it.
	d, _, out := spawnScript(t, `trap "" HUP TERM; sleep 1000 & P=$!; trap - TERM; echo $P; wait`, nil)
	d.SetKillGraceForTest(300 * time.Millisecond)

	got := waitForMatch(t, out, "the descendant's pid", func(s string) bool { return pidLineRE.MatchString(s) })
	gpid, err := strconv.Atoi(pidLineRE.FindStringSubmatch(got)[1])
	if err != nil {
		t.Fatalf("parse pid: %v", err)
	}
	t.Cleanup(func() { _ = syscall.Kill(gpid, syscall.SIGKILL) })
	if processGone(gpid) {
		t.Fatalf("descendant %d is not running before Kill", gpid)
	}

	if errKill := d.Kill(); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}

	// No assertion on how long Kill took: where init does not reap orphans an
	// exited child stays a zombie and keeps the group "alive", so Kill then
	// legitimately spends the whole grace period.
	deadline := time.Now().Add(5 * time.Second)
	for !processGone(gpid) {
		if time.Now().After(deadline) {
			t.Fatalf("descendant %d (ignoring TERM and HUP) survived Kill", gpid)
		}
		time.Sleep(20 * time.Millisecond)
	}
}

internal/driver/mcp_config_test.go.source:
package driver_test

import (
	"bytes"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
)

type testMCPConfig struct {
	MCPServers map[string]struct {
		Command string            `json:"command"`
		Args    []string          `json:"args"`
		Env     map[string]string `json:"env"`
		CWD     string            `json:"cwd"`
		URL     string            `json:"url"`
		Headers map[string]string `json:"headers"`
	} `json:"mcpServers"`
}

//nolint:gocognit,govet // Table covers complete server-set replacement and unrelated metadata preservation.
func TestSelectMCPsReplacesCompleteWorkspaceSelection(t *testing.T) {
	root := t.TempDir()
	d := driver.NewGenericCLIDriver()
	builtin := config.MCPServer{
		ID: config.BuiltinMCPKankuro, Name: "kankuro", URL: "http://127.0.0.1:1234/mcp",
		Headers: map[string]string{"Authorization": "Bearer activation-token"},
	}
	ordinary := config.MCPServer{
		ID: "ordinary", Name: "ordinary", Command: "serve", Args: []string{"--stdio"},
		Env: map[string]string{"MCP_KEY": "ordinary-secret"}, CWD: "/workspace", URL: "https://ordinary",
		Headers: map[string]string{"X-Auth": "ordinary-header"},
	}
	metadataDir := filepath.Join(root, ".kankuro")
	if err := os.MkdirAll(metadataDir, 0o700); err != nil {
		t.Fatal(err)
	}
	metadataPath := filepath.Join(metadataDir, "sub-workspaces.json")
	if err := os.WriteFile(metadataPath, []byte(`{"keep":true}`), 0o600); err != nil {
		t.Fatal(err)
	}

	for _, test := range []struct {
		name    string
		servers []config.MCPServer
		want    int
	}{
		{name: "built-in only", servers: []config.MCPServer{builtin}, want: 1},
		{name: "ordinary only", servers: []config.MCPServer{ordinary}, want: 1},
		{name: "combined", servers: []config.MCPServer{ordinary, builtin}, want: 2},
		{name: "empty clears old selection", servers: []config.MCPServer{}, want: 0},
	} {
		t.Run(test.name, func(t *testing.T) {
			if err := d.SelectMCPs(test.servers, root); err != nil {
				t.Fatalf("SelectMCPs: %v", err)
			}
			data, err := os.ReadFile(driver.MCPConfigPath(root))
			if err != nil {
				t.Fatal(err)
			}
			var got testMCPConfig
			if err := json.Unmarshal(data, &got); err != nil {
				t.Fatalf("decode workspace MCP config: %v", err)
			}
			if len(got.MCPServers) != test.want {
				t.Fatalf("server count = %d, want %d: %#v", len(got.MCPServers), test.want, got.MCPServers)
			}
			if entry, ok := got.MCPServers["ordinary"]; ok {
				if entry.Command != ordinary.Command || entry.URL != ordinary.URL || entry.Args[0] != ordinary.Args[0] ||
					entry.Env["MCP_KEY"] != "ordinary-secret" || entry.CWD != ordinary.CWD || entry.Headers["X-Auth"] != "ordinary-header" {
					t.Fatalf("ordinary MCP fields changed: %#v", entry)
				}
			}
			if entry, ok := got.MCPServers["kankuro"]; ok {
				if entry.URL != builtin.URL || entry.Headers["Authorization"] != builtin.Headers["Authorization"] {
					t.Fatalf("resolved Kankuro MCP fields changed: %#v", entry)
				}
			}
			info, err := os.Stat(driver.MCPConfigPath(root))
			if err != nil || info.Mode().Perm() != 0o600 {
				t.Fatalf("config permissions = %v, %v; want 0600", info, err)
			}
			metadata, err := os.ReadFile(metadataPath)
			if err != nil || string(metadata) != `{"keep":true}` {
				t.Fatalf("unrelated workspace metadata changed: %q, %v", metadata, err)
			}
		})
	}
}

func TestSelectMCPsRejectsUnresolvedBuiltinWithoutReplacingFile(t *testing.T) {
	root := t.TempDir()
	d := driver.NewGenericCLIDriver()
	if err := d.SelectMCPs([]config.MCPServer{{ID: "ordinary", Name: "ordinary", URL: "https://ordinary"}}, root); err != nil {
		t.Fatal(err)
	}
	path := driver.MCPConfigPath(root)
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	err = d.SelectMCPs([]config.MCPServer{{ID: config.BuiltinMCPKankuro, Name: "kankuro"}}, root)
	if err == nil {
		t.Fatal("unresolved built-in MCP unexpectedly serialized")
	}
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(before, after) {
		t.Fatalf("failed config publication replaced prior file: before=%s after=%s", before, after)
	}
}

//nolint:govet // The test deliberately checks each individual filesystem operation.
func TestSelectMCPsWriteFailureLeavesPreviousCompleteConfig(t *testing.T) {
	root := t.TempDir()
	d := driver.NewGenericCLIDriver()
	if err := d.SelectMCPs([]config.MCPServer{{ID: "before", Name: "before", URL: "https://before"}}, root); err != nil {
		t.Fatal(err)
	}
	path := driver.MCPConfigPath(root)
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	metadataDir := filepath.Dir(path)
	if err := os.Chmod(metadataDir, 0o500); err != nil {
		t.Fatal(err)
	}
	writeErr := d.SelectMCPs([]config.MCPServer{{ID: "after", Name: "after", URL: "https://after"}}, root)
	if err := os.Chmod(metadataDir, 0o700); err != nil {
		t.Fatal(err)
	}
	if writeErr == nil {
		t.Skip("filesystem permissions are not enforced for this test user")
	}
	after, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(before, after) {
		t.Fatalf("failed atomic publication changed prior config: before=%s after=%s", before, after)
	}
}

//nolint:govet // Independent cleanup and read failures are asserted at each step.
func TestRemoveKankuroEntryOnlyWhenCredentialMatches(t *testing.T) {
	root := t.TempDir()
	d := driver.NewGenericCLIDriver()
	servers := []config.MCPServer{
		{
			ID:      config.BuiltinMCPKankuro,
			Name:    "kankuro",
			URL:     "http://127.0.0.1:1234/mcp",
			Headers: map[string]string{"Authorization": "Bearer token-a"},
		},
		{ID: "ordinary", Name: "ordinary", Command: "server", Args: []string{"--stdio"}},
	}
	if err := d.SelectMCPs(servers, root); err != nil {
		t.Fatal(err)
	}
	path := driver.MCPConfigPath(root)
	metadataPath := filepath.Join(filepath.Dir(path), "sub-workspaces.json")
	if err := os.WriteFile(metadataPath, []byte(`{"kept":true}`), 0o600); err != nil {
		t.Fatal(err)
	}
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := driver.RemoveKankuroMCPIfAuthorizationMatches(path, "token-b"); err != nil {
		t.Fatal(err)
	}
	unchanged, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(before, unchanged) {
		t.Fatalf("another activation's config changed: %v", err)
	}
	if err := driver.RemoveKankuroMCPIfAuthorizationMatches(path, "token-a"); err != nil {
		t.Fatal(err)
	}
	var result testMCPConfig
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &result); err != nil {
		t.Fatal(err)
	}
	if len(result.MCPServers) != 1 || result.MCPServers["ordinary"].Command != "server" {
		t.Fatalf("conditional cleanup did not preserve ordinary MCP: %#v", result.MCPServers)
	}
	metadata, err := os.ReadFile(metadataPath)
	if err != nil || string(metadata) != `{"kept":true}` {
		t.Fatalf("conditional cleanup changed other workspace metadata: %q, %v", metadata, err)
	}
}

//nolint:govet // Separate filesystem and parse operations each have a focused assertion.
func TestRemoveKankuroEntryKeepsEmptyConfigAndHandlesMissingOrMalformedFiles(t *testing.T) {
	root := t.TempDir()
	d := driver.NewGenericCLIDriver()
	server := config.MCPServer{
		ID: config.BuiltinMCPKankuro, Name: "kankuro", URL: "http://127.0.0.1:1234/mcp",
		Headers: map[string]string{"Authorization": "Bearer token"},
	}
	if err := d.SelectMCPs([]config.MCPServer{server}, root); err != nil {
		t.Fatal(err)
	}
	path := driver.MCPConfigPath(root)
	if err := driver.RemoveKankuroMCPIfAuthorizationMatches(path, "token"); err != nil {
		t.Fatal(err)
	}
	var empty testMCPConfig
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &empty); err != nil || len(empty.MCPServers) != 0 {
		t.Fatalf("Kankuro-only cleanup did not retain an empty map: %#v, %v", empty, err)
	}
	if err := driver.RemoveKankuroMCPIfAuthorizationMatches(filepath.Join(root, "missing.json"), "token"); err != nil {
		t.Fatalf("missing config cleanup: %v", err)
	}
	if err := os.WriteFile(path, []byte("not-json"), 0o600); err != nil {
		t.Fatal(err)
	}
	err = driver.RemoveKankuroMCPIfAuthorizationMatches(path, "token")
	if err == nil {
		t.Fatal("malformed config cleanup unexpectedly succeeded")
	}
	malformed, readErr := os.ReadFile(path)
	if readErr != nil || string(malformed) != "not-json" {
		t.Fatalf("malformed config was modified: %q, %v", malformed, readErr)
	}
}

