package session_test

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/google/uuid"
)

func TestNaturalRecipientExitWakesMessagingWaiters(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("list workspaces: %v", err)
	}
	manager := newTestManager(t, repo.Dir(), repo)
	manager.SetMCPEndpoint("http://127.0.0.1:12345/mcp")
	card, err := repo.CreateIDCard(config.IDCard{DashboardID: "default", ID: "natural-exit", Name: "natural exit", Driver: "cat",
		WorkspaceID: workspaces[0].ID, MCPIDs: []string{config.BuiltinMCPKankuro}})
	if err != nil {
		t.Fatal(err)
	}
	sessionID, err := testLaunch(manager, card, nil, nil, config.BuiltinMCPs())
	if err != nil {
		t.Fatal(err)
	}
	snapshot, found := manager.GetSession(sessionID)
	if !found || snapshot.PID <= 0 || snapshot.ActivationID == "" {
		t.Fatalf("recipient snapshot = %#v, found=%v", snapshot, found)
	}
	messageID := uuid.NewString()
	if _, err = manager.Messages().CreateIntent(session.MessageRecord{ID: messageID, DashboardID: "default",
		SenderSessionID: "sender", RecipientSessionID: sessionID, RecipientActivationID: snapshot.ActivationID, Text: "task"},
		uuid.NewString(), session.SendFingerprint(sessionID, snapshot.ActivationID, "task")); err != nil {
		t.Fatal(err)
	}
	changed := manager.Messages().Changed()
	process, err := os.FindProcess(snapshot.PID)
	if err != nil {
		t.Fatal(err)
	}
	if err = process.Kill(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-changed:
	case <-time.After(5 * time.Second):
		t.Fatal("natural process termination did not wake messaging waiters")
	}
	live, err := manager.MessageRecipientLive(messageID)
	if err != nil || live {
		t.Fatalf("recipient live=%v, err=%v after natural exit", live, err)
	}
}

//nolint:gocognit // Stop and shutdown must each release a pending manager reservation.
func TestPendingMessageReservationDoesNotBlockStopOrShutdown(t *testing.T) {
	for _, lifecycle := range []string{"stop", "shutdown"} {
		t.Run(lifecycle, func(t *testing.T) {
			repo, err := config.NewFileRepository(t.TempDir())
			if err != nil {
				t.Fatal(err)
			}
			workspace := t.TempDir()
			if err = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("list workspaces: %v", err)
			}
			manager := newTestManager(t, repo.Dir(), repo)
			manager.SetMCPEndpoint("http://127.0.0.1:12345/mcp")
			controller, err := repo.CreateIDCard(
				config.IDCard{DashboardID: "default", ID: "admission-controller", Name: "controller", Driver: "cat",
					WorkspaceID: workspaces[0].ID, DashboardControl: true, MCPIDs: []string{config.BuiltinMCPKankuro}},
			)
			if err != nil {
				t.Fatal(err)
			}
			recipient, err := repo.CreateIDCard(
				config.IDCard{DashboardID: "default", ID: "admission-recipient", Name: "recipient", Driver: "cat",
					WorkspaceID: workspaces[0].ID, MCPIDs: []string{config.BuiltinMCPKankuro}},
			)
			if err != nil {
				t.Fatal(err)
			}
			controllerID, err := testLaunch(manager, controller, nil, nil, config.BuiltinMCPs())
			if err != nil {
				t.Fatal(err)
			}
			controllerWorkspace := filepath.Join(workspace, ".kankuro", "mcp-servers.json")
			token := readRelaunchToken(t, controllerWorkspace)
			recipientID, err := testLaunch(manager, recipient, nil, nil, config.BuiltinMCPs())
			if err != nil {
				t.Fatal(err)
			}
			recipientSession, found := manager.GetSession(recipientID)
			if !found {
				t.Fatal("recipient was not registered")
			}
			admission, err := manager.ReserveMessageAdmission(token, recipientID, recipientSession.ActivationID)
			if err != nil {
				t.Fatal(err)
			}
			messageID := uuid.NewString()
			if _, err = manager.Messages().CreateIntent(session.MessageRecord{ID: messageID, DashboardID: "default",
				SenderSessionID: controllerID, SenderActivationID: token, RecipientSessionID: recipientID,
				RecipientActivationID: recipientSession.ActivationID, Text: "queued"}, uuid.NewString(),
				session.SendFingerprint(recipientID, recipientSession.ActivationID, "queued")); err != nil {
				t.Fatal(err)
			}

			completed := make(chan struct{})
			go func() {
				if lifecycle == "stop" {
					_ = manager.Kill(recipientID)
				} else {
					manager.Shutdown()
				}
				close(completed)
			}()
			select {
			case <-completed:
			case <-time.After(5 * time.Second):
				t.Fatal("lifecycle operation waited on an unstarted message reservation")
			}
			if lifecycle == "stop" {
				defer admission.Release()
				_, submitErr := manager.SubmitMessage(context.Background(), admission, token, messageID,
					recipientID, recipientSession.ActivationID, "queued")
				if submitErr == nil {
					t.Fatal("invalidated queued message submission unexpectedly succeeded")
				}
				got, getErr := manager.Messages().GetMessage(messageID)
				if getErr != nil || got.Delivery != session.MessageNotSubmitted {
					t.Fatalf("queued message after stop = %#v, %v", got, getErr)
				}
			}
		})
	}
}

internal/session/relaunch_mcp_test.go.source:
package session_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
)

//nolint:gocognit,govet // Exercises credential rotation, deployment preservation, and retry after a persisted reload.
func TestRelaunchRefreshesOnlyKankuroMCPAfterRestart(t *testing.T) {
	for _, useTmp := range []bool{false, true} {
		t.Run(map[bool]string{false: "original", true: "temporary"}[useTmp], func(t *testing.T) {
			repo, workspaceID := workspaceValidationRepository(t)
			manager := newTestManager(t, repo.Dir(), repo)
			manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
			card := config.IDCard{
				ID: "relaunch", Name: "relaunch", Driver: "cat", WorkspaceID: workspaceID,
				UseTmpWorkspace: useTmp, AgentsMD: "initial role",
			}
			selected := append(config.BuiltinMCPs(), config.MCPServer{ID: "ordinary", Name: "ordinary", Command: "initial"})
			id, err := testLaunch(manager, card, nil, nil, selected)
			if err != nil {
				t.Fatal(err)
			}
			before, found := manager.GetSession(id)
			if !found || !before.KankuroMCPEnabled {
				t.Fatal("missing deployed Kankuro selection")
			}
			configPath := driver.MCPConfigPath(before.WorkingDir)
			firstToken := readRelaunchToken(t, configPath)
			if err := manager.Kill(id); err != nil {
				t.Fatal(err)
			}
			manager.Shutdown()
			deployed := `{"mcpServers":{"ordinary":{"command":"user-edited","extra":{"keep":true}}},"metadata":{"keep":true}}`
			writeTestFile(t, configPath, deployed)
			instructionPath := filepath.Join(before.WorkingDir, "AGENTS.md")
			writeTestFile(t, instructionPath, "manual instructions")
			restored := newTestManager(t, repo.Dir(), repo)
			restored.SetMCPEndpoint("http://127.0.0.1:43211/mcp")
			card.MCPIDs = nil
			card.AgentsMD = "must not be deployed"
			card.AgentsMDPreferPath = true
			card.AgentsMDPath = filepath.Join(t.TempDir(), "missing-instructions")
			// A malformed deployed config must fail without replacing it or starting a process.
			writeTestFile(t, configPath, "malformed config")
			if err := testRelaunch(restored, id, card); err == nil {
				t.Fatal("expected invalid deployed MCP config to block relaunch")
			}
			failed, found := restored.GetSession(id)
			if !found || failed.Status != session.StatusTerminated {
				t.Fatal("failed relaunch started an agent")
			}
			assertFileContent(t, configPath, "malformed config")
			assertFileContent(t, instructionPath, "manual instructions")
			writeTestFile(t, configPath, deployed)
			if err := testRelaunch(restored, id, card); err != nil {
				t.Fatal(err)
			}
			assertFileContent(t, instructionPath, "manual instructions")
			nextToken := readRelaunchToken(t, configPath)
			if nextToken == firstToken || restored.HasActivationCredential(firstToken) || !restored.HasActivationCredential(nextToken) {
				t.Fatal("relaunch failed to rotate activation credentials")
			}
			data, err := os.ReadFile(configPath)
			if err != nil {
				t.Fatal(err)
			}
			var root struct {
				MCPServers map[string]json.RawMessage `json:"mcpServers"`
				Metadata   json.RawMessage            `json:"metadata"`
			}
			if err := json.Unmarshal(data, &root); err != nil {
				t.Fatal(err)
			}
			if !strings.Contains(string(root.MCPServers["ordinary"]), "user-edited") ||
				!strings.Contains(string(root.MCPServers["ordinary"]), "extra") || !strings.Contains(string(root.Metadata), "true") {
				t.Fatalf("relaunch replaced workspace-authored MCP configuration: %s", data)
			}
			if !strings.Contains(string(root.MCPServers["kankuro"]), "43211") {
				t.Fatal("relaunch kept stale MCP endpoint")
			}
		})
	}
}

func readRelaunchToken(t *testing.T, path string) string {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var cfg struct {
		MCPServers map[string]struct {
			Headers map[string]string `json:"headers"`
		} `json:"mcpServers"`
	}
	if parseErr := json.Unmarshal(data, &cfg); parseErr != nil {
		t.Fatal(parseErr)
	}
	token := strings.TrimPrefix(cfg.MCPServers["kankuro"].Headers["Authorization"], "Bearer ")
	if token == "" {
		t.Fatal("Kankuro credential missing")
	}
	return token
}

internal/session/residual_cleanup_intern.source:
package session

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/google/uuid"
)

func TestRemoveResidualUsesSavedTemporaryIdentity(t *testing.T) {
	dir := t.TempDir()
	repo, err := config.NewFileRepository(dir)
	if err != nil {
		t.Fatal(err)
	}
	manager := NewManager(dir, repo)
	t.Cleanup(func() { manager.Shutdown() })
	id := uuid.NewString()
	root := filepath.Join(t.TempDir(), id)
	working := filepath.Join(root, "workspace")
	if errAt24 := os.MkdirAll(working, 0o700); errAt24 != nil {
		t.Fatal(errAt24)
	}
	if errAt27 := os.MkdirAll(filepath.Join(dir, "sessions"), 0o700); errAt27 != nil {
		t.Fatal(errAt27)
	}
	if errAt30 := os.WriteFile(filepath.Join(dir, "sessions", id+".json"), []byte(`{"id":"orphan"}`), 0o600); errAt30 != nil {
		t.Fatal(errAt30)
	}
	if _, errAt33 := manager.RemoveResidual(context.Background(), id, working, filepath.Dir(root), true); errAt33 == nil {
		t.Fatal("mismatched cleanup root accepted")
	}
	result, err := manager.RemoveResidual(context.Background(), id, working, root, true)
	if err != nil || !result.SessionRecordDeleted || !result.TemporaryWorkspaceRemoved {
		t.Fatalf("cleanup: %+v, %v", result, err)
	}
	if _, errAt40 := os.Stat(root); !os.IsNotExist(errAt40) {
		t.Fatalf("temporary workspace remains: %v", errAt40)
	}
	if _, errAt43 := manager.RemoveResidual(context.Background(), id, working, root, true); errAt43 != nil {
		t.Fatalf("retry: %v", errAt43)
	}
}

