package session_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/BlackGiack/kankuro/internal/session"
)

func TestReadSubWorkspaceDescriptorsDoesNotPrepareWorkspace(t *testing.T) {
	workingDir := t.TempDir()
	metadataDir := filepath.Join(workingDir, ".kankuro")
	if err := os.Mkdir(metadataDir, 0o700); err != nil {
		t.Fatal(err)
	}
	manifest := `{"schema_version":1,"copies":{"project":{"workspace_id":"workspace-id","source_path":"/source/project"}}}`
	if err := os.WriteFile(filepath.Join(metadataDir, "sub-workspaces.json"), []byte(manifest), 0o600); err != nil {
		t.Fatal(err)
	}
	descriptors, available := session.ReadSubWorkspaceDescriptors(workingDir)
	if !available || len(descriptors) != 1 {
		t.Fatalf("descriptors = %#v, available=%v", descriptors, available)
	}
	wantDestination := filepath.Join(workingDir, "tmp", "project")
	if descriptors[0].WorkspaceID != "workspace-id" ||
		descriptors[0].SourcePath != "/source/project" || descriptors[0].DestinationPath != wantDestination {
		t.Fatalf("descriptor = %#v", descriptors[0])
	}
	if _, err := os.Stat(filepath.Join(workingDir, "tmp")); !os.IsNotExist(err) {
		t.Fatalf("inspection prepared a destination directory (stat error %v)", err)
	}
	if err := os.WriteFile(filepath.Join(metadataDir, "sub-workspaces.json"), []byte("{"), 0o600); err != nil {
		t.Fatal(err)
	}
	corruptDescriptors, corruptAvailable := session.ReadSubWorkspaceDescriptors(workingDir)
	if corruptAvailable || len(corruptDescriptors) != 0 {
		t.Fatalf("corrupt manifest was treated as available: %#v", corruptDescriptors)
	}
}

internal/session/tmp_workspace_test.go.source:
package session_test

import (
	"errors"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
)

func TestTmpWorkspaceLifecycle(t *testing.T) {
	// Setup
	tmpBase := t.TempDir()
	configDir := filepath.Join(tmpBase, "config")
	sourceDir := filepath.Join(tmpBase, "source")
	if err := os.MkdirAll(sourceDir, 0o755); err != nil {
		t.Fatal(err)
	}

	// Create a file in source
	originalContent := []byte("original")
	if err := os.WriteFile(filepath.Join(sourceDir, "data.txt"), originalContent, 0o644); err != nil {
		t.Fatal(err)
	}

	// Set env var for tmp dir location
	t.Setenv("KANKURO_TMP_DIR", filepath.Join(tmpBase, "sessions_tmp"))

	repo, _ := config.NewFileRepository(configDir)
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: sourceDir, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	sm := newTestManager(t, configDir, repo)

	card := config.IDCard{
		ID:              "card-tmp",
		Name:            "tmp-test",
		Driver:          "cat", // simple driver
		WorkspaceID:     workspaces[0].ID,
		UseTmpWorkspace: true,
	}

	// 1. Launch
	sid, err := testLaunch(sm, card, nil, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}

	// Wait for start
	time.Sleep(100 * time.Millisecond)

	s, ok := sm.GetSession(sid)
	if !ok {
		t.Fatalf("session not found")
	}
	if s.WorkingDir == sourceDir {
		t.Fatalf("expected working dir to be different from source, got %s", s.WorkingDir)
	}

	// Check file copy
	copiedFile := filepath.Join(s.WorkingDir, "data.txt")
	content, errRead := os.ReadFile(copiedFile)
	if errRead != nil {
		t.Fatalf("read copied file: %v", errRead)
	}
	if string(content) != "original" {
		t.Fatalf("expected content 'original', got '%s'", string(content))
	}

	// 2. Modify file in session dir
	newContent := []byte("modified")
	if errWrite := os.WriteFile(copiedFile, newContent, 0o644); errWrite != nil {
		t.Fatal(errWrite)
	}

	// 3. Kill session
	if errKill := sm.Kill(sid); errKill != nil {
		t.Fatal(errKill)
	}

	// 4. Verify original unchanged
	origContent, errOrig := os.ReadFile(filepath.Join(sourceDir, "data.txt"))
	if errOrig != nil {
		t.Fatal(errOrig)
	}
	if string(origContent) != "original" {
		t.Fatalf("original file was modified!")
	}

	// 5. Relaunch
	if errRelaunch := testRelaunch(sm, sid, card); errRelaunch != nil {
		t.Fatalf("relaunch: %v", errRelaunch)
	}

	time.Sleep(100 * time.Millisecond)
	s2, ok2 := sm.GetSession(sid)
	if !ok2 {
		t.Fatalf("session not found after relaunch")
	}

	// Verify same working dir
	if s2.WorkingDir != s.WorkingDir {
		t.Fatalf("expected same working dir on relaunch, got %s vs %s", s2.WorkingDir, s.WorkingDir)
	}

	// Verify modification persists
	content2, errRead2 := os.ReadFile(filepath.Join(s2.WorkingDir, "data.txt"))
	if errRead2 != nil {
		t.Fatal(errRead2)
	}
	if string(content2) != "modified" {
		t.Fatalf("expected content 'modified' after relaunch, got '%s'", string(content2))
	}

	// 6. Persistence check
	// Create new manager (simulate restart)
	sm2 := newTestManager(t, configDir, repo)
	restoredSession, okRestored := sm2.GetSession(sid)
	if !okRestored {
		t.Fatalf("session not restored from disk")
	}
	if restoredSession.Status != session.StatusTerminated {
		t.Fatalf("expected restored status Terminated, got %s", restoredSession.Status)
	}
	if restoredSession.WorkingDir != s.WorkingDir {
		t.Fatalf("restored working dir mismatch")
	}
}

func TestSwitchAgentReplacesSkillsInTmpWorkspace(t *testing.T) {
	tmpBase := t.TempDir()
	configDir := filepath.Join(tmpBase, "config")
	sourceDir := filepath.Join(tmpBase, "source")
	if err := os.MkdirAll(sourceDir, 0o755); err != nil {
		t.Fatal(err)
	}

	skill1Dir := filepath.Join(tmpBase, "skill-one")
	skill2Dir := filepath.Join(tmpBase, "skill-two")
	if err := os.MkdirAll(skill1Dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(skill2Dir, 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(skill1Dir, "SKILL.md"), []byte("one"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(skill2Dir, "SKILL.md"), []byte("two"), 0o644); err != nil {
		t.Fatal(err)
	}

	t.Setenv("KANKURO_TMP_DIR", filepath.Join(tmpBase, "sessions_tmp"))

	repo, _ := config.NewFileRepository(configDir)
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: sourceDir, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	sm := newTestManager(t, configDir, repo)

	card1 := config.IDCard{
		ID:              "card-tmp-1",
		Name:            "tmp-one",
		Driver:          "cat",
		WorkspaceID:     workspaces[0].ID,
		UseTmpWorkspace: true,
	}
	skills1 := []config.Skill{
		{ID: "s1", Name: "alpha-skill", Source: skill1Dir},
	}
	sid, err := testLaunch(sm, card1, skills1, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	time.Sleep(100 * time.Millisecond)

	s, ok := sm.GetSession(sid)
	if !ok {
		t.Fatalf("session not found")
	}
	wd := s.WorkingDir
	skill1Path := filepath.Join(wd, ".agents", "skills", "alpha-skill")
	if _, errStat := os.Stat(skill1Path); errStat != nil {
		t.Fatalf("expected skill1 present: %v", errStat)
	}

	if errKill := sm.Kill(sid); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}

	card2 := config.IDCard{
		ID:          "card-tmp-2",
		Name:        "tmp-two",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	}
	skills2 := []config.Skill{
		{ID: "s2", Name: "beta-skill", Source: skill2Dir},
	}
	if errSwitch := testSwitchAgent(sm, sid, card2, skills2, nil, nil); errSwitch != nil {
		t.Fatalf("switch: %v", errSwitch)
	}
	time.Sleep(100 * time.Millisecond)

	if _, errStat := os.Stat(skill1Path); errStat == nil || !os.IsNotExist(errStat) {
		t.Fatalf("expected skill1 removed, got %v", errStat)
	}
	skill2Path := filepath.Join(wd, ".agents", "skills", "beta-skill")
	if _, errStat2 := os.Stat(skill2Path); errStat2 != nil {
		t.Fatalf("expected skill2 present: %v", errStat2)
	}

	if errKillAfter := sm.Kill(sid); errKillAfter != nil {
		t.Fatalf("kill after switch: %v", errKillAfter)
	}
}

// TestTmpWorkspaceDefaultsUnderConfigDir covers the location the package's
// TestMain hides by setting KANKURO_TMP_DIR: with it unset, temporary
// workspaces live under <config>/tmp, for both creation and Remove (which
// share one fallback, Manager.tmpRoot).
func TestTmpWorkspaceDefaultsUnderConfigDir(t *testing.T) {
	t.Setenv("KANKURO_TMP_DIR", "")
	tmpBase := t.TempDir()
	configDir := filepath.Join(tmpBase, "config")
	sourceDir := filepath.Join(tmpBase, "source")
	if err := os.MkdirAll(sourceDir, 0o755); err != nil {
		t.Fatal(err)
	}

	repo, _ := config.NewFileRepository(configDir)
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: sourceDir, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()
	sm := newTestManager(t, configDir, repo)

	sid, err := testLaunch(sm, config.IDCard{
		ID:              "card-default-tmp",
		Name:            "default-tmp",
		Driver:          "cat",
		WorkspaceID:     workspaces[0].ID,
		UseTmpWorkspace: true,
	}, nil, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}

	s, _ := sm.GetSession(sid)
	wantRoot := filepath.Join(configDir, "tmp", sid)
	if want := filepath.Join(wantRoot, "source"); s.WorkingDir != want {
		t.Fatalf("WorkingDir = %q, want %q", s.WorkingDir, want)
	}
	if _, errStat := os.Stat(s.WorkingDir); errStat != nil {
		t.Fatalf("workspace copy missing: %v", errStat)
	}

	if errKill := sm.Kill(sid); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}
	if errRemove := sm.Remove(sid); errRemove != nil {
		t.Fatalf("remove: %v", errRemove)
	}
	if _, errStat := os.Stat(wantRoot); !errors.Is(errStat, os.ErrNotExist) {
		t.Fatalf("Remove left %s behind (stat err: %v)", wantRoot, errStat)
	}
}

internal/session/trust_removal_test.go.source:
package session_test

import (
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
)

type trustTestDriver struct {
	*driver.GenericCLIDriver

	prepare    func(context.Context, string) error
	spawnCheck func(string) error
	fail       bool
}

func (d *trustTestDriver) PrepareWorkspace(ctx context.Context, path string) error {
	return d.prepare(ctx, path)
}
func (d *trustTestDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	if d.spawnCheck != nil {
		if err := d.spawnCheck(cfg.WorkingDir); err != nil {
			return nil, err
		}
	}
	if d.fail {
		return nil, errors.New("spawn failed")
	}
	cfg.Driver = "cat"
	return d.GenericCLIDriver.Spawn(cfg)
}

//nolint:govet,gocognit,gocyclo,cyclop // Covers both trust grants, restart, cleanup failure and retry.
func TestTemporarySessionTrustCleanupSurvivesRestartAndCanRetry(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	repo, workspaceID := workspaceValidationRepository(t)
	registry := driver.NewRegistry()
	registry.Register("codex-test", func() driver.AgentDriver {
		return &trustTestDriver{GenericCLIDriver: driver.NewGenericCLIDriver(), prepare: driver.NewCodexCLIDriver().PrepareWorkspace}
	})
	registry.Register("claude-test", func() driver.AgentDriver {
		return &trustTestDriver{GenericCLIDriver: driver.NewGenericCLIDriver(), prepare: driver.NewClaudeCodeDriver().PrepareWorkspace,
			spawnCheck: func(path string) error {
				data, err := os.ReadFile(filepath.Join(home, ".claude.json"))
				if err != nil {
					return err
				}
				var cfg struct {
					Projects map[string]map[string]json.RawMessage `json:"projects"`
				}
				if err = json.Unmarshal(data, &cfg); err != nil {
					return err
				}
				if string(cfg.Projects[path]["hasTrustDialogAccepted"]) != "true" {
					return errors.New("Claude trust absent before spawn")
				}
				return nil
			}}
	})
	legacy := filepath.Join(home, ".claude", "settings.json")
	if err := os.MkdirAll(filepath.Dir(legacy), 0700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(legacy, []byte("{legacy-invalid"), 0600); err != nil {
		t.Fatal(err)
	}
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
	card := config.IDCard{ID: "a", Name: "a", Driver: "codex-test", WorkspaceID: workspaceID, UseTmpWorkspace: true}
	id, err := testLaunch(manager, card, nil, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	snap, ok := manager.GetSession(id)
	if !ok {
		t.Fatal("missing session")
	}
	if err := manager.Kill(id); err != nil {
		t.Fatal(err)
	}
	claudePath := filepath.Join(home, ".claude.json")
	seed := `{"root":"preserve","projects":{"/other":{"hasTrustDialogAccepted":true},` +
		strconv.Quote(snap.WorkingDir) + `:{"keep":"metadata"}}}`
	if err := os.WriteFile(claudePath, []byte(seed), 0600); err != nil {
		t.Fatal(err)
	}
	card.ID = "b"
	card.Driver = "claude-test"
	if err := testSwitchAgent(manager, id, card, nil, nil, nil); err != nil {
		t.Fatal(err)
	}
	var before struct {
		Projects map[string]map[string]json.RawMessage `json:"projects"`
	}
	claudeData, err := os.ReadFile(claudePath)
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(claudeData, &before); err != nil {
		t.Fatal(err)
	}
	if string(before.Projects[snap.WorkingDir]["hasTrustDialogAccepted"]) != "true" || before.Projects[snap.OriginalDir] != nil {
		t.Fatalf("wrong workspace trust: %s", claudeData)
	}
	if err := manager.Kill(id); err != nil {
		t.Fatal(err)
	}
	manager.Shutdown()
	restored := newTestManager(t, repo.Dir(), repo)
	valid, err := os.ReadFile(claudePath)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(claudePath, []byte("{"), 0600); err != nil {
		t.Fatal(err)
	}
	result, err := restored.RemoveDetailed(id)
	if !errors.Is(err, session.ErrTrustCleanup) || result.InMemoryRemoved {
		t.Fatalf("expected retryable failure: %#v %v", result, err)
	}
	if _, ok := restored.GetSession(id); !ok {
		t.Fatal("failed deletion discarded session")
	}
	if _, err := os.Stat(snap.WorkingDir); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(claudePath, valid, 0600); err != nil {
		t.Fatal(err)
	}
	result, err = restored.RemoveDetailed(id)
	if err != nil || !result.InMemoryRemoved || !result.TemporaryWorkspaceRemoved {
		t.Fatalf("retry failed: %#v %v", result, err)
	}
	codex, err := os.ReadFile(filepath.Join(home, ".codex/config.toml"))
	if err != nil || strings.Contains(string(codex), snap.WorkingDir) {
		t.Fatalf("Codex trust remains: %v", err)
	}
	cleaned, err := os.ReadFile(claudePath)
	if err != nil {
		t.Fatal(err)
	}
	var after struct {
		Root     string                                `json:"root"`
		Projects map[string]map[string]json.RawMessage `json:"projects"`
	}
	if err = json.Unmarshal(cleaned, &after); err != nil {
		t.Fatal(err)
	}
	if after.Root != "preserve" || after.Projects["/other"] == nil ||
		after.Projects[snap.WorkingDir]["hasTrustDialogAccepted"] != nil ||
		string(after.Projects[snap.WorkingDir]["keep"]) != `"metadata"` {
		t.Fatalf("cleanup lost project data: %s", cleaned)
	}
	legacyData, err := os.ReadFile(legacy)
	if err != nil || string(legacyData) != "{legacy-invalid" {
		t.Fatalf("legacy settings changed: %q %v", legacyData, err)
	}
}

//nolint:govet // Error variables are scoped to individual test assertions.
func TestNonTemporarySessionDeletionPreservesTrust(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	repo, workspaceID := workspaceValidationRepository(t)
	manager := newTestManager(t, repo.Dir(), repo)
	id, err := testLaunch(manager, config.IDCard{ID: "a", Name: "a", Driver: "cat", WorkspaceID: workspaceID}, nil, nil, nil)
	if err != nil {
		t.Fatal(err)
	}
	snap, _ := manager.GetSession(id)
	if err := driver.NewCodexCLIDriver().PrepareWorkspace(context.Background(), snap.WorkingDir); err != nil {
		t.Fatal(err)
	}
	if err := driver.NewClaudeCodeDriver().PrepareWorkspace(context.Background(), snap.WorkingDir); err != nil {
		t.Fatal(err)
	}
	if err := manager.Kill(id); err != nil {
		t.Fatal(err)
	}
	if err := manager.Remove(id); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(home, ".codex/config.toml"))
	if err != nil || !strings.Contains(string(data), snap.WorkingDir) {
		t.Fatal("non-temporary trust was removed")
	}
	claude, err := os.ReadFile(filepath.Join(home, ".claude.json"))
	if err != nil || !strings.Contains(string(claude), "hasTrustDialogAccepted") || !strings.Contains(string(claude), snap.WorkingDir) {
		t.Fatal("non-temporary Claude trust was removed")
	}
}

func TestFailedTemporaryLaunchRemovesTrust(t *testing.T) {
	for _, tc := range []struct {
		name, path, grant string
		prepare           func(context.Context, string) error
	}{
		{"codex", ".codex/config.toml", "trust_level", driver.NewCodexCLIDriver().PrepareWorkspace},
		{"claude", ".claude.json", "hasTrustDialogAccepted", driver.NewClaudeCodeDriver().PrepareWorkspace},
	} {
		t.Run(tc.name, func(t *testing.T) {
			home := t.TempDir()
			t.Setenv("HOME", home)
			repo, workspaceID := workspaceValidationRepository(t)
			registry := driver.NewRegistry()
			registry.Register("fail", func() driver.AgentDriver {
				return &trustTestDriver{GenericCLIDriver: driver.NewGenericCLIDriver(), prepare: tc.prepare, fail: true}
			})
			manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
			_, err := testLaunch(manager,
				config.IDCard{ID: "a", Name: "a", Driver: "fail", WorkspaceID: workspaceID, UseTmpWorkspace: true},
				nil,
				nil,
				nil,
			)
			if err == nil {
				t.Fatal("expected spawn failure")
			}
			data, err := os.ReadFile(filepath.Join(home, tc.path))
			if err != nil {
				t.Fatal(err)
			}
			if strings.Contains(string(data), tc.grant) {
				t.Fatalf("failed launch left trust grant: %s", data)
			}
		})
	}
}

