package session_test

import (
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
)

func TestSessionIdleWordDetection(t *testing.T) {
	repo, _ := config.NewFileRepository(t.TempDir())
	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	sm := newTestManager(t, repo.Dir(), repo)
	card := config.IDCard{
		ID:          "card-idle",
		Name:        "idle",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	}

	sid, err := testLaunch(sm, card, nil, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	defer sm.Kill(sid)

	handle, errAttach := testAttach(sm, sid)
	if errAttach != nil {
		t.Fatalf("attach: %v", errAttach)
	}
	defer handle.Close()

	// Send non-word animation characters
	if _, errWrite := handle.Input.Write([]byte("...")); errWrite != nil {
		t.Fatalf("write: %v", errWrite)
	}
	time.Sleep(100 * time.Millisecond)

	// Should still be running
	running := false
	for _, s := range sm.List() {
		if s.ID == sid && s.Status == session.StatusRunning {
			running = true
		}
	}
	if !running {
		t.Fatalf("expected session to be running after non-word output")
	}

	// Manually advance the "last word" time to simulate 16s silence in the test
	sm.SetLastWordAt(sid, time.Now().Add(-16*time.Second))

	// Wait for the watcher ticker (2s)
	time.Sleep(2500 * time.Millisecond)

	waiting := false
	for _, s := range sm.List() {
		if s.ID == sid && s.Status == session.StatusWaiting {
			waiting = true
		}
	}
	if !waiting {
		t.Fatalf("expected session to become waiting after 15s of word silence")
	}
}

// TestRelaunchSurvivesStaleWatchers reproduces a Kill->Relaunch cycle and
// asserts that the previous activation's watch/trackOutput goroutines do not
// clobber the freshly relaunched session once the watch ticker fires again.
func TestRelaunchSurvivesStaleWatchers(t *testing.T) {
	repo, _ := config.NewFileRepository(t.TempDir())
	wd := t.TempDir()
	_ = repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: wd, IsRoot: false}})
	workspaces, _ := repo.ListWorkspaces()

	sm := newTestManager(t, repo.Dir(), repo)
	card := config.IDCard{
		ID:          "card-relaunch-race",
		Name:        "relaunch-race",
		Driver:      "cat",
		WorkspaceID: workspaces[0].ID,
	}

	sid, err := testLaunch(sm, card, nil, nil, nil)
	if err != nil {
		t.Fatalf("launch: %v", err)
	}
	if errKill := sm.Kill(sid); errKill != nil {
		t.Fatalf("kill: %v", errKill)
	}

	if errRelaunch := testRelaunch(sm, sid, card); errRelaunch != nil {
		t.Fatalf("relaunch: %v", errRelaunch)
	}
	defer sm.Kill(sid)

	// Attach BEFORE the stale watcher's tick. A subscriber channel closed by
	// the stale watcher's closeSubscribersLocked is irreversible, unlike
	// Status, which the new watcher repaints on its own next tick a moment
	// later - so attaching first is what makes this test actually catch the
	// bug instead of observing a self-healed state.
	handle, errAttach := testAttach(sm, sid)
	if errAttach != nil {
		t.Fatalf("attach after relaunch: %v", errAttach)
	}
	defer handle.Close()

	// Wait past the watch interval so the stale (pre-relaunch) watch/
	// trackOutput goroutines would have had a chance to fire and clobber the
	// new session, if the generation guard were missing. Margin above the 2s
	// watchInterval to keep this reliable under CI load.
	time.Sleep(3 * time.Second)

	s, ok := sm.GetSession(sid)
	if !ok {
		t.Fatalf("session not found after relaunch")
	}
	if s.Status == session.StatusTerminated {
		t.Fatalf("expected session to still be running/waiting after relaunch, got %s", s.Status)
	}

	if !sm.BroadcastOutput(sid, []byte("ping")) {
		t.Fatalf("expected session to still accept broadcasts after relaunch")
	}
	select {
	case data, chOpen := <-handle.Output:
		if !chOpen {
			t.Fatalf("subscriber channel closed unexpectedly after relaunch")
		}
		if string(data) != "ping" {
			t.Fatalf("expected 'ping', got %q", data)
		}
	case <-time.After(time.Second):
		t.Fatalf("timed out waiting for broadcast on relaunched session")
	}
}

internal/session/workspace_mcp_concurren.source:
package session_test

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/BlackGiack/kankuro/internal/api"
	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/mcp"
	"github.com/BlackGiack/kankuro/internal/session"
)

const workspaceMCPInterleaveTimeout = 3 * time.Second

type killGateDriver struct {
	*driver.GenericCLIDriver

	entered chan struct{}
	release <-chan struct{}
}

type spawnFailGateDriver struct {
	*driver.GenericCLIDriver

	entered chan struct{}
	release <-chan struct{}
}

type cancellationSpawnDriver struct {
	*driver.GenericCLIDriver

	entered    chan struct{}
	release    <-chan struct{}
	spawnCalls atomic.Int32
	terminated atomic.Bool
}

func (d *cancellationSpawnDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	if d.spawnCalls.Add(1) == 1 {
		close(d.entered)
		<-d.release
	}
	cfg.Driver = "cat"
	return d.GenericCLIDriver.Spawn(cfg)
}

func (d *cancellationSpawnDriver) Kill() error {
	d.terminated.Store(true)
	return d.GenericCLIDriver.Kill()
}

func (d *spawnFailGateDriver) Spawn(_ driver.AgentConfig) (*driver.SessionHandle, error) {
	d.entered <- struct{}{}
	<-d.release
	return nil, errors.New("controlled older spawn failure")
}

func (d *killGateDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	cfg.Driver = "cat"
	return d.GenericCLIDriver.Spawn(cfg)
}

func (d *killGateDriver) Kill() error {
	select {
	case d.entered <- struct{}{}:
	default:
	}
	<-d.release
	return d.GenericCLIDriver.Kill()
}

//nolint:cyclop,gocognit,gocyclo,govet // Controlled kill interleavings exercise shared-config ownership for each selection mode.
func TestOlderSharedWorkspaceCleanupPreservesNewerSelection(t *testing.T) {
	for _, test := range []struct {
		name         string
		newServers   []config.MCPServer
		wantKankuro  bool
		wantOrdinary bool
	}{
		{
			name:        "new activation selects Kankuro and ordinary",
			newServers:  append(config.BuiltinMCPs(), config.MCPServer{ID: "ordinary", Name: "ordinary", URL: "https://ordinary"}),
			wantKankuro: true, wantOrdinary: true,
		},
		{
			name:         "new activation selects ordinary only",
			newServers:   []config.MCPServer{{ID: "ordinary", Name: "ordinary", URL: "https://ordinary"}},
			wantOrdinary: true,
		},
		{name: "new activation selects nothing"},
	} {
		t.Run(test.name, func(t *testing.T) {
			repo, err := config.NewFileRepository(t.TempDir())
			if err != nil {
				t.Fatal(err)
			}
			workspace := t.TempDir()
			if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
				t.Fatal(err)
			}
			workspaces, err := repo.ListWorkspaces()
			if err != nil || len(workspaces) != 1 {
				t.Fatalf("workspaces: %v", err)
			}
			registry := driver.NewBuiltinRegistry()
			killEntered := make(chan struct{}, 1)
			killRelease := make(chan struct{})
			var releaseOnce sync.Once
			releaseKill := func() { releaseOnce.Do(func() { close(killRelease) }) }
			registry.Register("kill-gate", func() driver.AgentDriver {
				return &killGateDriver{
					GenericCLIDriver: driver.NewGenericCLIDriver(),
					entered:          killEntered,
					release:          killRelease,
				}
			})
			manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
			runtime, err := mcp.Start(api.New(repo, manager))
			if err != nil {
				t.Fatal(err)
			}
			t.Cleanup(func() {
				ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
				defer cancel()
				if err := runtime.Shutdown(ctx); err != nil {
					t.Errorf("shutdown MCP runtime: %v", err)
				}
			})
			t.Cleanup(func() { manager.Shutdown() })
			t.Cleanup(releaseKill)
			manager.SetMCPEndpoint(runtime.Endpoint())

			metadataPath := filepath.Join(workspace, ".kankuro", "sub-workspaces.json")
			if err := os.MkdirAll(filepath.Dir(metadataPath), 0o700); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(metadataPath, []byte(`{"preserve":true}`), 0o600); err != nil {
				t.Fatal(err)
			}
			olderCard := config.IDCard{ID: "older", Name: "older", Driver: "kill-gate", WorkspaceID: workspaces[0].ID}
			olderID, err := testLaunch(manager, olderCard, nil, nil, config.BuiltinMCPs())
			if err != nil {
				t.Fatalf("launch older activation: %v", err)
			}
			olderToken := tokenFromConfig(t, driver.MCPConfigPath(workspace))

			newerCard := config.IDCard{ID: "newer", Name: "newer", Driver: "cat", WorkspaceID: workspaces[0].ID}
			newerID, err := testLaunch(manager, newerCard, nil, nil, test.newServers)
			if err != nil {
				t.Fatalf("launch newer activation: %v", err)
			}
			mcpPath := driver.MCPConfigPath(workspace)
			newerBytes, err := os.ReadFile(mcpPath)
			if err != nil {
				t.Fatal(err)
			}
			var newerConfig struct {
				MCPServers map[string]struct {
					Headers map[string]string `json:"headers"`
				} `json:"mcpServers"`
			}
			if err := json.Unmarshal(newerBytes, &newerConfig); err != nil {
				t.Fatal(err)
			}
			if _, found := newerConfig.MCPServers["kankuro"]; found != test.wantKankuro {
				t.Fatalf("newer Kankuro selection = %v, want %v", found, test.wantKankuro)
			}
			if _, found := newerConfig.MCPServers["ordinary"]; found != test.wantOrdinary {
				t.Fatalf("newer ordinary selection = %v, want %v", found, test.wantOrdinary)
			}
			var newerToken string
			if test.wantKankuro {
				newerToken = strings.TrimPrefix(newerConfig.MCPServers["kankuro"].Headers["Authorization"], "Bearer ")
				if newerToken == olderToken {
					t.Fatal("concurrent activation reused the older credential")
				}
			}

			killResult := make(chan error, 1)
			go func() { killResult <- manager.Kill(olderID) }()
			select {
			case <-killEntered:
			case <-time.After(workspaceMCPInterleaveTimeout):
				t.Fatal("older activation kill did not reach the controlled interleaving")
			}
			releaseKill()
			select {
			case err := <-killResult:
				if err != nil {
					t.Fatalf("kill older activation: %v", err)
				}
			case <-time.After(workspaceMCPInterleaveTimeout):
				t.Fatal("older activation cleanup did not finish")
			}
			afterOlderCleanup, err := os.ReadFile(mcpPath)
			if err != nil || !bytes.Equal(afterOlderCleanup, newerBytes) {
				t.Fatalf("older cleanup modified newer config: err=%v before=%s after=%s", err, newerBytes, afterOlderCleanup)
			}
			if _, err := manager.RegisterConversation(olderToken, "stale-id", "stale"); err == nil {
				t.Fatal("older credential remained authorized after kill")
			}
			if test.wantKankuro {
				if _, err := manager.RegisterConversation(newerToken, "newer-id", "newer"); err != nil {
					t.Fatalf("newer credential was revoked by older cleanup: %v", err)
				}
			}
			if err := manager.Kill(newerID); err != nil {
				t.Fatal(err)
			}
			metadata, err := os.ReadFile(metadataPath)
			if err != nil || string(metadata) != `{"preserve":true}` {
				t.Fatalf("cleanup changed sub-workspace metadata: %q, %v", metadata, err)
			}
		})
	}
}

//nolint:govet // Controlled launch synchronization asserts that failed cleanup preserves newer workspace state.
func TestFailedOlderActivationCannotCleanupNewerWorkspaceConfig(t *testing.T) {
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", err)
	}
	spawnEntered := make(chan struct{}, 1)
	spawnRelease := make(chan struct{})
	var releaseOnce sync.Once
	releaseSpawn := func() { releaseOnce.Do(func() { close(spawnRelease) }) }
	registry := driver.NewBuiltinRegistry()
	registry.Register("spawn-fail", func() driver.AgentDriver {
		return &spawnFailGateDriver{
			GenericCLIDriver: driver.NewGenericCLIDriver(),
			entered:          spawnEntered,
			release:          spawnRelease,
		}
	})
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
	runtime, err := mcp.Start(api.New(repo, manager))
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := runtime.Shutdown(ctx); err != nil {
			t.Errorf("shutdown MCP runtime: %v", err)
		}
	})
	t.Cleanup(func() { manager.Shutdown() })
	t.Cleanup(releaseSpawn)
	manager.SetMCPEndpoint(runtime.Endpoint())
	olderCard := config.IDCard{ID: "older", Name: "older", Driver: "spawn-fail", WorkspaceID: workspaces[0].ID}
	olderResult := make(chan error, 1)
	go func() {
		_, launchErr := testLaunch(manager, olderCard, nil, nil, config.BuiltinMCPs())
		olderResult <- launchErr
	}()
	select {
	case <-spawnEntered:
	case <-time.After(workspaceMCPInterleaveTimeout):
		t.Fatal("older activation did not reach its blocked spawn")
	}
	newerCard := config.IDCard{ID: "newer", Name: "newer", Driver: "cat", WorkspaceID: workspaces[0].ID}
	newerID, err := testLaunch(manager, newerCard, nil, nil, config.BuiltinMCPs())
	if err != nil {
		t.Fatalf("launch newer activation: %v", err)
	}
	path := driver.MCPConfigPath(workspace)
	newerConfig, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	newerToken := tokenFromConfig(t, path)
	releaseSpawn()
	select {
	case launchErr := <-olderResult:
		if launchErr == nil || !strings.Contains(launchErr.Error(), "controlled older spawn failure") {
			t.Fatalf("older launch error = %v, want controlled spawn failure", launchErr)
		}
	case <-time.After(workspaceMCPInterleaveTimeout):
		t.Fatal("older failed activation did not finish cleanup")
	}
	configAfterCleanup, err := os.ReadFile(path)
	if err != nil || !bytes.Equal(configAfterCleanup, newerConfig) {
		t.Fatalf("failed older cleanup changed newer config: err=%v", err)
	}
	if _, err := manager.RegisterConversation(newerToken, "newer-id", "newer"); err != nil {
		t.Fatalf("newer credential was revoked by failed older cleanup: %v", err)
	}
	if err := manager.Kill(newerID); err != nil {
		t.Fatal(err)
	}
}

func TestCancellationAfterMCPConfigBeforeSpawnRevokesAndUnpublishes(t *testing.T) {
	skillContent, skillErr := os.ReadFile("../../kankuro_skills/mcp-cli/SKILL.md")
	if skillErr != nil {
		t.Fatal(skillErr)
	}
	config.SetBuiltinMCPCLISkillContent(skillContent)
	t.Cleanup(func() { config.SetBuiltinMCPCLISkillContent(nil) })
	configDir := t.TempDir()
	tmpRoot := t.TempDir()
	t.Setenv("KANKURO_TMP_DIR", tmpRoot)
	repo, setupErr := config.NewFileRepository(configDir)
	if setupErr != nil {
		t.Fatal(setupErr)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, listErr := repo.ListWorkspaces()
	if listErr != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", listErr)
	}
	entered, release := make(chan struct{}), make(chan struct{})
	driverRegistry := driver.NewBuiltinRegistry()
	gatedDriver := &cancellationSpawnDriver{
		GenericCLIDriver: driver.NewGenericCLIDriver(), entered: entered, release: release,
	}
	driverRegistry.Register("cancel-spawn", func() driver.AgentDriver {
		return gatedDriver
	})
	manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(driverRegistry))
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	card := config.IDCard{
		ID: "controller", Name: "controller", Driver: "cancel-spawn", WorkspaceID: workspaces[0].ID,
		UseTmpWorkspace: true, DashboardControl: true, MCPIDs: []string{config.BuiltinMCPKankuro},
	}
	sessionID := "a9e0e5eb-32d7-4a94-8548-43db75642f8c"
	activationContext, cancelActivation := context.WithCancel(context.Background())
	defer cancelActivation()
	launchResult := make(chan error, 1)
	go func() {
		_, launchErr := testLaunchWithIDContext(manager,
			activationContext, sessionID, card, nil, nil, config.BuiltinMCPs(),
		)
		launchResult <- launchErr
	}()
	select {
	case <-entered:
	case <-time.After(workspaceMCPInterleaveTimeout):
		close(release)
		t.Fatal("activation did not reach gated spawn after MCP config publication")
	}
	workspaceCopy := filepath.Join(tmpRoot, sessionID, filepath.Base(workspace))
	token := tokenFromConfig(t, driver.MCPConfigPath(workspaceCopy))
	if !manager.HasActivationCredential(token) {
		t.Fatal("published pre-spawn credential was not live at the gate")
	}
	cancelActivation()
	close(release)
	select {
	case launchErr := <-launchResult:
		if !errors.Is(launchErr, context.Canceled) {
			t.Fatalf("cancelled launch error = %v, want context cancellation", launchErr)
		}
	case <-time.After(workspaceMCPInterleaveTimeout):
		t.Fatal("cancelled activation did not return")
	}
	if manager.HasActivationCredential(token) {
		t.Fatal("cancelled unpublished activation credential remained authorized")
	}
	if _, exists := manager.GetSession(sessionID); exists {
		t.Fatal("cancelled activation was published into the session registry")
	}
	if gatedDriver == nil || !gatedDriver.terminated.Load() {
		t.Fatal("process spawned after cancellation was not torn down")
	}
	if _, statErr := os.Stat(filepath.Join(tmpRoot, sessionID)); !os.IsNotExist(statErr) {
		t.Fatalf("cancelled activation left its temporary workspace: %v", statErr)
	}
	if _, retryErr := testLaunchWithIDContext(manager,
		context.Background(), sessionID, card, nil, nil, config.BuiltinMCPs(),
	); retryErr != nil {
		t.Fatalf("activation reservation was not released: %v", retryErr)
	}
	if killErr := manager.Kill(sessionID); killErr != nil {
		t.Fatal(killErr)
	}
	if _, removeErr := manager.RemoveDetailed(sessionID); removeErr != nil {
		t.Fatalf("remove retried temporary activation: %v", removeErr)
	}
}

