	assertFileContent(t, manual, "same-card switch refresh")
	if killErr := sm.Kill(sid); killErr != nil {
		t.Fatalf("kill after same-card switch: %v", killErr)
	}
}

//nolint:gocognit // each subtest exercises the complete restart/preservation contract for one workspace mode.
func TestRelaunchPreservesDeployedConfigurationAcrossRestart(t *testing.T) {
	for _, useTmp := range []bool{false, true} {
		t.Run(map[bool]string{false: "original", true: "temporary"}[useTmp], func(t *testing.T) {
			repo, setupErr := config.NewFileRepository(t.TempDir())
			if setupErr != nil {
				t.Fatal(setupErr)
			}
			mainDir, subDir, newSubDir := t.TempDir(), t.TempDir(), t.TempDir()
			skillSrc, personaSrc := t.TempDir(), filepath.Join(t.TempDir(), "persona.md")
			writeTestFile(t, filepath.Join(skillSrc, "SKILL.md"), "skill source")
			writeTestFile(t, personaSrc, "persona source")
			writeTestFile(t, filepath.Join(subDir, "sub.txt"), "sub source")
			writeTestFile(t, filepath.Join(newSubDir, "new.txt"), "new source")
			workspaceSources := []config.WorkspaceSource{{Path: mainDir}, {Path: subDir}, {Path: newSubDir}}
			if saveErr := repo.SaveWorkspaceSources(workspaceSources); saveErr != nil {
				t.Fatal(saveErr)
			}
			workspaces, workspaceErr := repo.ListWorkspaces()
			if workspaceErr != nil {
				t.Fatal(workspaceErr)
			}
			workspaceID := workspaceIDForPath(t, workspaces, mainDir)
			subID := workspaceIDForPath(t, workspaces, subDir)
			newSubID := workspaceIDForPath(t, workspaces, newSubDir)
			skill, skillErr := repo.UpsertSkill(config.Skill{ID: "skill-old", Name: "old-skill", Source: skillSrc})
			if skillErr != nil {
				t.Fatal(skillErr)
			}
			persona, personaErr := repo.UpsertPersona(config.Persona{ID: "persona-old", Name: "old-persona", Source: personaSrc})
			if personaErr != nil {
				t.Fatal(personaErr)
			}
			mcp := config.MCPServer{ID: "mcp-old", Name: "old", Command: "old-command"}
			if _, err := repo.UpsertMCP(mcp); err != nil {
				t.Fatal(err)
			}
			card := config.IDCard{
				ID: "preserve-card", Name: "preserve", Driver: "cat", WorkspaceID: workspaceID,
				UseTmpWorkspace: useTmp, SkillIDs: []string{skill.ID}, PersonaIDs: []string{persona.ID},
				MCPIDs: []string{mcp.ID}, AgentsMD: "original instruction", SubWorkspaceIDs: []string{subID},
			}
			sm := newTestManager(t, repo.Dir(), repo)
			sid, launchErr := testLaunch(sm, card, []config.Skill{skill}, []config.Persona{persona}, []config.MCPServer{mcp})
			if launchErr != nil {
				t.Fatalf("launch: %v", launchErr)
			}
			before, _ := sm.GetSession(sid)
			configRoot := before.WorkingDir
			skillPath := filepath.Join(configRoot, ".agents", "skills", "old-skill", "SKILL.md")
			personaPath := filepath.Join(configRoot, ".agents", "agents", "old-persona.md")
			mcpPath := filepath.Join(configRoot, ".kankuro", "mcp-servers.json")
			manifestPath := filepath.Join(configRoot, ".kankuro", "sub-workspaces.json")
			subCopy := filepath.Join(configRoot, "tmp", filepath.Base(subDir))
			writeTestFile(t, skillPath, "user-edited skill")
			writeTestFile(t, personaPath, "user-edited persona")
			writeTestFile(t, mcpPath, "user-edited mcp config")
			manifestBefore, manifestErr := os.ReadFile(manifestPath)
			if manifestErr != nil {
				t.Fatal(manifestErr)
			}
			deletePaths := []string{skillPath, filepath.Join(subCopy, "sub.txt")}
			for _, path := range deletePaths {
				if err := os.Remove(path); err != nil {
					t.Fatal(err)
				}
			}
			if err := sm.Kill(sid); err != nil {
				t.Fatal(err)
			}
			if got, ok := sm.GetSession(sid); !ok {
				t.Fatal("session disappeared")
			} else {
				before = got
			}
			if sm.Shutdown() != 0 {
				t.Fatal("expected no running sessions at restart")
			}
			sm = newTestManager(t, repo.Dir(), repo)
			card.SkillIDs, card.PersonaIDs, card.MCPIDs = nil, nil, nil
			card.AgentsMD = "edited card instruction"
			card.SubWorkspaceIDs = []string{newSubID}
			card.UseTmpWorkspace = !useTmp // relaunch must not adopt the edited ownership mode
			if err := testRelaunch(sm, sid, card); err != nil {
				t.Fatalf("relaunch after manager restart: %v", err)
			}
			assertFileContent(t, personaPath, "user-edited persona")
			assertFileContent(t, mcpPath, "user-edited mcp config")
			assertAbsent(t, skillPath)
			assertAbsent(t, filepath.Join(subCopy, "sub.txt"))
			assertAbsent(t, filepath.Join(configRoot, "tmp", filepath.Base(newSubDir)))
			manifestAfter, manifestErr := os.ReadFile(manifestPath)
			if manifestErr != nil || string(manifestAfter) != string(manifestBefore) {
				t.Fatalf("relaunch changed sub-workspace ownership manifest: %s, %v", manifestAfter, manifestErr)
			}
			after, ok := sm.GetSession(sid)
			if !ok || after.WorkingDir != before.WorkingDir || after.OriginalDir != before.OriginalDir || after.UseTmpWorkspace != useTmp {
				t.Fatalf("relaunch changed session workspace metadata: %+v", after)
			}
			persisted, persistErr := os.ReadFile(filepath.Join(repo.Dir(), "sessions", sid+".json"))
			if persistErr != nil {
				t.Fatal(persistErr)
			}
			var record session.Data
			if err := json.Unmarshal(persisted, &record); err != nil {
				t.Fatal(err)
			}
			if record.WorkingDir != before.WorkingDir || record.OriginalDir != before.OriginalDir || record.UseTmpWorkspace != useTmp {
				t.Fatalf("persisted workspace metadata changed: %+v", record)
			}
			if err := sm.Kill(sid); err != nil {
				t.Fatal(err)
			}
		})
	}
}

//nolint:gocognit,gocyclo,cyclop,govet // Exercises deployed credential authorization across lifecycle transitions and legacy loading.
func TestDashboardControlDeploymentAcrossRelaunchReloadAndSwitch(t *testing.T) {
	skillContent, skillErr := os.ReadFile("../../kankuro_skills/mcp-cli/SKILL.md")
	if skillErr != nil {
		t.Fatal(skillErr)
	}
	config.SetBuiltinMCPCLISkillContent(skillContent)
	t.Cleanup(func() { config.SetBuiltinMCPCLISkillContent(nil) })
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if err := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); err != nil {
		t.Fatal(err)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("list workspace: %v (%d)", err, len(workspaces))
	}
	manager := newTestManager(t, repo.Dir(), repo)
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	card := config.IDCard{ID: "controller", Name: "controller", Driver: "cat", WorkspaceID: workspaces[0].ID,
		DashboardControl: true, MCPIDs: []string{config.BuiltinMCPKankuro}}
	secondCard := card
	secondCard.ID, secondCard.Name = "second-controller", "second controller"
	secondCard.DashboardControl = true
	sessionID, err := testLaunch(manager, card, nil, nil, config.BuiltinMCPs())
	if err != nil {
		t.Fatalf("launch opted-in card: %v", err)
	}
	configPath := filepath.Join(workspace, ".kankuro", "mcp-servers.json")
	firstToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(firstToken); err != nil {
		t.Fatalf("initial deployed grant was denied: %v", err)
	}
	card.DashboardControl = false
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if err := testRelaunch(manager, sessionID, card); err != nil {
		t.Fatalf("relaunch after card grant edit: %v", err)
	}
	relaunchedToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(relaunchedToken); err != nil {
		t.Fatalf("ordinary relaunch did not preserve deployed grant: %v", err)
	}
	if manager.HasActivationCredential(firstToken) {
		t.Fatal("relaunch left the prior activation credential authorized")
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if manager.Shutdown() != 0 {
		t.Fatal("manager shutdown reported running sessions")
	}
	manager = newTestManager(t, repo.Dir(), repo)
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	if err := testRelaunch(manager, sessionID, card); err != nil {
		t.Fatalf("relaunch after persisted manager reload: %v", err)
	}
	reloadedToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(reloadedToken); err != nil {
		t.Fatalf("persisted deployed grant was not preserved across reload: %v", err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if manager.Shutdown() != 0 {
		t.Fatal("manager shutdown reported running sessions")
	}
	// A pre-grant-era record has no dashboard_control field; its zero value must
	// remain registration-only even when the Kankuro server was deployed.
	recordPath := filepath.Join(repo.Dir(), "sessions", sessionID+".json")
	recordData, err := os.ReadFile(recordPath)
	if err != nil {
		t.Fatal(err)
	}
	var legacyRecord map[string]json.RawMessage
	if err := json.Unmarshal(recordData, &legacyRecord); err != nil {
		t.Fatal(err)
	}
	delete(legacyRecord, "dashboard_control")
	recordData, err = json.Marshal(legacyRecord)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(recordPath, recordData, 0o600); err != nil {
		t.Fatal(err)
	}
	manager = newTestManager(t, repo.Dir(), repo)
	manager.SetMCPEndpoint("http://127.0.0.1:43210/mcp")
	if err := testRelaunch(manager, sessionID, card); err != nil {
		t.Fatalf("legacy relaunch: %v", err)
	}
	legacyToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(legacyToken); err == nil {
		t.Fatal("legacy record without dashboard_control gained dashboard authority")
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if err := testSwitchAgent(manager, sessionID, card, nil, nil, config.BuiltinMCPs()); err != nil {
		t.Fatalf("switch to same card with current opt-out: %v", err)
	}
	sameCardToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(sameCardToken); err == nil {
		t.Fatal("same-card explicit switch did not apply the current opt-out")
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
	if err := testSwitchAgent(manager, sessionID, secondCard, nil, nil, config.BuiltinMCPs()); err != nil {
		t.Fatalf("switch to opted-in card: %v", err)
	}
	secondToken := readRelaunchToken(t, configPath)
	if _, err := manager.ResolveDashboardCaller(secondToken); err != nil {
		t.Fatalf("explicit switch did not apply destination grant: %v", err)
	}
	if err := manager.Kill(sessionID); err != nil {
		t.Fatal(err)
	}
}

func writeTestFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
}

func assertFileContent(t *testing.T, path, want string) {
	t.Helper()
	got, err := os.ReadFile(path)
	if err != nil || string(got) != want {
		t.Fatalf("%s: content=%q err=%v, want %q", path, got, err, want)
	}
}

func assertAbsent(t *testing.T, path string) {
	t.Helper()
	if _, err := os.Lstat(path); !os.IsNotExist(err) {
		t.Fatalf("expected %s to remain absent, err=%v", path, err)
	}
}

func workspaceIDForPath(t *testing.T, workspaces []config.Workspace, path string) string {
	t.Helper()
	for _, workspace := range workspaces {
		if workspace.Path == path {
			return workspace.ID
		}
	}
	t.Fatalf("workspace not found for %s", path)
	return ""
}

internal/session/workspace_validation_te.source:
package session_test

import (
	"os"
	"path/filepath"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
	"github.com/BlackGiack/kankuro/internal/session"
)

type workspaceValidationDriver struct {
	*driver.GenericCLIDriver

	spawns *atomic.Int32
}

func (d *workspaceValidationDriver) Spawn(cfg driver.AgentConfig) (*driver.SessionHandle, error) {
	d.spawns.Add(1)
	return d.GenericCLIDriver.Spawn(cfg)
}

//nolint:gocognit,govet // Each case verifies rejection, no mutation or spawn, and successful retry through the real lifecycle.
func TestActivationRejectsUnavailableSavedWorkspace(t *testing.T) {
	for _, test := range []struct {
		name        string
		useTmp      bool
		operation   string
		replacement string
	}{
		{"relaunch/missing/source", false, "relaunch", "missing"},
		{"relaunch/file/source", false, "relaunch", "file"},
		{"switch/missing/source", false, "switch", "missing"},
		{"switch/file/source", false, "switch", "file"},
		{"relaunch/missing/temporary", true, "relaunch", "missing"},
		{"relaunch/file/temporary", true, "relaunch", "file"},
		{"switch/missing/temporary", true, "switch", "missing"},
		{"switch/file/temporary", true, "switch", "file"},
	} {
		t.Run(test.name, func(t *testing.T) {
			repo, workspaceID := workspaceValidationRepository(t)
			var spawns atomic.Int32
			registry := driver.NewRegistry()
			registry.Register("cat", func() driver.AgentDriver {
				return &workspaceValidationDriver{GenericCLIDriver: driver.NewGenericCLIDriver(), spawns: &spawns}
			})
			manager := newTestManager(t, repo.Dir(), repo, session.WithDriverRegistry(registry))
			card := config.IDCard{ID: "a", Name: "A", Driver: "cat", WorkspaceID: workspaceID, UseTmpWorkspace: test.useTmp}
			id, err := testLaunch(manager, card, nil, nil, nil)
			if err != nil {
				t.Fatal(err)
			}
			if err := manager.Kill(id); err != nil {
				t.Fatal(err)
			}
			before, found := manager.GetSession(id)
			if !found {
				t.Fatal("session missing")
			}
			backup := filepath.Join(t.TempDir(), "saved-workspace")
			if err := os.Rename(before.WorkingDir, backup); err != nil {
				t.Fatal(err)
			}
			if test.replacement == "file" {
				if err := os.WriteFile(before.WorkingDir, []byte("keep this file"), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			activate := func() error { return testRelaunch(manager, id, card) }
			if test.operation == "switch" {
				card.ID = "b"
				activate = func() error { return testSwitchAgent(manager, id, card, nil, nil, nil) }
			}
			if err := activate(); err == nil || !strings.Contains(err.Error(), before.WorkingDir) {
				t.Fatalf("expected workspace error with saved path, got %v", err)
			}
			if spawns.Load() != 1 {
				t.Fatal("invalid workspace activation reached Spawn")
			}
			after, found := manager.GetSession(id)
			if !found || after.Status != session.StatusTerminated ||
				after.PID != before.PID || after.WorkingDir != before.WorkingDir {
				t.Fatalf("failed activation changed session identity or process: %#v", after)
			}
			if test.replacement == "missing" {
				if _, err := os.Lstat(before.WorkingDir); !os.IsNotExist(err) {
					t.Fatalf("missing workspace was recreated: %v", err)
				}
			} else {
				content, err := os.ReadFile(before.WorkingDir)
				if err != nil || string(content) != "keep this file" {
					t.Fatalf("replacement file changed: %q, %v", content, err)
				}
				if err := os.Remove(before.WorkingDir); err != nil {
					t.Fatal(err)
				}
			}
			if err := os.Rename(backup, before.WorkingDir); err != nil {
				t.Fatal(err)
			}
			if err := activate(); err != nil {
				t.Fatalf("retry after restoring workspace: %v", err)
			}
			if spawns.Load() != 2 {
				t.Fatal("retry did not spawn exactly one agent")
			}
			content, err := os.ReadFile(filepath.Join(before.WorkingDir, "work.txt"))
			if err != nil || string(content) != "saved work" {
				t.Fatalf("saved work lost after retry: %q, %v", content, err)
			}
		})
	}
}

func workspaceValidationRepository(t *testing.T) (*config.FileRepository, string) {
	t.Helper()
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	workspace := t.TempDir()
	if writeErr := os.WriteFile(filepath.Join(workspace, "work.txt"), []byte("saved work"), 0o600); writeErr != nil {
		t.Fatal(writeErr)
	}
	if saveErr := repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}); saveErr != nil {
		t.Fatal(saveErr)
	}
	workspaces, err := repo.ListWorkspaces()
	if err != nil || len(workspaces) != 1 {
		t.Fatalf("workspaces: %v", err)
	}
	return repo, workspaces[0].ID
}

internal/ui/components/capability_list_l.source:
package components_test

import (
	"fmt"
	"strings"
	"testing"

	bubbletea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/ui/components"
)

// Capability lists render exactly their assigned height. Row positions depend
// on size and unfiltered item count, not the cursor or search results.

type capItem struct{ id string }

func (i capItem) GetID() string          { return i.id }
func (i capItem) GetLabel() string       { return i.id }
func (i capItem) GetDescription() string { return "" }

func capItems(n int) []components.CapabilityItem {
	items := make([]components.CapabilityItem, n)
	for i := range items {
		items[i] = capItem{id: fmt.Sprintf("item-%02d", i)}
	}
	return items
}

func newSizedCapList(n, height int) *components.CapabilityList {
	l := components.NewCapabilityList(components.CapabilityListConfig{Title: "Skills", SourceHint: "hint", MaxVisible: 5})
	l.SetItems(capItems(n))
	l.SetSize(40, height)
	l.SetFocused(true)
	return l
}

func capLines(l *components.CapabilityList) []string {
	return strings.Split(ansi.Strip(l.View()), "\n")
}

// capQueries are a search that matches nothing special (none typed), one item,
// several, and nothing.
const ellipsisRow = "  ..."

var capQueries = []string{"", "item-07", "item-1", "zzz"} //nolint:gochecknoglobals // shared test fixture

// forEveryCapState calls fn for each cursor position of each query.
func forEveryCapState(l *components.CapabilityList, fn func(label string)) {
	for _, q := range capQueries {
		l.SetSearchQuery(q)
		n := len(l.FilteredItems())
		for pos := range max(n, 1) {
			l.SetCursor(pos)
			fn(fmt.Sprintf("query=%q cursor=%d", q, pos))
		}
	}
}

func TestCapabilityListRendersExactlyItsHeight(t *testing.T) {
	for height := 2; height <= 12; height++ {
		slots := height - 1
		for _, n := range []int{0, 1, slots, slots + 1, 30} {
			l := newSizedCapList(n, height)
			forEveryCapState(l, func(state string) {
				if got := len(capLines(l)); got != height {
					t.Errorf("height=%d items=%d %s: rendered %d lines, want %d:\n%s",
						height, n, state, got, height, ansi.Strip(l.View()))
				}
			})
		}
	}
}

func isCapItemRow(s string) bool {
	return strings.HasPrefix(strings.TrimLeft(s, "> "), "[") || strings.Contains(s, "(no matching items)")
}

// assertRowsInPlace checks one rendered state of a list of the given height:
// the header, the first item row, the indicator rows and the padding.
func assertRowsInPlace(t *testing.T, lines []string, height, firstItem int, overflow bool, label string) {
	t.Helper()
	if len(lines) != height {
		t.Fatalf("%s: %d lines, want %d", label, len(lines), height)
	}
	if !strings.HasPrefix(lines[0], "Skills (hint)") {
		t.Errorf("%s: row 0 is %q, want the header", label, lines[0])
	}
	if !isCapItemRow(lines[firstItem]) {
		t.Errorf("%s: row %d is %q, want the first item row:\n%s",
			label, firstItem, lines[firstItem], strings.Join(lines, "\n"))
	}
	if overflow {
		for _, row := range []int{1, height - 1} {
			if lines[row] != "" && lines[row] != ellipsisRow {
				t.Errorf("%s: row %d is %q, want blank or %q", label, row, lines[row], ellipsisRow)
			}
		}
	}
	for _, line := range lines[firstItem:] {
		if strings.TrimSpace(line) == "" && line != "" {
			t.Errorf("%s: padding line %q is not empty", label, line)
		}
	}
}

// assertIndicators checks that the "..." rows say which side has more.
func assertIndicators(t *testing.T, l *components.CapabilityList, n, height int) {
	t.Helper()
	l.SetSearchQuery("")
	for _, c := range []struct {
		name       string
		cursor     int
		top, final string
	}{
		{"top", 0, "", ellipsisRow},
		{"middle", n / 2, ellipsisRow, ellipsisRow},
		{"bottom", n - 1, ellipsisRow, ""},
	} {
		l.SetCursor(c.cursor)
		if lines := capLines(l); lines[1] != c.top || lines[height-1] != c.final {
			t.Errorf("height=%d items=%d %s: rows 1 and last are %q and %q, want %q and %q",
				height, n, c.name, lines[1], lines[height-1], c.top, c.final)
		}
	}
}

func TestCapabilityListItemsKeepTheirRows(t *testing.T) {
	for height := 4; height <= 12; height++ {
		slots := height - 1
		for _, n := range []int{2, slots, slots + 1, 30} {
			l := newSizedCapList(n, height)
			overflow := n > slots && slots >= 3
			firstItem := 1
			if overflow {
				firstItem = 2
			}
			forEveryCapState(l, func(state string) {
				assertRowsInPlace(t, capLines(l), height, firstItem, overflow, fmt.Sprintf("height=%d items=%d %s", height, n, state))
			})
			if overflow {
				assertIndicators(t, l, n, height)
			}
		}
	}
}

// TestCapabilityListScrollsThroughKeys drives the list the way the editor does
// and checks that the focused row is always rendered.
func TestCapabilityListScrollsThroughKeys(t *testing.T) {
	l := newSizedCapList(20, 7)
	for range 20 {
		plain := ansi.Strip(l.View())
		if !strings.Contains(plain, "> [") {
			t.Fatalf("cursor %d is not on screen:\n%s", l.Cursor(), plain)
		}
		l.Update(bubbletea.KeyPressMsg{Code: bubbletea.KeyDown})
	}
}

// TestCapabilityListUnsizedStillRenders: a list built before SetSize runs keeps
// the old, content-driven layout.
func TestCapabilityListUnsizedStillRenders(t *testing.T) {
	l := components.NewCapabilityList(components.CapabilityListConfig{Title: "Skills", MaxVisible: 3})
	l.SetItems(capItems(10))
	plain := ansi.Strip(l.View())
	if got := strings.Count(plain, "[ ]"); got != 3 {
		t.Errorf("unsized list shows %d items, want its MaxVisible (3):\n%s", got, plain)
	}
}

internal/ui/components/card_list_test.go.source:
package components_test

import (
	"strings"
	"testing"
	"unicode/utf8"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/components"
)

func TestCardList_New(t *testing.T) {
	callbacks := components.CardListCallbacks{
		OnSelect: func(config.IDCard) tea.Cmd {
			return nil
		},
		OnEdit: func(config.IDCard) tea.Cmd {
			return nil
		},
		OnDelete: func(string) {},
	}

	c := components.NewCardList(callbacks)
	if c == nil {
		t.Fatal("NewCardList returned nil")
	}

	// Check initial state
	if c.Focused {
		t.Error("CardList should not be focused initially")
	}
}

func TestCardList_SetCards(t *testing.T) {
	callbacks := components.CardListCallbacks{}
	c := components.NewCardList(callbacks)

	cards := []config.IDCard{
		{ID: "1", Name: "Card 1"},
		{ID: "2", Name: "Card 2"},
	}
	skills := []config.Skill{}
	personas := []config.Persona{}

	c.SetCards(cards, skills, personas)

	// Verify internal state updated
	if len(c.Cards()) != 2 {
		t.Errorf("Expected 2 cards, got %d", len(c.Cards()))
	}
}

func TestCardList_SetSearchQuery(t *testing.T) {
	callbacks := components.CardListCallbacks{}
	c := components.NewCardList(callbacks)

	cards := []config.IDCard{
		{ID: "1", Name: "Alpha"},
		{ID: "2", Name: "Beta"},
		{ID: "3", Name: "Gamma"},
	}

	c.SetCards(cards, nil, nil)

	// No filter
	filtered := c.FilteredCards()
	if len(filtered) != 3 {
		t.Errorf("Expected 3 cards without filter, got %d", len(filtered))
	}

	// With filter
	c.SetSearchQuery("al")
	filtered = c.FilteredCards()
	if len(filtered) != 1 {
		t.Errorf("Expected 1 card matching 'al', got %d", len(filtered))
	}
	if len(filtered) > 0 && filtered[0].ID != "1" {
		t.Errorf("Expected card ID '1', got '%s'", filtered[0].ID)
	}
}

func TestCardList_Selected(t *testing.T) {
	callbacks := components.CardListCallbacks{}
	c := components.NewCardList(callbacks)

	// No selection
	_, ok := c.Selected()
	if ok {
		t.Error("Selected should return false when no selection")
	}

	// Set cards and select first
	cards := []config.IDCard{
		{ID: "1", Name: "Test"},
	}
	c.SetCards(cards, nil, nil)
	c.Select(0)

	card, ok := c.Selected()
	if !ok {
		t.Error("Selected should return true when item selected")
	}
	if card.ID != "1" {
		t.Errorf("Expected card ID '1', got '%s'", card.ID)
	}
}

func TestRenderCardItem(t *testing.T) {
	card := config.IDCard{
		ID:     "1",
		Name:   "Test Card",
		Driver: "claude",
		Model:  "claude-3",
		Puppet: "kankuro",
	}

	skills := []config.Skill{
		{ID: "s1", Name: "Skill1"},
	}
	personas := []config.Persona{
		{ID: "p1", Name: "Persona1"},
	}

	// Render unselected
	output := components.RenderCardItem(card, skills, personas, nil, false, 50)
	if output == "" {
		t.Error("RenderCardItem returned empty string")
	}

	// Render selected
	outputSel := components.RenderCardItem(card, skills, personas, nil, true, 50)
	if outputSel == "" {
		t.Error("RenderCardItem (selected) returned empty string")
	}

	// Selected should be different (different border color)
	if output == outputSel {
		t.Error("Selected and unselected should render differently")
	}
}

func TestRenderCardItemWithPills(t *testing.T) {
	// Test with skills and personas
	card := config.IDCard{
		ID:         "1",
		Name:       "Test Card",
		Driver:     "claude",
		Model:      "claude-3",
		Puppet:     "kankuro",
		SkillIDs:   []string{"s1", "s2"},
		PersonaIDs: []string{"p1"},
	}

	skills := []config.Skill{
		{ID: "s1", Name: "Skill1"},
		{ID: "s2", Name: "Skill2"},
	}
	personas := []config.Persona{
		{ID: "p1", Name: "Persona1"},
	}

	output := components.RenderCardItem(card, skills, personas, nil, false, 50)

	// Should contain skill and persona pills
	if !strings.Contains(output, "Skill1") {
		t.Error("Expected skill pill 'Skill1' in output")
	}
	if !strings.Contains(output, "Skill2") {
		t.Error("Expected skill pill 'Skill2' in output")
	}
	if !strings.Contains(output, "Persona1") {
		t.Error("Expected persona pill 'Persona1' in output")
	}
}

func TestRenderCardItemWithEmptyPuppet(t *testing.T) {
	// Test with empty puppet - should use default
	card := config.IDCard{
		ID:     "1",
		Name:   "Test Card",
		Driver: "claude",
		Model:  "claude-3",
		Puppet: "", // Empty puppet
	}

	output := components.RenderCardItem(card, nil, nil, nil, false, 50)

	// Should not be empty - should render default puppet
	if output == "" {
		t.Error("RenderCardItem with empty puppet should still render")
	}
}

func TestRenderCardItemNoCapabilities(t *testing.T) {
	card := config.IDCard{
		ID:     "1",
		Name:   "Test Card",
		Driver: "claude",
		Model:  "claude-3",
		Puppet: "kankuro",
	}

	// Empty skills and personas
	output := components.RenderCardItem(card, nil, nil, nil, false, 50)

	// Should show "no capabilities" message
	if !strings.Contains(output, "no capabilities") {
		t.Error("Expected 'no capabilities' message when no skills/personas")
	}
}

func TestRenderCardItem_MultibyteName(t *testing.T) {
	card := config.IDCard{
		ID:     "1",
		Name:   "日本語のとても長いカード名前テスト",
		Driver: "claude",
		Model:  "claude-3",
		Puppet: "kankuro",
	}

	output := components.RenderCardItem(card, nil, nil, nil, false, 30)

	if !utf8.ValidString(output) {
		t.Fatalf("output is not valid UTF-8: %q", output)
	}
	if strings.ContainsRune(output, '\uFFFD') {
		t.Errorf("output contains a replacement rune, name was cut mid-rune: %q", output)
	}
}

internal/ui/components/card_render_layou.source:
package components_test

import (
	"fmt"
	"strings"
	"testing"

	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/ui/components"
	"github.com/BlackGiack/kankuro/internal/ui/uitest"
)

// renderedCardHeight is the line count of a correctly laid-out card: the face
// box (FaceBoxHeight) plus the top and bottom border.
const renderedCardHeight = components.FaceBoxHeight + 2

func builtinPuppets(t *testing.T) []config.Puppet {
	t.Helper()
	repo, err := config.NewFileRepository(t.TempDir())
	if err != nil {
		t.Fatalf("new repo: %v", err)
	}
	puppets, err := repo.ListPuppets()
	if err != nil {
		t.Fatalf("list puppets: %v", err)
	}
	return puppets
}

func cardWithSkills(names []string) (config.IDCard, []config.Skill) {
	card := config.IDCard{Name: "Master mind", Driver: "claude", Puppet: "cat"}
	var skills []config.Skill
	for i, n := range names {
		id := fmt.Sprintf("skill-%d", i)
		skills = append(skills, config.Skill{ID: id, Name: n})
		card.SkillIDs = append(card.SkillIDs, id)
	}
	return card, skills
}

// assertIntactCard fails if the rendered card is not a clean rectangle of the
// expected height. A row wider than the card's inner width makes the outer
// border wrap it, which shows up as ragged line widths and extra lines - the
// face box's art spilling onto new lines at the left edge.
func assertIntactCard(t *testing.T, out, label string) {
	t.Helper()
	uitest.AssertExactRect(t, out, ansi.StringWidth(strings.SplitN(out, "\n", 2)[0]), renderedCardHeight, label)
}

// assertSinglePillRow fails if the capability pills spill past their one row.
// The info box holds name, driver, a blank line and the pill row (lines 1-4
// inside the border); line 5 is only there because the face box is taller,
// so its info-box half must stay blank. Pills wrapping onto it is how a pill
// ends up split in two ("api-" / "pat...").
func assertSinglePillRow(t *testing.T, out, label string) {
	t.Helper()
	lines := strings.Split(ansi.Strip(out), "\n")
	if len(lines) != renderedCardHeight {
		return // assertIntactCard reports this
	}
	// "│ info box │ face box │" - the info box is the first cell.
	cells := strings.Split(lines[components.InfoBoxHeight+1], "│")
	if len(cells) < 3 {
		t.Errorf("%s: unexpected row shape %q", label, lines[components.InfoBoxHeight+1])
		return
	}
	if strings.TrimSpace(cells[1]) != "" {
		t.Errorf("%s: pills spilled onto a second row %q:\n%s", label, cells[1], ansi.Strip(out))
	}
}

// TestRenderCardItemStaysIntactAcrossWidths is the regression test for the
// card that shattered only for particular skill sets at particular list
// widths: each pill ends in two columns of whitespace, lipgloss word-wrap
// leaves whitespace hanging past the box edge, and when the edge fell inside
// those two columns the pill row came out 1-2 columns too wide.
//
// The first set is the exact card that was reported (it broke at list widths
// 50, 51 and 63); the others shift the pill boundaries so the sweep covers
// many edge positions, not just one.
func TestRenderCardItemStaysIntactAcrossWidths(t *testing.T) {
	puppets := builtinPuppets(t)
	sets := [][]string{
		{"architecture", "clean-code", "golang", "plan-writing"},
		{"architecture", "clean-code", "api-patterns", "plan-writing"},
		{"architecture", "golang", "plan-writing"},
		{"architecture", "clean-code", "golang", "plan-writing", "api-patterns"},
		{"a", "bb", "ccc", "dddd", "eeeee", "ffffff"},
		{"golang"},
		{"日本語のスキル", "clean-code", "golang"},
		nil,
	}
	for _, names := range sets {
		card, skills := cardWithSkills(names)
		for _, selected := range []bool{false, true} {
			for width := components.CardListMinWidth; width <= 160; width++ {
				out := components.RenderCardItem(card, skills, nil, puppets, selected, width)
				label := fmt.Sprintf("skills=%v selected=%v width=%d", names, selected, width)
				assertIntactCard(t, out, label)
				assertSinglePillRow(t, out, label)
			}
		}
	}
}

// TestRenderCardItemSummarisesPillsThatDoNotFit checks the "+N" summary:
// capabilities that do not fit on the row are counted, not silently dropped,
// and the count accounts for everything hidden.
func TestRenderCardItemSummarisesPillsThatDoNotFit(t *testing.T) {
	puppets := builtinPuppets(t)
	names := []string{"architecture", "clean-code", "golang", "plan-writing", "api-patterns", "rust-pro"}
	card, skills := cardWithSkills(names)

	narrow := ansi.Strip(components.RenderCardItem(card, skills, nil, puppets, false, components.CardListMinWidth))
	wide := ansi.Strip(components.RenderCardItem(card, skills, nil, puppets, false, 160))

	for label, out := range map[string]string{"narrow": narrow, "wide": wide} {
		shown := 0
		for _, n := range []string{"archite", "clean-code", "golang", "plan-wr", "api-pat", "rust-pro"} {
			if strings.Contains(out, n) {
				shown++
			}
		}
		hidden := len(names) - shown
		if hidden == 0 {
			continue
		}
		if want := fmt.Sprintf("+%d", hidden); !strings.Contains(out, want) {
			t.Errorf("%s: %d of %d skills shown, expected a %q summary pill:\n%s", label, shown, len(names), want, out)
		}
	}

	// MaxPillsShown still caps a wide card, so six skills can never all show.
	if !strings.Contains(wide, "+") {
		t.Errorf("wide card should summarise skills beyond MaxPillsShown (%d):\n%s", components.MaxPillsShown, wide)
	}
}

// TestRenderCardItemClipsOversizedPuppet covers the face box's half of the
// row: puppets can come from user puppet sources, and art wider than the box
// used to widen the row and shatter the card exactly like the pill overflow.
func TestRenderCardItemClipsOversizedPuppet(t *testing.T) {
	wide := config.Puppet{
		ID:    "wide",
		Name:  "wide",
		Lines: []string{"<==================>", "|  much too wide   |", "<==================>"},
	}
	card, skills := cardWithSkills([]string{"golang"})
	card.Puppet = "wide"
	for width := components.CardListMinWidth; width <= 120; width++ {
		out := components.RenderCardItem(card, skills, nil, []config.Puppet{wide}, false, width)
		assertIntactCard(t, out, fmt.Sprintf("oversized puppet width=%d", width))
	}
}

// TestRenderCardItemSanitisesUserText: tabs, line breaks and escapes in a
// card's name, driver, model and skill names must not change the card's shape.
// lipgloss expands a tab to four columns after the text was fitted, so a name
// of 18 tab-separated letters is 18 columns to the fitting code and 57 to the
// terminal. Seen to fail with DisplayText removed from the name line.
func TestRenderCardItemSanitisesUserText(t *testing.T) {
	puppets := builtinPuppets(t)
	messy := "a\tb\tc\td\te\tf\tg\th\ti\tj\nk\r\x1b[31ml\x1b[0m"
	card, skills := cardWithSkills([]string{messy, "clean-code"})
	card.Name, card.Driver, card.Model = messy, messy, messy
	for width := components.CardListMinWidth; width <= 160; width++ {
		out := components.RenderCardItem(card, skills, nil, puppets, false, width)
		assertIntactCard(t, out, fmt.Sprintf("width=%d", width))
		if strings.ContainsAny(ansi.Strip(out), "\t\r") {
			t.Fatalf("width=%d: a control character reached the output: %q", width, ansi.Strip(out))
		}
	}
}

func TestCardListUsesBalancedCellGuttersAcrossSelectionAndFiltering(t *testing.T) {
	for _, width := range []int{44, 60, 100} {
		list := components.NewCardList(components.CardListCallbacks{})
		list.SetPuppets(builtinPuppets(t))
		list.SetCards([]config.IDCard{
			{ID: "one", Name: "First", Driver: "cat", Puppet: "kankuro"},
			{ID: "two", Name: "Second", Driver: "cat", Puppet: "kankuro"},
		}, nil, nil)
		list.SetSize(width, 30)
		for _, state := range []struct {
			name        string
			selectIndex int
			query       string
		}{
			{name: "first selected", selectIndex: 0},
			{name: "second selected", selectIndex: 1},
			{name: "filtered", selectIndex: 0, query: "Second"},
		} {
			list.Select(state.selectIndex)
			list.SetSearchQuery(state.query)
			out := ansi.Strip(list.View())
			for line := range strings.SplitSeq(out, "\n") {
				leftAt, rightAt := strings.Index(line, "╭"), strings.LastIndex(line, "╮")
				if leftAt < 0 || rightAt < 0 {
					continue
				}
				left := ansi.StringWidth(line[:leftAt])
				right := width - ansi.StringWidth(line[:rightAt+len("╮")])
				if left != 2 || right != 2 {
					t.Errorf("%s width=%d: card gutters left=%d right=%d, want 2/2:\n%s", state.name, width, left, right, out)
				}
				break
			}
		}
	}
}

