package components_test

import (
	"strings"
	"testing"

	"github.com/BlackGiack/kankuro/internal/ui/components"
)

func TestModal_OpenClose(t *testing.T) {
	m := components.NewModal("Test Modal")

	if m.IsOpen() {
		t.Error("Modal should start closed")
	}

	m.Open()
	if !m.IsOpen() {
		t.Error("Modal should be open after Open()")
	}

	m.Close()
	if m.IsOpen() {
		t.Error("Modal should be closed after Close()")
	}
}

func TestModal_ViewHidden(t *testing.T) {
	m := components.NewModal("Hidden Modal")

	view := m.View()
	if view != "" {
		t.Errorf("Hidden modal should render empty string, got: %q", view)
	}
}

func TestModal_ViewVisible(t *testing.T) {
	m := components.NewModal("Visible Modal")
	m.SetContent("Are you sure?")
	m.Open()

	view := m.View()
	if view == "" {
		t.Error("Open modal should render content")
	}
	if !strings.Contains(view, "Visible Modal") {
		t.Error("Should contain title")
	}
	if !strings.Contains(view, "Are you sure?") {
		t.Error("Should contain content")
	}
}

func TestModalStateLifecycle(t *testing.T) {
	tests := []struct {
		name          string
		steps         func(s *components.ModalState)
		wantOpen      bool
		wantConfirmed bool
		wantCancelled bool
	}{
		{"zero value", func(*components.ModalState) {}, false, false, false},
		{"open", func(s *components.ModalState) { s.Open() }, true, false, false},
		{"confirm sets only confirmed", func(s *components.ModalState) { s.Open(); s.Confirm() }, true, true, false},
		{"cancel sets only cancelled", func(s *components.ModalState) { s.Open(); s.Cancel() }, true, false, true},
		{"confirm does not close", func(s *components.ModalState) { s.Open(); s.Confirm(); s.Cancel() }, true, true, true},
		{"open clears previous flags", func(s *components.ModalState) { s.Open(); s.Confirm(); s.Cancel(); s.Open() }, true, false, false},
		{"close clears everything", func(s *components.ModalState) { s.Open(); s.Confirm(); s.Cancel(); s.Close() }, false, false, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var s components.ModalState
			tt.steps(&s)
			if s.IsOpen() != tt.wantOpen || s.Confirmed() != tt.wantConfirmed || s.Cancelled() != tt.wantCancelled {
				t.Errorf("open/confirmed/cancelled = %v/%v/%v, want %v/%v/%v",
					s.IsOpen(), s.Confirmed(), s.Cancelled(), tt.wantOpen, tt.wantConfirmed, tt.wantCancelled)
			}
		})
	}
}

internal/ui/components/session_list_layo.source:
package components_test

import (
	"fmt"
	"strings"
	"testing"
	"time"
	"unicode/utf8"

	"github.com/charmbracelet/x/ansi"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/components"
	"github.com/BlackGiack/kankuro/internal/ui/uitest"
)

// Session lists stay within their assigned dimensions. Each item occupies
// SessionDelegateHeight rows plus one spacing row; names must not move the status row.

const sessionItemRows = components.SessionDelegateHeight + 1 // item rows + spacing row

// sessionListMinHeight is the shortest list the dashboard hands its sessions
// pane on a 24-row terminal: the coordinator gives the dashboard 24-4 = 20,
// the pane is 21 rows, minus its border (2) and title block (2). Below ~9 rows
// the list's own chrome (pagination) plus one item no longer fits;
// that is out of range, since the dashboard is never that short.
const sessionListMinHeight = 17

// sessionListMinWidth is the narrowest list the dashboard hands its sessions
// pane on the smallest terminal it supports (80 columns, see
// views/dashboard_layout_test.go): 80/4 = 20 pane columns minus the two border
// columns. TestSessionListFitsEveryWidth covers narrower lists too.
const sessionListMinWidth = 18

func sweepNames() []string { return uitest.AdversarialNames }

func sessionFixtures(n int, names []string) ([]session.Snapshot, []config.IDCard) {
	faces := []string{"", "happy", "focused", "thinking", "neutral"}
	statuses := []session.Status{session.StatusRunning, session.StatusWaiting, session.StatusTerminated}
	dirs := []string{
		"/home/user/projects/a-rather-long-directory-name/with/many/segments",
		"/home/用户/项目/日本語のディレクトリ/とても長い名前",
		"/tmp/x",
		"",
		"/home/user/🚀/🚀/🚀/🚀/🚀/🚀/🚀/🚀",
	}
	var cards []config.IDCard
	var sessions []session.Snapshot
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	for i := range n {
		cardID := fmt.Sprintf("card-%d", i)
		if i%7 != 6 { // every seventh session's card was deleted
			cards = append(cards, config.IDCard{
				ID:        cardID,
				Name:      names[(i+1)%len(names)],
				FaceStyle: faces[i%len(faces)],
			})
		}
		sessions = append(sessions, session.Snapshot{
			ID:              fmt.Sprintf("session-%d-%s", i, strings.Repeat("0123456789", 4)),
			CardID:          cardID,
			Name:            names[i%len(names)],
			PID:             1000 + i,
			WorkingDir:      dirs[i%len(dirs)],
			UseTmpWorkspace: i%3 == 0,
			StartedAt:       base.Add(time.Duration(i) * time.Minute),
			Status:          statuses[i%len(statuses)],
			Pinged:          i%4 == 0,
		})
	}
	return sessions, cards
}

func TestSessionListStaysWithinItsBox(t *testing.T) {
	for _, count := range []int{0, 1, 20} {
		for _, query := range []string{"", "s"} {
			sessions, cards := sessionFixtures(count, sweepNames())
			for w := sessionListMinWidth; w <= 80; w += 3 {
				for h := sessionListMinHeight; h <= 30; h += 3 {
					sl := components.NewSessionList(components.SessionListCallbacks{})
					sl.SetSize(w, h)
					sl.SetSessions(sessions, cards)
					sl.SetSearchQuery(query)
					label := fmt.Sprintf("sessions=%d query=%q %dx%d", count, query, w, h)
					uitest.AssertWithin(t, sl.View(), w, h, label)
				}
			}
		}
	}
}

func TestSessionListRegistrationDetailsStayWithinTheirRows(t *testing.T) {
	sessions, cards := sessionFixtures(1, []string{strings.Repeat("n", 200)})
	sessions[0].Registration = session.RegistrationPending
	sessions[0].RegistrationErr = strings.Repeat("registration failure ", 20)
	sessions[0].ActiveConversationID = strings.Repeat("native-id-", 20)
	sessions[0].Conversations = map[string][]session.ConversationBinding{
		sessions[0].CardID: {{ID: sessions[0].ActiveConversationID, Name: strings.Repeat("conversation name ", 10), Driver: "codex"}},
	}
	for _, width := range []int{sessionListMinWidth, 23, 40, 80} {
		list := components.NewSessionList(components.SessionListCallbacks{})
		list.SetSize(width, sessionListMinHeight)
		list.SetSessions(sessions, cards)
		uitest.AssertWithin(
			t,
			list.View(),
			width,
			sessionListMinHeight,
			fmt.Sprintf("registration details %dx%d", width, sessionListMinHeight),
		)
		assertItemRows(t, list, sessionListMinHeight, fmt.Sprintf("registration rows %d", width))
	}
}

// TestSessionListKeepsItemRowsInPlace checks each item against its own region.
// Every name from AdversarialNames gets its own sweep, since a single wrapped
// or overlong title shifts every row below it.
func TestSessionListKeepsItemRowsInPlace(t *testing.T) {
	for i, name := range sweepNames() {
		sessions, cards := sessionFixtures(12, []string{name})
		for _, w := range []int{sessionListMinWidth, 23, 29, 40, 80} {
			for _, h := range []int{17, 24, 30} {
				sl := components.NewSessionList(components.SessionListCallbacks{})
				sl.SetSize(w, h)
				sl.SetSessions(sessions, cards)
				label := fmt.Sprintf("name#%d %dx%d", i, w, h)
				assertItemRows(t, sl, h, label)
			}
		}
	}
}

func assertItemRows(t *testing.T, sl *components.SessionList, h int, label string) {
	t.Helper()
	out := sl.View()
	rows := strings.Split(ansi.Strip(out), "\n")
	onPage := sl.List().Paginator.ItemsOnPage(len(sl.List().Items()))
	if onPage*sessionItemRows-1 > h {
		t.Errorf("%s: %d items of %d rows cannot fit in %d:\n%s", label, onPage, sessionItemRows, h, ansi.Strip(out))
		return
	}
	for k := range onPage {
		row := sessionItemRows*k + 2
		if row >= len(rows) || !strings.Contains(rows[row], "pid=") && !strings.Contains(rows[row], "wai") &&
			!strings.Contains(rows[row], "run") && !strings.Contains(rows[row], "ter") {
			t.Errorf("%s: item %d has no status row at line %d:\n%s", label, k, row, ansi.Strip(out))
			return
		}
	}
	for i, r := range rows[:min(len(rows), onPage*sessionItemRows)] {
		if i%sessionItemRows == sessionItemRows-1 && strings.TrimSpace(r) != "" {
			t.Errorf("%s: spacing row %d is not blank %q:\n%s", label, i, r, ansi.Strip(out))
			return
		}
	}
}

// TestSessionListEmptyAndFilteredAway covers 0 items and a search that matches
// nothing: the filter changes what is drawn, and the result must still fit.
func TestSessionListEmptyAndFilteredAway(t *testing.T) {
	sessions, cards := sessionFixtures(5, []string{"alpha"})
	sl := components.NewSessionList(components.SessionListCallbacks{})
	sl.SetSize(30, sessionListMinHeight)
	sl.SetSessions(sessions, cards)
	sl.SetSearchQuery("zzz-matches-nothing")
	uitest.AssertWithin(t, sl.View(), 30, sessionListMinHeight, "filtered away")
	if len(sl.List().Items()) != 0 {
		t.Fatalf("expected the query to match nothing, got %d items", len(sl.List().Items()))
	}
}

// TestSessionListDescriptionIsValidUTF8 guards the path trimming in
// Description(): it slices a byte offset, so a path with multibyte runes near
// the cut produced invalid UTF-8, which terminals draw as replacement boxes
// and which breaks width measurement.
func TestSessionListDescriptionIsValidUTF8(t *testing.T) {
	for _, dir := range []string{
		"/home/用户/项目/日本語のディレクトリ/とても長い名前",
		"/home/user/🚀/🚀/🚀/🚀/🚀/🚀/🚀/🚀",
		"/ééééééééééééééééééééééééééééé",
	} {
		item := components.SessionListItem{Session: session.Snapshot{ID: "s", WorkingDir: dir}}
		desc := item.Description()
		if !utf8.ValidString(desc) {
			t.Errorf("working dir %q: Description() is not valid UTF-8: %q", dir, desc)
		}
	}
}

// TestSessionListFitsEveryWidth is the regression test for the list's built-in
// help line ("up / down / q quit / ? more"), which was wider than the list at
// list widths 17-20, 26-28 and 35-36 (and below 17 for an empty list) and made
// the dashboard's sessions pane wrap it and grow two rows - on a stock 80- and
// 120-column terminal. It sweeps every width, narrower than the dashboard ever
// asks for, so re-enabling the help (or any other fixed-width row) fails here.
// Seen to fail: with SetShowHelp(false) removed from NewSessionList.
func TestSessionListFitsEveryWidth(t *testing.T) {
	for _, count := range []int{0, 3, 20} {
		sessions, cards := sessionFixtures(count, []string{"alpha"})
		for w := 10; w <= 80; w++ {
			sl := components.NewSessionList(components.SessionListCallbacks{})
			sl.SetSize(w, sessionListMinHeight)
			sl.SetSessions(sessions, cards)
			uitest.AssertWithin(t, sl.View(), w, sessionListMinHeight, fmt.Sprintf("sessions=%d width=%d", count, w))
		}
	}
}

// TestSessionListNameWithTabsFitsWidth: lipgloss expands a tab to four spaces
// after the delegate has measured and truncated the title, so a name with tabs
// ends up wider than the list.
func TestSessionListNameWithTabsFitsWidth(t *testing.T) {
	sessions, cards := sessionFixtures(3, []string{"name\twith\ttabs and more text"})
	sl := components.NewSessionList(components.SessionListCallbacks{})
	sl.SetSize(30, sessionListMinHeight)
	sl.SetSessions(sessions, cards)
	uitest.AssertWithin(t, sl.View(), 30, sessionListMinHeight, "tab name")
}

internal/ui/components/session_list_test.source:
package components_test

import (
	"sort"
	"strings"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/session"
	"github.com/BlackGiack/kankuro/internal/ui/components"
)

func TestSessionList_New(t *testing.T) {
	callbacks := components.SessionListCallbacks{
		OnSelect: func(session.Snapshot) tea.Cmd {
			return nil
		},
		OnAttach:  func(string) {},
		OnKill:    func(string) {},
		OnDelete:  func(string) {},
		OnSwitch:  func(string) {},
		OnPreview: func(string) tea.Cmd { return nil },
	}

	sl := components.NewSessionList(callbacks)
	if sl == nil {
		t.Fatal("NewSessionList returned nil")
	}

	if sl.Focused {
		t.Error("SessionList should not be focused initially")
	}
}

func TestSessionListShowsDeletedCardLabel(t *testing.T) {
	item := components.SessionListItem{Session: session.Snapshot{CardID: "old-card", CardDeleted: true}}
	if !strings.Contains(item.Description(), "deleted card: old-card") {
		t.Fatalf("description: %q", item.Description())
	}
}

func TestSessionList_SetSessions(t *testing.T) {
	callbacks := components.SessionListCallbacks{}
	sl := components.NewSessionList(callbacks)

	sessions := []session.Snapshot{
		{ID: "s1", Name: "Session 1", Status: session.StatusRunning, StartedAt: time.Now()},
		{ID: "s2", Name: "Session 2", Status: session.StatusTerminated, StartedAt: time.Now().Add(-time.Hour)},
	}
	cards := []config.IDCard{
		{ID: "c1", Name: "Card 1"},
	}

	sl.SetSessions(sessions, cards)

	// Verify internal state updated
	if len(sl.Sessions()) != 2 {
		t.Errorf("Expected 2 sessions, got %d", len(sl.Sessions()))
	}

	// Verify sorting (newest first)
	sorted := make([]session.Snapshot, len(sessions))
	copy(sorted, sessions)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].StartedAt.After(sorted[j].StartedAt)
	})
}

func TestSessionList_SetSearchQuery(t *testing.T) {
	callbacks := components.SessionListCallbacks{}
	sl := components.NewSessionList(callbacks)

	sessions := []session.Snapshot{
		{ID: "s1", Name: "Alpha Session"},
		{ID: "s2", Name: "Beta Session"},
		{ID: "s3", Name: "Gamma Session"},
	}

	sl.SetSessions(sessions, nil)

	// No filter
	filtered := sl.FilterSessions(sessions)
	if len(filtered) != 3 {
		t.Errorf("Expected 3 sessions without filter, got %d", len(filtered))
	}

	// With filter
	sl.SetSearchQuery("beta")
	filtered = sl.FilterSessions(sessions)
	if len(filtered) != 1 {
		t.Errorf("Expected 1 session matching 'beta', got %d", len(filtered))
	}
	if len(filtered) > 0 && filtered[0].ID != "s2" {
		t.Errorf("Expected session ID 's2', got '%s'", filtered[0].ID)
	}
}

func TestSessionList_Selected(t *testing.T) {
	callbacks := components.SessionListCallbacks{}
	sl := components.NewSessionList(callbacks)

	// No selection
	_, ok := sl.Selected()
	if ok {
		t.Error("Selected should return false when no selection")
	}

	// Set sessions and select first
	sessions := []session.Snapshot{
		{ID: "s1", Name: "Test Session", StartedAt: time.Now()},
	}
	sl.SetSessions(sessions, nil)
	l := sl.List()
	l.Select(0)

	sess, ok := sl.Selected()
	if !ok {
		t.Error("Selected should return true when item selected")
	}
	if sess.ID != "s1" {
		t.Errorf("Expected session ID 's1', got '%s'", sess.ID)
	}
}

func TestSessionListItem_Title(t *testing.T) {
	tests := []struct {
		name     string
		session  session.Snapshot
		expected string
	}{
		{
			name:     "running session",
			session:  session.Snapshot{ID: "s1", Name: "Test", Status: session.StatusRunning},
			expected: "Test",
		},
		{
			name: "waiting session",
			session: session.Snapshot{
				ID:     "s2",
				Name:   "Waiting",
				Status: session.StatusWaiting,
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			item := components.SessionListItem{Session: tt.session}
			title := item.Title()

			if tt.session.Status != session.StatusWaiting {
				if title != tt.expected {
					t.Errorf("Expected title %q, got %q", tt.expected, title)
				}
			} else {
				// Waiting status should contain color codes
				if title == "Waiting" {
					t.Error("Waiting session title should include color styling")
				}
			}
		})
	}
}

func TestSessionListItem_Description(t *testing.T) {
	session := session.Snapshot{
		ID:              "s1",
		Name:            "Test Session",
		CardID:          "c1",
		Status:          session.StatusRunning,
		PID:             12345,
		WorkingDir:      "/home/user/project",
		UseTmpWorkspace: false,
	}

	card := &config.IDCard{
		ID:        "c1",
		Name:      "Test Card",
		FaceStyle: "happy",
	}

	item := components.SessionListItem{
		Session: session,
		Card:    card,
	}

	desc := item.Description()

	if desc == "" {
		t.Error("Description should not be empty")
	}
}

func TestSessionListItemShowsConversationRegistrationStateAndIdentity(t *testing.T) {
	item := components.SessionListItem{Session: session.Snapshot{
		ID:                      "session",
		CardID:                  "card",
		Name:                    "Agent",
		Status:                  session.StatusRunning,
		PID:                     123,
		Registration:            session.RegistrationRegistered,
		RegistrationPersistence: session.RegistrationUnsaved,
		ActiveConversationID:    "native-conversation-id",
		Conversations: map[string][]session.ConversationBinding{
			"card": {{ID: "native-conversation-id", Name: "Feature work", Driver: "codex"}},
		},
	}}
	description := item.Description()
	for _, want := range []string{"reg=registered/not-saved", "Feature work", "sation-id"} {
		if !strings.Contains(description, want) {
			t.Errorf("description %q does not show %q", description, want)
		}
	}
}

func TestSessionList_SetSelectedByID(t *testing.T) {
	callbacks := components.SessionListCallbacks{}
	sl := components.NewSessionList(callbacks)

	sessions := []session.Snapshot{
		{ID: "s1", Name: "First", StartedAt: time.Now().Add(-2 * time.Hour)},
		{ID: "s2", Name: "Second", StartedAt: time.Now().Add(-time.Hour)},
		{ID: "s3", Name: "Third", StartedAt: time.Now()},
	}

	sl.SetSessions(sessions, nil)

	// Note: SetSessions sorts by StartedAt newest first: s3, s2, s1
	// Select second session (s2)
	sl.SetSelectedByID("s2")

	sess, ok := sl.Selected()
	if !ok {
		t.Fatal("Should have selection after SetSelectedByID")
	}
	if sess.ID != "s2" {
		t.Errorf("Expected session ID 's2', got '%s'", sess.ID)
	}

	// Try to select non-existent ID
	sl.SetSelectedByID("nonexistent")
	// Should still be on s2
	sess, _ = sl.Selected()
	if sess.ID != "s2" {
		t.Error("Should not change selection for non-existent ID")
	}
}

func TestRenderAgentFace(t *testing.T) {
	// Test that renderer works
	face := components.RenderAgentFace("neutral")
	if face == "" {
		t.Error("RenderAgentFace should return non-empty string")
	}
}

func TestRenderAgentPuppet(t *testing.T) {
	puppet := components.RenderAgentPuppet("kankuro", nil)
	if puppet == "" {
		t.Error("RenderAgentPuppet should return non-empty string")
	}
}

