				editor.Update(tea.KeyPressMsg{Code: tea.KeySpace, Text: " "})
				if got := editor.Card().UseTmpWorkspace; got != expected {
					t.Fatalf("Space: got %t, want %t", got, expected)
				}
			}
			if want {
				editor.Update(tea.KeyPressMsg{Code: tea.KeySpace, Text: " "})
