package main

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/driver"
)

func TestEmbeddedMCPCLISkillDeploysThroughConfig(t *testing.T) {
	if len(embeddedMCPCLISkill) == 0 || !bytes.Contains(embeddedMCPCLISkill, []byte("name: mcp-cli")) {
		t.Fatal("embedded skill is empty or missing its canonical metadata")
	}
	previous, hadPrevious := config.GetBuiltinSkillContent("mcp-cli")
	config.SetBuiltinMCPCLISkillContent(embeddedMCPCLISkill)
	t.Cleanup(func() {
		if hadPrevious {
			config.SetBuiltinMCPCLISkillContent(previous)
		} else {
			config.SetBuiltinMCPCLISkillContent(nil)
		}
	})

	workspace := t.TempDir()
	d := driver.NewGenericCLIDriver()
	skill := builtinSkill(t, config.BuiltinSkillMCPCLI)
	if err := d.SetSkills([]config.Skill{skill}, workspace); err != nil {
		t.Fatalf("deploy embedded skill: %v", err)
	}
	deployed, err := os.ReadFile(filepath.Join(workspace, ".agents", "skills", "mcp-cli", "SKILL.md"))
	if err != nil {
		t.Fatalf("read deployed skill: %v", err)
	}
	if !bytes.Equal(deployed, embeddedMCPCLISkill) {
		t.Fatal("deployed skill differs from embedded bytes")
	}
}

func TestEmbeddedKankuroPuppetSkillDeploysThroughConfig(t *testing.T) {
	if len(embeddedKankuroPuppetSkill) == 0 || !bytes.Contains(embeddedKankuroPuppetSkill, []byte("name: kankuro-puppet")) {
		t.Fatal("embedded puppet skill is empty or missing its canonical metadata")
	}
	config.SetBuiltinKankuroPuppetSkillContent(embeddedKankuroPuppetSkill)
	t.Cleanup(func() { config.SetBuiltinKankuroPuppetSkillContent(nil) })
	workspace := t.TempDir()
	skill := builtinSkill(t, config.BuiltinSkillKankuroPuppet)
	if err := driver.NewGenericCLIDriver().SetSkills([]config.Skill{skill}, workspace); err != nil {
		t.Fatal(err)
	}
	deployed, err := os.ReadFile(filepath.Join(workspace, ".agents", "skills", "kankuro-puppet", "SKILL.md"))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(deployed, embeddedKankuroPuppetSkill) {
		t.Fatal("deployed puppet skill differs from embedded bytes")
	}
}

// builtinSkill reads the actual registry used for deployment.
func builtinSkill(t *testing.T, id string) config.Skill {
	t.Helper()
	for _, skill := range config.BuiltinSkills() {
		if skill.ID == id {
			return skill
		}
	}
	t.Fatalf("built-in skill %s missing", id)
	return config.Skill{}
}

tests/e2e/capture_test.go.source:
//go:build e2e

package e2e_test

import (
	"path/filepath"
	"testing"
	"time"

	tuitest "github.com/microsoft/tui-test/bindings/go"
	"github.com/microsoft/tui-test/bindings/go/tuitesttest"
)

// This preflight makes no agent/model calls and leaves no persistent images.
func TestNativeCaptureGlyphs(t *testing.T) {
	verifyNativeCapture(t)
}

func verifyNativeCapture(t *testing.T) {
	t.Helper()
	terminal := tuitesttest.New(t, tuitesttest.Options{
		Prefix: "kankuro-capture-check", Program: "printf", Args: []string{"⬝ ⠋ ■"},
		Client: tuitest.ClientOptions{Recording: &tuitest.AutomaticRecording{Mode: tuitest.RecordingDisabled}},
		Spawn:  tuitest.SpawnOptions{Cols: new(uint16(12)), Rows: new(uint16(2)), WaitReady: new(false)},
	})
	timeout := 5 * time.Second
	must(t, terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}))
	assertNativeExit(t, terminal)
	must(t, terminal.GetByText("⬝ ⠋ ■", tuitest.TextSelectorOptions{}).Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}))
	_, err := terminal.Screenshot(filepath.Join(t.TempDir(), "glyph-check.png"), tuitest.ScreenshotOptions{})
	if err != nil {
		t.Fatalf("native screenshot preflight: %v; install an outline font covering U+2B1D (for example Noto Sans Symbols2)", err)
	}
}

// Direct Run processes expose State.Exited; ExpectExitCode tracks shell commands.
func assertNativeExit(t *testing.T, terminal *tuitest.Client) {
	t.Helper()
	state, err := terminal.State()
	must(t, err)
	if state.Exited == nil {
		t.Fatal("native process exit code was not recorded")
	}
	if *state.Exited != 0 {
		t.Fatalf("native process exit code = %d, want 0", *state.Exited)
	}
}

tests/e2e/environment_test.go.source:
//go:build e2e

package e2e_test

import (
	"io/fs"
	"os"
	"path/filepath"
	"testing"
)

// isolatedAgentEnvironment copies only configuration, credentials and model
// preferences, never historical conversations or a running server's state.
func isolatedAgentEnvironment(t *testing.T, sandbox, agent string) map[string]string {
	t.Helper()
	originalHome, err := os.UserHomeDir()
	must(t, err)
	home := filepath.Join(sandbox, "home")
	configHome := filepath.Join(home, ".config")
	dataHome := filepath.Join(home, ".local/share")
	stateHome := filepath.Join(home, ".local/state")
	for _, dir := range []string{home, configHome, dataHome, stateHome} {
		must(t, os.MkdirAll(dir, 0o700))
	}
	originalConfig := os.Getenv("XDG_CONFIG_HOME")
	if originalConfig == "" {
		originalConfig = filepath.Join(originalHome, ".config")
	}
	originalData := os.Getenv("XDG_DATA_HOME")
	if originalData == "" {
		originalData = filepath.Join(originalHome, ".local/share")
	}
	originalState := os.Getenv("XDG_STATE_HOME")
	if originalState == "" {
		originalState = filepath.Join(originalHome, ".local/state")
	}
	environment := map[string]string{
		"HOME": home, "XDG_CONFIG_HOME": configHome, "XDG_DATA_HOME": dataHome,
		"XDG_STATE_HOME": stateHome, "XDG_CACHE_HOME": filepath.Join(home, ".cache"),
		"TERM": "xterm-256color", "COLORTERM": "truecolor",
	}
	switch agent {
	case "opencode":
		copyOpenCodeConfiguration(t, filepath.Join(originalConfig, "opencode"), filepath.Join(configHome, "opencode"))
		copyConfiguration(t, filepath.Join(originalData, "opencode/auth.json"), filepath.Join(dataHome, "opencode/auth.json"))
		copyConfiguration(t, filepath.Join(originalState, "opencode/model.json"), filepath.Join(stateHome, "opencode/model.json"))
		copyConfiguration(t, filepath.Join(originalState, "opencode/kv.json"), filepath.Join(stateHome, "opencode/kv.json"))
		if _, statErr := os.Stat(filepath.Join(originalData, "opencode/opencode.db")); statErr == nil {
			copyOpenCodeCredentials(t, environment)
		} else if !os.IsNotExist(statErr) {
			t.Fatal(statErr)
		}
	case "codex":
		source := os.Getenv("CODEX_HOME")
		if source == "" {
			source = filepath.Join(originalHome, ".codex")
		}
		destination := filepath.Join(home, ".codex")
		for _, name := range []string{"config.toml", "auth.json", "instructions.md", "rules"} {
			copyConfiguration(t, filepath.Join(source, name), filepath.Join(destination, name))
		}
		environment["CODEX_HOME"] = destination
	case "claude":
		copyConfiguration(t, filepath.Join(originalHome, ".claude.json"), filepath.Join(home, ".claude.json"))
		for _, name := range []string{"settings.json", "settings.local.json", ".credentials.json"} {
			copyConfiguration(t, filepath.Join(originalHome, ".claude", name), filepath.Join(home, ".claude", name))
		}
		environment["CLAUDE_CONFIG_DIR"] = filepath.Join(home, ".claude")
	}
	return environment
}

func copyConfiguration(t *testing.T, source, destination string) {
	t.Helper()
	info, err := os.Stat(source)
	if os.IsNotExist(err) {
		return
	}
	must(t, err)
	if !info.IsDir() {
		copyConfigurationFile(t, source, destination)
		return
	}
	must(t, filepath.WalkDir(source, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		relative, relativeErr := filepath.Rel(source, path)
		if relativeErr != nil {
			return relativeErr
		}
		target := filepath.Join(destination, relative)
		if entry.IsDir() {
			return os.MkdirAll(target, 0o700)
		}
		if entry.Type().IsRegular() {
			copyConfigurationFile(t, path, target)
		}
		return nil
	}))
}

func copyConfigurationFile(t *testing.T, source, destination string) {
	t.Helper()
	bytes, err := os.ReadFile(source)
	must(t, err)
	must(t, os.MkdirAll(filepath.Dir(destination), 0o700))
	must(t, os.WriteFile(destination, bytes, 0o600))
}

tests/e2e/native_agent_test.go.source:
//go:build e2e

package e2e_test

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"testing"
	"time"

	tuitest "github.com/microsoft/tui-test/bindings/go"
	"github.com/microsoft/tui-test/bindings/go/tuitesttest"

	"github.com/BlackGiack/kankuro/internal/config"
	"github.com/BlackGiack/kankuro/internal/configstartup"
	"github.com/BlackGiack/kankuro/internal/session"
)

// TestNativeAgentJourney deliberately requires a configured installed agent.
// Missing executables skip; authentication, configuration and journey failures do not.
func TestNativeAgentJourney(t *testing.T) {
	j := newNativeJourney(t)
	first := j.launch()
	nonce := j.register(first)
	j.detach()
	j.resume(first, nonce)
	j.finish()
}

type nativeJourney struct {
	t         *testing.T
	root      string
	agent     nativeAgent
	artifacts string
	configDir string
	card      config.IDCard
	terminal  *tuitest.Client
	run       *journeyRun
}

func newNativeJourney(t *testing.T) *nativeJourney {
	t.Helper()
	if os.Getenv("TUI_TEST_RECORDING_FONT_FAMILIES") == "" {
		t.Setenv("TUI_TEST_RECORDING_FONT_FAMILIES", "DejaVu Sans Mono,DejaVu Sans")
	}
	agent := selectAgent(t)
	root, err := filepath.Abs("../..")
	must(t, err)
	run, artifacts := newJourneyRun(t, root, agent)
	j := &nativeJourney{t: t, root: root, agent: agent, artifacts: artifacts, run: run}
	verifyNativeCapture(t)
	sandbox := t.TempDir()
	environment := isolatedAgentEnvironment(t, sandbox, j.agent.name)
	workspace := filepath.Join(sandbox, "workspace")
	must(t, os.MkdirAll(workspace, 0o700))
	// Keep approvals confined to the disposable workspace; preserve the user's model/provider.
	if j.agent.name == "opencode" {
		j.run.Model = configureOpenCodeWorkspace(t, workspace)
	}
	configDir := filepath.Join(sandbox, "config")
	must(t, os.MkdirAll(configDir, 0o700))
	must(t, configstartup.PrepareStartup(configDir))
	repo, err := config.NewFileRepository(configDir)
	must(t, err)
	must(t, repo.SaveWorkspaceSources([]config.WorkspaceSource{{Path: workspace}}))
	workspaces, err := repo.ListWorkspaces()
	must(t, err)
	if len(workspaces) != 1 {
		t.Fatalf("workspace registry = %+v", workspaces)
	}
	card, err := repo.CreateIDCard(config.IDCard{
		DashboardID: "default",
		Name:        "Native E2E",
		Driver:      j.agent.name,
		WorkspaceID: workspaces[0].ID,
		Puppet:      "kankuro",
		SkillIDs:    []string{config.BuiltinSkillMCPCLI, config.BuiltinSkillKankuroPuppet},
		MCPIDs:      []string{config.BuiltinMCPKankuro},
		AgentsMD:    "This is a disposable terminal acceptance test. Follow the user's registration instructions exactly. Use the real native conversation ID, never invent one. Use mcp-cli with .kankuro/mcp-servers.json. Do not display credentials.",
	})
	must(t, err)
	binary := filepath.Join(sandbox, "kankuro")
	if runtime.GOOS == "windows" {
		binary += ".exe"
	}
	buildCtx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	build := exec.CommandContext(buildCtx, "go", "build", "-o", binary, ".")
	build.Dir = j.root
	if output, buildErr := build.CombinedOutput(); buildErr != nil {
		t.Fatalf("build Kankuro: %v\n%s", buildErr, output)
	}
	environment["KANKURO_CONFIG_DIR"] = configDir
	environment["KANKURO_TMP_DIR"] = filepath.Join(sandbox, "tmp")
	terminal := tuitesttest.New(t, tuitesttest.Options{
		Program: binary, Prefix: "kankuro-native",
		Client: tuitest.ClientOptions{Recording: &tuitest.AutomaticRecording{Mode: tuitest.RecordingDisabled}},
		Spawn: tuitest.SpawnOptions{
			Cols: new(uint16(120)), Rows: new(uint16(40)), Cwd: workspace,
			Env: environment, WaitReady: new(false),
		},
	})
	j.terminal, j.configDir, j.card = terminal, configDir, card
	registerTerminalCleanup(t, terminal, j.run, j.artifacts)
	return j
}

func newJourneyRun(t *testing.T, root string, agent nativeAgent) (*journeyRun, string) {
	t.Helper()
	artifacts := filepath.Join(root, "tests/e2e/artifacts/native-agent")
	if override := os.Getenv("KANKURO_E2E_ARTIFACT_DIR"); override != "" {
		resolved, pathErr := filepath.Abs(override)
		must(t, pathErr)
		artifacts = resolved
	}
	// Only remove this test's known artifacts; never clear an arbitrary supplied directory.
	must(t, os.MkdirAll(artifacts, 0o700))
	for _, name := range []string{"launched.png", "registered.png", "dashboard.png", "resumed.png", "failure.png", "result.json"} {
		if removeErr := os.Remove(filepath.Join(artifacts, name)); removeErr != nil && !os.IsNotExist(removeErr) {
			t.Fatal(removeErr)
		}
	}
	run := &journeyRun{
		Agent: agent.name, Command: "go test -tags=e2e ./tests/e2e -run '^TestNativeAgentJourney$' -count=1 -timeout=10m -v",
		Fingerprint: sourceFingerprint(t, root), Revision: "WORKTREE",
		StartedAt: time.Now().UTC(), Size: [2]int{120, 40}, Stage: "setup",
	}
	t.Cleanup(func() {
		if after := sourceFingerprint(t, root); after != run.Fingerprint {
			t.Error("source changed during native E2E run")
		}
		writeJourneyRun(t, run, artifacts)
	})
	return run, artifacts
}

func writeJourneyRun(t *testing.T, run *journeyRun, artifacts string) {
	t.Helper()
	run.FinishedAt = time.Now().UTC()
	run.Status = "passed"
	if t.Failed() {
		run.Status = "failed"
	}
	data, err := json.MarshalIndent(run, "", "  ")
	if err != nil {
		t.Errorf("encode run: %v", err)
		return
	}
	if writeErr := os.WriteFile(filepath.Join(artifacts, "result.json"), append(data, '\n'), 0o600); writeErr != nil {
		t.Errorf("record run: %v", writeErr)
	}
}

func registerTerminalCleanup(t *testing.T, terminal *tuitest.Client, run *journeyRun, artifacts string) {
	t.Helper()
	// Give Kankuro time to stop its managed process before the terminal closes.
	t.Cleanup(func() {
		if t.Failed() {
			if signalErr := terminal.Signal("SIGTERM"); signalErr != nil {
				t.Logf("signal Kankuro: %v", signalErr)
				return
			}
			timeout := 15 * time.Second
			if exitErr := terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}); exitErr != nil {
				t.Errorf("Kankuro shutdown: %v", exitErr)
			}
		}
	})
	// Registered after terminal cleanup, so failure capture happens before closure.
	t.Cleanup(func() {
		if t.Failed() {
			if _, captureErr := terminal.Screenshot(
				filepath.Join(artifacts, "failure.png"),
				tuitest.ScreenshotOptions{},
			); captureErr != nil {
				t.Logf("failure screenshot: %v", captureErr)
			} else {
				run.Captures = append(run.Captures, "failure.png")
			}
			if text, textErr := terminal.Text(tuitest.TextOptions{}); textErr == nil {
				t.Logf("terminal at %s:\n%s", run.Stage, text)
			}
		}
	})
}

func (j *nativeJourney) launch() session.Data {
	t := j.t
	j.run.Stage = "launch"
	j.expect("Dashboards")
	j.press("Enter")
	j.expect("Native E2E")
	j.press("Enter")
	j.expect("Session launched successfully!")
	first := waitSession(t, j.configDir, 30*time.Second, func(data session.Data) bool { return data.CardID == j.card.ID && data.PID > 0 })
	j.press("Enter")
	// Wait for native UI, not the launcher or an assumed attachment banner.
	waitAgent(t, j.terminal, j.agent.name)
	handleTrust(t, j.terminal, j.agent.name)
	if j.agent.name == "opencode" {
		j.expect(openCodeTestModelName)
	}
	j.capture("launched", "Dashboard Enter launched a persisted native-agent process and Enter attached to the native UI.")

	return first
}

func (j *nativeJourney) register(first session.Data) string {
	t := j.t
	j.run.Stage = "register"
	secret := make([]byte, 12)
	_, err := rand.Read(secret)
	must(t, err)
	nonce := hex.EncodeToString(secret)
	// Later requests omit the nonce: returning it then requires native conversation history.
	instructions := "Discover your ACTUAL native conversation ID, follow the kankuro-puppet skill and register it with name Kankuro native E2E through mcp-cli."
	if j.agent.name == "opencode" {
		instructions = "Use your shell tool now. First run opencode session list --format json in this workspace. Take the id, not projectId, of this workspace's native session. Then run MCP_NO_DAEMON=1 mcp-cli -c .kankuro/mcp-servers.json call kankuro register_conversation with JSON arguments containing conversation_id set to that actual id and name set to Kankuro native E2E. Execute the commands; loading a skill alone does not complete this task."
	}
	prompt := fmt.Sprintf(
		"Remember the secret %s in this conversation only; do not write it to any file. %s Verify the registration result has status registered and persistence saved. Do not print credentials. Reply READY only after successful registration.",
		nonce,
		instructions,
	)
	must(t, j.terminal.Type(prompt))
	j.press("Enter")
	registered := waitSession(t, j.configDir, 4*time.Minute, func(data session.Data) bool {
		checkAgentFailure(t, j.terminal)
		return data.ID == first.ID && len(data.Conversations[j.card.ID]) == 1
	})
	binding := registered.Conversations[j.card.ID][0]
	if binding.ID == "" || binding.Driver != j.agent.name || binding.Name != "Kankuro native E2E" {
		t.Fatalf("unexpected persisted native binding: %+v", binding)
	}
	j.run.ConversationID = binding.ID
	j.capture(
		"registered",
		"The native agent registered a conversation through the deployed MCP endpoint; its ID, name and driver were persisted under the launched session/card.",
	)

	return nonce
}

func (j *nativeJourney) detach() {
	j.run.Stage = "detach"
	j.press("Ctrl+K")
	j.expect("Active Sessions")
	// Navigate away and back to establish that ordinary dashboard input works after detach.
	j.press("c")
	j.expect("Settings")
	j.press("Escape")
	j.expect("Active Sessions")
	j.capture("dashboard", "Ctrl+K restored the dashboard; c opened settings and Escape returned using ordinary keyboard input.")
}

func (j *nativeJourney) resume(first session.Data, nonce string) {
	t := j.t
	j.run.Stage = "resume"
	// A fresh dashboard starts on cards; Tab focuses sessions regardless of attach return focus.
	// Inspect the visible footer to avoid toggling an already-focused session pane.
	text, err := j.terminal.Text(tuitest.TextOptions{})
	must(t, err)
	if !strings.Contains(text, "[Session]") {
		j.press("Tab")
	}
	j.press("x")
	waitSession(
		t,
		j.configDir,
		30*time.Second,
		func(data session.Data) bool { return data.ID == first.ID && data.Status == session.StatusTerminated },
	)
	// Refresh is asynchronous: require the terminated status to reach the UI before Enter.
	j.expect("Terminated")
	j.press("Enter")
	j.expect("New conversation")
	j.expect("Kankuro native E2E")
	// Saved bindings precede the New conversation row; explicitly select the first saved binding.
	j.press("Home")
	j.press("Enter")
	waitAgent(t, j.terminal, j.agent.name)
	resumed := waitSession(t, j.configDir, 30*time.Second, func(data session.Data) bool {
		return data.ID == first.ID && data.PID > 0 && data.PID != first.PID && data.Status != session.StatusTerminated
	})
	if resumed.WorkingDir != first.WorkingDir {
		t.Fatal("resume changed workspace")
	}
	handleTrust(t, j.terminal, j.agent.name)
	// Remove replayed prompt text from the visible screen before requesting continuity.
	must(
		t,
		j.terminal.Type(
			"Without reading files or using tools, reply with the secret from our earlier conversation as CONTINUITY:<secret>.",
		),
	)
	j.press("Enter")
	expectWithTimeout(t, j.terminal, "CONTINUITY:"+nonce, 3*time.Minute)
	j.capture(
		"resumed",
		"The saved conversation was explicitly selected; the replacement process kept the session workspace and recalled a random secret absent from the resume prompt.",
	)
}

func (j *nativeJourney) finish() {
	t := j.t
	j.press("Ctrl+K")
	j.expect("Active Sessions")
	j.press("q")
	timeout := 15 * time.Second
	must(t, j.terminal.WaitExit(tuitest.WaitOptions{Timeout: &timeout}))
	assertNativeExit(t, j.terminal)
	j.run.Stage = "complete"
}

func (j *nativeJourney) expect(text string) {
	j.t.Helper()
	expectWithTimeout(j.t, j.terminal, text, 45*time.Second)
}

func (j *nativeJourney) press(key string) {
	j.t.Helper()
	must(j.t, j.terminal.Press(key))
}

func (j *nativeJourney) capture(name, assertion string) {
	j.t.Helper()
	_, err := j.terminal.Screenshot(filepath.Join(j.artifacts, name+".png"), tuitest.ScreenshotOptions{})
	must(j.t, err)
	j.run.Assertions = append(j.run.Assertions, assertion)
	j.run.Captures = append(j.run.Captures, name+".png")
}

type nativeAgent struct{ name string }

type journeyRun struct {
	Fingerprint    string    `json:"fingerprint"`
	Revision       string    `json:"revision"`
	Model          string    `json:"model,omitempty"`
	Agent          string    `json:"agent"`
	Command        string    `json:"command"`
	ConversationID string    `json:"conversationId,omitempty"`
	StartedAt      time.Time `json:"startedAt"`
	FinishedAt     time.Time `json:"finishedAt"`
	Status         string    `json:"status"`
	Stage          string    `json:"stage"`
	Size           [2]int    `json:"size"`
	Assertions     []string  `json:"assertions"`
	Captures       []string  `json:"captures"`
}

func selectAgent(t *testing.T) nativeAgent {
	t.Helper()
	for _, name := range []string{"opencode", "codex", "claude"} {
		if _, err := exec.LookPath(name); err == nil {
			return nativeAgent{name: name}
		}
	}
	t.Skip("no opencode, codex or claude executable available")
	return nativeAgent{}
}

func expectWithTimeout(t *testing.T, terminal *tuitest.Client, text string, timeout time.Duration) {
	t.Helper()
	must(t, terminal.GetByText(text, tuitest.TextSelectorOptions{}).First().Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}))
}

func must(t *testing.T, err error) {
	t.Helper()
	if err != nil {
		t.Fatal(err)
	}
}

// waitSession polls atomic application records, never treats terminal silence as completion.
func waitSession(t *testing.T, configDir string, timeout time.Duration, ready func(session.Data) bool) session.Data {
	t.Helper()
	deadline := time.NewTimer(timeout)
	defer deadline.Stop()
	tick := time.NewTicker(100 * time.Millisecond)
	defer tick.Stop()
	var latest session.Data
	for {
		paths, err := filepath.Glob(filepath.Join(configDir, "sessions", "*.json"))
		must(t, err)
		for _, path := range paths {
			bytes, readErr := os.ReadFile(path)
			if readErr != nil {
				continue
			}
			var data session.Data
			if json.Unmarshal(bytes, &data) != nil {
				continue
			}
			latest = data
			if ready(data) {
				return data
			}
		}
		select {
		case <-deadline.C:
			t.Fatalf("session state timed out: id=%s status=%s conversations=%v", latest.ID, latest.Status, latest.Conversations)
		case <-tick.C:
		}
	}
}

func handleTrust(t *testing.T, terminal *tuitest.Client, agent string) {
	t.Helper()
	// Trust prompts differ by CLI. Auto-confirm only known workspace prompts,
	// leaving login/model errors to fail the journey rather than skipping it.
	text, err := terminal.Text(tuitest.TextOptions{})
	must(t, err)
	if agent == "codex" && strings.Contains(text, "trust") {
		must(t, terminal.Press("Enter"))
	}
	if agent == "claude" && strings.Contains(text, "trust") {
		must(t, terminal.Press("Enter"))
	}
}

func waitAgent(t *testing.T, terminal *tuitest.Client, agent string) {
	t.Helper()
	pattern := "ctrl\\+p commands"
	switch agent {
	case "codex":
		pattern = "(?i)codex|trust this"
	case "claude":
		pattern = "(?i)claude|trust this"
	}
	timeout := 45 * time.Second
	must(
		t,
		terminal.GetByText("Session launched successfully!", tuitest.TextSelectorOptions{}).
			Wait(tuitest.LocatorWaitOptions{State: tuitest.Hidden, Timeout: &timeout}),
	)
	must(
		t,
		terminal.GetByText(pattern, tuitest.TextSelectorOptions{Regex: true}).
			First().
			Expect(tuitest.LocatorExpectOptions{Timeout: &timeout}),
	)
	checkAgentFailure(t, terminal)
}

func checkAgentFailure(t *testing.T, terminal *tuitest.Client) {
	t.Helper()
	text, err := terminal.Text(tuitest.TextOptions{})
	must(t, err)
	for _, failure := range []string{"Free limit reached", "Authentication required", "Invalid API key", "Server process exited", "Failed to start server"} {
		if strings.Contains(text, failure) {
			t.Fatalf("native agent reported %q", failure)
		}
	}
}

tests/e2e/opencode_test.go.source:
//go:build e2e

package e2e_test

import (
	"bytes"
	"context"
	"encoding/json"
	"net"
	"os"
	"os/exec"
	"path/filepath"
	"reflect"
	"strconv"
	"testing"
	"time"
)

const (
	openCodeTestModel     = "openrouter/openrouter/free"
	openCodeTestModelName = "Free Models Router"
)

type openCodeCredential struct {
	Active        bool   `json:"active"`
	IntegrationID string `json:"integrationID"`
	Value         any    `json:"value"`
}

// Use the installed CLI's supported transfer format, keeping secrets in memory.
// Copying auth.json alone misses credentials migrated into OpenCode's v2 database.
func copyOpenCodeCredentials(t *testing.T, environment map[string]string) {
	t.Helper()
	exported := openCodeCommand(t, nil, nil, "auth", "export")
	var original []openCodeCredential
	must(t, json.Unmarshal(exported, &original))
	// A standalone invocation closes its private server after import/export.
	openCodeCommand(t, environment, exported, "auth", "import", "--standalone")
	imported := openCodeCommand(t, environment, nil, "auth", "export", "--standalone")
	var copied []openCodeCredential
	must(t, json.Unmarshal(imported, &copied))
	configureOpenCodeService(t, environment)
	if !sameOpenCodeCredentials(original, copied) {
		t.Fatal("isolated OpenCode credential import differs from the configured integrations")
	}
}

// Compare by integration/value rather than IDs or ordering chosen by import.
// Never include credential material in assertion errors.
func sameOpenCodeCredentials(original, copied []openCodeCredential) bool {
	if len(original) != len(copied) {
		return false
	}
	remaining := append([]openCodeCredential(nil), copied...)
	for _, credential := range original {
		found := -1
		for i, candidate := range remaining {
			if reflect.DeepEqual(credential, candidate) {
				found = i
				break
			}
		}
		if found < 0 {
			return false
		}
		remaining = append(remaining[:found], remaining[found+1:]...)
	}
	return true
}

func openCodeCommand(t *testing.T, environment map[string]string, input []byte, arguments ...string) []byte {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), time.Minute)
	defer cancel()
	command := exec.CommandContext(ctx, "opencode", arguments...)
	command.Env = os.Environ()
	for key, value := range environment {
		command.Env = append(command.Env, key+"="+value)
	}
	if home := environment["HOME"]; home != "" {
		command.Dir = home
	}
	command.Stdin = bytes.NewReader(input)
	// Do not capture stderr or print stdout: either can include exported secrets.
	output, err := command.Output()
	if err != nil {
		t.Fatalf("OpenCode %v failed: %v", arguments, err)
	}
	return output
}

func configureOpenCodeWorkspace(t *testing.T, workspace string) string {
	t.Helper()
	model := openCodeTestModel
	settings := map[string]any{"permission": "allow"}
	if model != "" {
		settings["model"] = model
	}
	encoded, err := json.Marshal(settings)
	must(t, err)
	must(t, os.WriteFile(filepath.Join(workspace, "opencode.json"), encoded, 0o600))
	return model
}

// Service endpoints are runtime state: a copied port can target the user's live server.
func copyOpenCodeConfiguration(t *testing.T, source, destination string) {
	t.Helper()
	entries, err := os.ReadDir(source)
	if os.IsNotExist(err) {
		return
	}
	must(t, err)
	for _, entry := range entries {
		if entry.Name() == "service.json" {
			continue
		}
		copyConfiguration(t, filepath.Join(source, entry.Name()), filepath.Join(destination, entry.Name()))
	}
}

func configureOpenCodeService(t *testing.T, environment map[string]string) {
	t.Helper()
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	must(t, err)
	address, ok := listener.Addr().(*net.TCPAddr)
	if !ok {
		t.Fatal("test listener did not have a TCP address")
	}
	port := strconv.Itoa(address.Port)
	must(t, listener.Close())
	openCodeCommand(t, environment, nil, "service", "set", "port", port)
	t.Cleanup(func() { openCodeCommand(t, environment, nil, "service", "stop") })
}

tests/e2e/provenance_test.go.source:
//go:build e2e

package e2e_test

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"strings"
	"testing"
)

// sourceFingerprint uses the Appedia collector's canonical source inventory.
// Images/results are not source inputs; documentation does not affect this hash.
func sourceFingerprint(t *testing.T, root string) string {
	t.Helper()
	exclude := []string{".agents", ".kankuro", "appedia", "kankuro_skills/create-appedia", "kankuro_skills/create-appediff", "tmp"}
	skip := []string{
		".git",
		".hg",
		".svn",
		".maintenance",
		"node_modules",
		"vendor",
		"__pycache__",
		".venv",
		"venv",
		"appedia",
		"appediff",
		".next",
	}
	command := exec.Command("git", "ls-files", "-co", "--exclude-standard", "-z")
	command.Dir = root
	output, err := command.Output()
	must(t, err)
	sources := make(map[string]string)
	for path := range strings.SplitSeq(string(output), "\x00") {
		if !isSource(path) || excludedSource(path, append(skip, exclude...)) {
			continue
		}
		info, statErr := os.Lstat(filepath.Join(root, path))
		if os.IsNotExist(statErr) {
			continue
		}
		must(t, statErr)
		if !info.Mode().IsRegular() {
			continue
		}
		bytes, readErr := os.ReadFile(filepath.Join(root, path))
		must(t, readErr)
		sum := sha256.Sum256(bytes)
		sources[path] = hex.EncodeToString(sum[:])
	}
	slices.Sort(exclude)
	// Map keys are sorted by encoding/json, matching Python's sort_keys=True.
	canonical, err := json.Marshal(map[string]any{"sources": sources, "exclude": exclude})
	must(t, err)
	sum := sha256.Sum256(canonical)
	return hex.EncodeToString(sum[:])
}

func excludedSource(path string, excluded []string) bool {
	directory := filepath.ToSlash(filepath.Dir(path))
	for part := range strings.SplitSeq(directory, "/") {
		if slices.Contains(excluded, part) {
			return true
		}
	}
	return false
}

func isSource(path string) bool {
	extensions := []string{".go", ".py", ".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".mts", ".cts", ".tf"}
	manifests := []string{
		"go.mod",
		"go.sum",
		"package.json",
		"package-lock.json",
		"pnpm-lock.yaml",
		"yarn.lock",
		"pyproject.toml",
		"uv.lock",
		"requirements.txt",
	}
	return slices.Contains(extensions, filepath.Ext(path)) || slices.Contains(manifests, filepath.Base(path))
}
